function writeI32(view, offset, value) {
  view.setInt32(offset, value | 0, true);
}
function writeU32(view, offset, value) {
  view.setUint32(offset, value >>> 0, true);
}
function writeU8(view, offset, value) {
  view.setUint8(offset, value & 0xff);
}
function readI32(view, offset) {
  return view.getInt32(offset, true);
}
function readU32(view, offset) {
  return view.getUint32(offset, true);
}
function readU8(view, offset) {
  return view.getUint8(offset);
}

test("header declares HUD post-update pure helpers ABI v5 and tracked paths exist", () => {
  assert.ok(existsSync(header));
  assert.ok(existsSync(source));
  const h = readFileSync(header, "utf8");
  assert.match(h, /ISAAC_HUD_POST_UPDATE_PURE_HELPERS_ABI_VERSION = 39/);
  assert.match(h, /isaac_hud_post_update_try_pure/);
  assert.match(h, /isaac_stat_hud_countdown_tick/);
  assert.match(h, /0x009a2b30/);
  /* v7 F3 re-derivation: full three-move swap, no free residual. */
  assert.match(h, /three-move std::swap/);
  assert.match(h, /0x0083b9ec/);
  assert.match(h, /structurally DEAD|structurally dead/);
  assert.match(h, /NO host free residual|NOT a free residual/);
  assert.doesNotMatch(h, /that is the host free residual/);
  assert.doesNotMatch(h, /host frees it/);
  assert.match(h, /isaac_history_hud_slot_compact_loop_continue/);
  /* v7 F5 snapshot contract: the PE reads both Manager fields post-loop. */
  assert.match(h, /0x009a2b5a/);
  assert.match(h, /0x0084c178/);
  assert.match(h, /0x009a2bb2/);
  assert.match(h, /isaac_hud_post_update_snapshot_safe/);
  assert.match(h, /recapture both\s+fields|recapture both fields/);
  assert.match(h, /0x0083b280/);
  assert.match(h, /0x0083b850/);
  assert.match(h, /0x0084c170/);
  assert.match(h, /isaac_history_hud_recompute_try_pure/);
  assert.match(h, /isaac_history_hud_recompute_all_try_pure/);
  assert.match(h, /isaac_history_hud_twin_dirty_needed/);
  assert.match(h, /isaac_history_hud_get_player_idx_try_pure/);
  assert.match(h, /isaac_history_hud_get_player_idx_resolve/);
  assert.match(h, /isaac_stat_hud_apply_owner_flag/);
  assert.match(h, /isaac_stat_hud_player_vector_count/);
  assert.match(h, /0x009be080/);
  assert.match(h, /0x0084ca00/);
  assert.match(h, /0x0083bbc0/);
  assert.match(h, /0x00aef15c/);
  assert.match(h, /0x0090b100/);
  assert.match(h, /0x4b3d8/);
  /* ABI v36 wires try_pure into safe Update HUD sites; nested residual stays host. */
  assert.match(h, /ABI v36 wires isaac_hud_post_update_try_pure|wires isaac_hud_post_update_try_pure/);
  assert.equal(HUD_POST_UPDATE_PURE_ABI_VERSION, 39);
  assert.equal(STAT_HUD_COLLECTIBLE_ID, 0x1f2);
  assert.equal(STAT_HUD_RECOMPUTE_FLAGS, 0xfffffeff >>> 0);
  assert.equal(HUD_HOST_VA_HISTORY_RECOMPUTE, 0x0083b280);
  assert.equal(HUD_HOST_VA_HISTORY_RECOMPUTE_ALL, 0x0083b850);
  assert.equal(HUD_HOST_VA_HISTORY_GET_PLAYER_IDX, 0x0083bbc0);
  assert.equal(HUD_HOST_VA_FIRST_COLLECTIBLE_OWNER, 0x009be080);
  assert.equal(HUD_HOST_VA_STAT_RECOMPUTE_STATS, 0x0084ca00);
  assert.equal(HUD_HOST_VA_CRT_FREE, 0x00aef15c);
  assert.equal(HUD_HOST_VA_NETPLAY_IS_IDX_LOCAL, 0x0090b100);
  assert.equal(HISTORY_HUD_TWIN_PTR_OFFSET, 0x1e6c);
  assert.equal(HISTORY_HUD_CHARACTER_TYPE_OFFSET, 0x13c0);
  assert.equal(HISTORY_HUD_TWIN_CHAR_A, 0x1d);
  assert.equal(HISTORY_HUD_TWIN_CHAR_B, 0x26);
  assert.equal(HISTORY_GET_PLAYER_IDX_NETPLAY_EMBED_OFF, 0x4b3d8);
  assert.equal(HISTORY_GET_PLAYER_IDX_PLAYER_NET_IDX_OFF, 0x1618);
  assert.equal(HISTORY_GET_PLAYER_IDX_PLAYER_FIELD_2C_OFF, 0x2c);
  assert.equal(HISTORY_GET_PLAYER_IDX_PLAYER_FIELD_3BC_OFF, 0x3bc);
  assert.equal(HISTORY_GET_PLAYER_IDX_PLAYER_CHAR_TYPE_OFF, 0x13c0);
  assert.equal(HISTORY_GET_PLAYER_IDX_REJECT_CHAR, 0x28);
});

test("v8 byte-parameter sweep: no uint8_t scalar parameter remains", () => {
  /* A uint8_t SCALAR parameter lets the compiler assume the high bits are
     already clear, and the Wasm ABI never narrows an i32 argument, so the
     shipped export tests the full word where the PE tests a byte. All seven
     such exports in this header probed DIVERGENT at 0x100 before v8.
     Pointer parameters (uint8_t*) and struct fields are layout and stay. */
  const stripped = readFileSync(header, "utf8").replace(/\/\*[\s\S]*?\*\//g, "");
  const protos = [...stripped.matchAll(/isaac_[a-z0-9_]+\s*\(([^;{]*?)\)\s*;/g)];
  assert.ok(protos.length >= 60, `expected many prototypes, got ${protos.length}`);
  for (const m of protos) {
    assert.doesNotMatch(
      `${m[1]})`,
      /\buint8_t\s+[a-z_0-9]+\s*[,)]/,
      `uint8_t scalar parameter in: ${m[0].replace(/\s+/g, " ")}`,
    );
  }
});

test("HUD post-update pure JS oracle matches recovered control flow", () => {
  assert.equal(hudPlayerHudOccupiedMask([0, 0, 0, 0, 0, 0, 0, 0]), 0);
  assert.equal(hudPlayerHudOccupiedMask([1, 0, 0, 0, 0, 0, 0, 0]), 1);
  assert.equal(hudPlayerHudOccupiedMask([0, 0, 0xabc, 0, 0, 0, 0, 0]), 4);

  assert.equal(hudHistoryBlockNeeded(0), false);
  assert.equal(hudHistoryBlockNeeded(-1), false);
  assert.equal(hudHistoryBlockNeeded(1), true);

  assert.equal(hudHistoryRecomputeAllNeeded(0), true);
  assert.equal(hudHistoryRecomputeAllNeeded(1), false);
  assert.equal(hudHistoryFlagSet(0), 1);

  assert.equal(hudHistorySlotRecomputeNeeded(0), false);
  assert.equal(hudHistorySlotRecomputeNeeded(0x80), true);

  assert.equal(statHudPostUpdateNeeded(0), false);
  assert.equal(statHudPostUpdateNeeded(1), true);

  assert.deepEqual(
    tryHudPostUpdatePure({
      playerHudOccupiedMask: 0,
      managerHistoryCount: 0,
      managerStatFlag: 0,
    }),
    { hostRequired: false },
  );
  assert.deepEqual(
    tryHudPostUpdatePure({
      playerHudOccupiedMask: 1,
      managerHistoryCount: 0,
      managerStatFlag: 0,
    }),
    { hostRequired: true },
  );
  assert.deepEqual(
    tryHudPostUpdatePure({
      playerHudOccupiedMask: 0,
      managerHistoryCount: 2,
      managerStatFlag: 0,
    }),
    { hostRequired: true },
  );
  assert.deepEqual(
    tryHudPostUpdatePure({
      playerHudOccupiedMask: 0,
      managerHistoryCount: 0,
      managerStatFlag: 1,
    }),
    { hostRequired: true },
  );

  const ticked = statHudCountdownTick({
    group0: [0, 1, 2, -1, 5, 0, 0, 0, 0, 0],
    group1: [3, 0, -5, 1, 0, 0, 0, 0, 0, 0],
  });
  assert.deepEqual(ticked.group0, [0, 0, 1, -1, 4, 0, 0, 0, 0, 0]);
  assert.deepEqual(ticked.group1, [2, 0, -5, 0, 0, 0, 0, 0, 0, 0]);

  // base_at_0x13c at index 5 so first counter (base-5) is index 0
  const pad = 5;
  const mem = Array(pad + STAT_HUD_COUNTDOWN_GROUP_STRIDE_DWORDS + 0x29).fill(0);
  for (let i = 0; i < STAT_HUD_COUNTDOWN_PER_GROUP; i += 1) {
    const slot =
      i === 0
        ? pad - STAT_HUD_COUNTDOWN_INNER_STRIDE_DWORDS
        : pad + (i - 1) * STAT_HUD_COUNTDOWN_INNER_STRIDE_DWORDS;
    mem[slot] = i + 1;
  }
  const after = statHudCountdownTickAt(mem, pad);
  for (let i = 0; i < STAT_HUD_COUNTDOWN_PER_GROUP; i += 1) {
    const slot =
      i === 0
        ? pad - STAT_HUD_COUNTDOWN_INNER_STRIDE_DWORDS
        : pad + (i - 1) * STAT_HUD_COUNTDOWN_INNER_STRIDE_DWORDS;
    assert.equal(after[slot], i);
  }
});

test("HistoryHUD::Recompute pure-complete shell (helpers ABI v2 retained)", () => {
  // idx > 1 → pure no-op
  assert.deepEqual(
    tryHistoryHudRecomputePure({ idx: 2, immediate: 1, playerPtr: 0x1000 }),
    { hostRequired: false },
  );
  assert.deepEqual(
    tryHistoryHudRecomputePure({ idx: 0xffffffff, immediate: 0, playerPtr: 1 }),
    { hostRequired: false },
  );
  // null player → pure no-op
  assert.deepEqual(
    tryHistoryHudRecomputePure({ idx: 0, immediate: 1, playerPtr: 0 }),
    { hostRequired: false },
  );
  // immediate == 0 → pure dirty store
  assert.deepEqual(
    tryHistoryHudRecomputePure({ idx: 0, immediate: 0, playerPtr: 0xabc }),
    { hostRequired: false, dirty: 1 },
  );
  assert.deepEqual(
    tryHistoryHudRecomputePure({ idx: 1, immediate: 0, playerPtr: 0xdef }),
    { hostRequired: false, dirty: 1 },
  );
  // immediate != 0 + valid slot → host
  assert.deepEqual(
    tryHistoryHudRecomputePure({ idx: 0, immediate: 1, playerPtr: 0xabc }),
    { hostRequired: true },
  );
  assert.deepEqual(
    tryHistoryHudRecomputePure({ idx: 1, immediate: 0xff, playerPtr: 1 }),
    { hostRequired: true },
  );
  assert.equal(historyHudSlotDirtySet(0), 1);
});

test("HistoryHUD RecomputeAll-shaped pure peels (helpers ABI v3)", () => {
  // pure-complete shell
  assert.deepEqual(
    tryHistoryHudRecomputeAllPure({ slot0Player: 0, slot1Player: 0, playerCount: 0 }),
    { hostRequired: false },
  );
  assert.deepEqual(
    tryHistoryHudRecomputeAllPure({ slot0Player: 1, slot1Player: 0, playerCount: 0 }),
    { hostRequired: true },
  );
  assert.deepEqual(
    tryHistoryHudRecomputeAllPure({ slot0Player: 0, slot1Player: 0xabc, playerCount: 0 }),
    { hostRequired: true },
  );
  assert.deepEqual(
    tryHistoryHudRecomputeAllPure({ slot0Player: 0, slot1Player: 0, playerCount: 1 }),
    { hostRequired: true },
  );
  assert.deepEqual(
    tryHistoryHudRecomputeAllPure({ slot0Player: 0, slot1Player: 0, playerCount: -1 }),
    { hostRequired: true },
  );

  // reverse walk: start cursor=2 off=0x14 → cursor=1 off=0 continue; then stop
  let step = historyHudReverseWalkStep(
    HISTORY_HUD_REVERSE_WALK_START_CURSOR,
    HISTORY_HUD_REVERSE_WALK_START_OFFSET,
  );
  assert.equal(step.cursor, 1);
  assert.equal(step.offset, 0);
  assert.equal(step.continue, true);
  step = historyHudReverseWalkStep(step.cursor, step.offset);
  assert.equal(step.cursor, 0);
  assert.equal(step.offset, (0 - HISTORY_HUD_SLOT_STRIDE) >>> 0);
  assert.equal(step.continue, false);

  assert.equal(historyHudPlayerIdxInvalid(-1), true);
  assert.equal(historyHudPlayerIdxInvalid(0), false);
  assert.equal(historyHudPlayerIdxInvalid(1), false);
  assert.equal(historyHudPlayerIdxInvalid(0x80000000), true); // signed neg

  assert.equal(historyHudSlotCompactNeeded(2), false);
  assert.equal(historyHudSlotCompactNeeded(1), true);
  assert.equal(historyHudSlotCompactNeeded(0), true);

  // v7: the compact step is a full three-move std::swap of the whole slot.
  // PE truth: 0x0083b936/0x0083b93c store the SAVED dst scalars into src and
  // the move-3 adopt at 0x0083b9ec..0x0083b9f4 stores dst's FORMER triple
  // into src. Nothing is freed (the 0x0083b951 teardown branch is dead).
  const swapped = historyHudSlotCompactSwap(
    { player: 0x1234, dirty: 1, listBegin: 0x10, listEnd: 0x20, listCap: 0x30 },
    { player: 0xdead, dirty: 0, listBegin: 0xaa, listEnd: 0xbb, listCap: 0xcc },
  );
  assert.equal(swapped.dst.player, 0xdead);
  assert.equal(swapped.dst.dirty, 0);
  assert.equal(swapped.dst.listBegin, 0xaa); // src triple moved down
  assert.equal(swapped.dst.listEnd, 0xbb);
  assert.equal(swapped.dst.listCap, 0xcc);
  assert.equal(swapped.src.player, 0x1234); // swap, NOT zero-fill
  assert.equal(swapped.src.dirty, 1);
  assert.equal(swapped.src.listBegin, 0x10); // src ADOPTS dst's old triple
  assert.equal(swapped.src.listEnd, 0x20);   // (0x0083b9ec adopt, NOT zeroed,
  assert.equal(swapped.src.listCap, 0x30);   //  NOT freed)
  assert.equal(swapped.dstOldList.listBegin, 0x10); // == what src now holds
  assert.equal(swapped.dstOldList.listEnd, 0x20);
  assert.equal(swapped.dstOldList.listCap, 0x30);
  // Negative result pinned: the old "src triple emptied + host free" story
  // is refuted — a dirty destination slot's triple must survive in src.
  const swapBack = historyHudSlotCompactSwap(swapped.dst, swapped.src);
  assert.deepEqual(swapBack.dst, {
    player: 0x1234, dirty: 1, listBegin: 0x10, listEnd: 0x20, listCap: 0x30,
  });
  assert.deepEqual(swapBack.src, {
    player: 0xdead, dirty: 0, listBegin: 0xaa, listEnd: 0xbb, listCap: 0xcc,
  });
  // Adjacent slots can never satisfy the address-equality skip.
  assert.equal(
    historyHudSlotCompactTripleMoveNeeded(
      HISTORY_HUD_SLOT_LIST_BEGIN_OFFSET,
      HISTORY_HUD_SLOT_LIST_BEGIN_OFFSET + HISTORY_HUD_SLOT_STRIDE,
    ),
    true,
  );
  assert.equal(historyHudSlotCompactTripleMoveNeeded(0x100, 0x100), false);

  // v7 compact loop-continue (0x0083bab2): signed `< 2` on the incremented
  // index. Entered at cursor 1 the body runs exactly once (1+1 = 2 exits).
  assert.equal(historyHudSlotCompactLoopContinue(1), true);
  assert.equal(historyHudSlotCompactLoopContinue(2), false);
  assert.equal(historyHudSlotCompactLoopContinue(3), false);
  assert.equal(historyHudSlotCompactLoopContinue(-1), true); // SIGNED jl
  assert.equal(historyHudSlotCompactLoopContinue(0x80000000), true);

  // v7 F5 snapshot-safety: only an empty low-8 mask keeps pre-loop
  // history/stat snapshots valid at the PE read points.
  assert.equal(hudPostUpdateSnapshotSafe(0), true);
  assert.equal(hudPostUpdateSnapshotSafe(1), false);
  assert.equal(hudPostUpdateSnapshotSafe(0x80), false);
  assert.equal(hudPostUpdateSnapshotSafe(0x100), true); // low byte only
  assert.equal(hudPostUpdateSnapshotSafe(0xff00), true);

  assert.equal(historyHudTwinCharEligible(0x1d), true);
  assert.equal(historyHudTwinCharEligible(0x26), true);
  assert.equal(historyHudTwinCharEligible(0), false);
  assert.equal(historyHudTwinCharEligible(3), false);

  assert.equal(
    historyHudTwinDirtyNeeded({
      twinPtr: 0x1000,
      characterType: 0x1d,
      twinIdx: 0,
      slotPlayerAtTwinIdx: 0x2000,
    }),
    true,
  );
  assert.equal(
    historyHudTwinDirtyNeeded({
      twinPtr: 0x1000,
      characterType: 0x26,
      twinIdx: 1,
      slotPlayerAtTwinIdx: 1,
    }),
    true,
  );
  assert.equal(
    historyHudTwinDirtyNeeded({
      twinPtr: 0,
      characterType: 0x1d,
      twinIdx: 0,
      slotPlayerAtTwinIdx: 1,
    }),
    false,
  );
  assert.equal(
    historyHudTwinDirtyNeeded({
      twinPtr: 1,
      characterType: 3,
      twinIdx: 0,
      slotPlayerAtTwinIdx: 1,
    }),
    false,
  );
  assert.equal(
    historyHudTwinDirtyNeeded({
      twinPtr: 1,
      characterType: 0x1d,
      twinIdx: 2,
      slotPlayerAtTwinIdx: 1,
    }),
    false,
  );
  assert.equal(
    historyHudTwinDirtyNeeded({
      twinPtr: 1,
      characterType: 0x1d,
      twinIdx: 0xffffffff, // unsigned > 1
      slotPlayerAtTwinIdx: 1,
    }),
    false,
  );
  assert.equal(
    historyHudTwinDirtyNeeded({
      twinPtr: 1,
      characterType: 0x1d,
      twinIdx: 0,
      slotPlayerAtTwinIdx: 0,
    }),
    false,
  );

  assert.equal(historyHudListByteSize(0x1000, 0x1000 + 0x28 * 3), 0x28 * 3);
  assert.equal(historyHudListByteSize(0x1000, 0x1000 + 0x28 * 3 + 5), 0x28 * 3);
  assert.equal(historyHudListByteSize(0x2000, 0x1000), 0);
  assert.equal(historyHudListFreeNeeded(0), false);
  assert.equal(historyHudListFreeNeeded(0xabc), true);

  assert.equal(HISTORY_HUD_SLOT_COUNT, 2);
  assert.equal(HISTORY_HUD_SLOT_STRIDE, 0x14);
  assert.equal(HISTORY_HUD_LIST_ELEM_STRIDE, 0x28);
  assert.equal(HISTORY_HUD_PLAYER_LIST_GAME_OFFSET, 0x1baa8);
});

test("GetPlayerIdx-shaped pure peels (helpers ABI v4)", () => {
  // netplay range empty
  assert.equal(historyHudGetPlayerIdxNetplayRangeEmpty(0, 0), true);
  assert.equal(historyHudGetPlayerIdxNetplayRangeEmpty(0x1000, 0x1000), true);
  assert.equal(historyHudGetPlayerIdxNetplayRangeEmpty(0x1000, 0x1004), false);

  // eligibility
  assert.equal(
    historyHudGetPlayerIdxPlayerEligible({ field2c: 0, field3bc: 0, charType: 0 }),
    true,
  );
  assert.equal(
    historyHudGetPlayerIdxPlayerEligible({ field2c: 0, field3bc: 0, charType: 3 }),
    true,
  );
  assert.equal(
    historyHudGetPlayerIdxPlayerEligible({ field2c: 1, field3bc: 0, charType: 0 }),
    false,
  );
  assert.equal(
    historyHudGetPlayerIdxPlayerEligible({ field2c: 0, field3bc: 1, charType: 0 }),
    false,
  );
  assert.equal(
    historyHudGetPlayerIdxPlayerEligible({
      field2c: 0,
      field3bc: 0,
      charType: HISTORY_GET_PLAYER_IDX_REJECT_CHAR,
    }),
    false,
  );

  // resolve: exact match
  assert.deepEqual(
    historyHudGetPlayerIdxResolve({
      slot0Player: 0xabc,
      slot1Player: 0,
      playerPtr: 0xabc,
    }),
    { idx: 0, slot0: 0xabc, slot1: 0, assigned: false },
  );
  assert.deepEqual(
    historyHudGetPlayerIdxResolve({
      slot0Player: 0x111,
      slot1Player: 0xabc,
      playerPtr: 0xabc,
    }),
    { idx: 1, slot0: 0x111, slot1: 0xabc, assigned: false },
  );

  // resolve: assign into first empty
  assert.deepEqual(
    historyHudGetPlayerIdxResolve({
      slot0Player: 0,
      slot1Player: 0,
      playerPtr: 0xdead,
    }),
    { idx: 0, slot0: 0xdead, slot1: 0, assigned: true },
  );
  assert.deepEqual(
    historyHudGetPlayerIdxResolve({
      slot0Player: 0x111,
      slot1Player: 0,
      playerPtr: 0xdead,
    }),
    { idx: 1, slot0: 0x111, slot1: 0xdead, assigned: true },
  );

  // resolve: no empty and no match
  assert.deepEqual(
    historyHudGetPlayerIdxResolve({
      slot0Player: 0x111,
      slot1Player: 0x222,
      playerPtr: 0xdead,
    }),
    { idx: -1, slot0: 0x111, slot1: 0x222, assigned: false },
  );

  // try_pure: netplay empty → pure even when local sample unknown
  assert.deepEqual(
    tryHistoryHudGetPlayerIdxPure({
      netplayBegin: 0,
      netplayEnd: 0,
      netplayLocalKnown: -1,
      field2c: 0,
      field3bc: 0,
      charType: 1,
      slot0Player: 0xabc,
      slot1Player: 0,
      playerPtr: 0xabc,
    }),
    { hostRequired: false, idx: 0, slot0: 0xabc, slot1: 0, assigned: false },
  );

  // try_pure: netplay non-empty + unknown local → host
  assert.deepEqual(
    tryHistoryHudGetPlayerIdxPure({
      netplayBegin: 0x1000,
      netplayEnd: 0x1004,
      netplayLocalKnown: -1,
      field2c: 0,
      field3bc: 0,
      charType: 0,
      slot0Player: 0,
      slot1Player: 0,
      playerPtr: 0x1,
    }),
    { hostRequired: true },
  );

  // try_pure: netplay non-empty + not local → pure -1
  assert.deepEqual(
    tryHistoryHudGetPlayerIdxPure({
      netplayBegin: 0x1000,
      netplayEnd: 0x1004,
      netplayLocalKnown: 0,
      field2c: 0,
      field3bc: 0,
      charType: 0,
      slot0Player: 0,
      slot1Player: 0,
      playerPtr: 0x1,
    }),
    { hostRequired: false, idx: -1, slot0: 0, slot1: 0, assigned: false },
  );

  // try_pure: netplay non-empty + local → pure resolve (assign)
  assert.deepEqual(
    tryHistoryHudGetPlayerIdxPure({
      netplayBegin: 0x1000,
      netplayEnd: 0x1004,
      netplayLocalKnown: 1,
      field2c: 0,
      field3bc: 0,
      charType: 0,
      slot0Player: 0,
      slot1Player: 0,
      playerPtr: 0xbeef,
    }),
    { hostRequired: false, idx: 0, slot0: 0xbeef, slot1: 0, assigned: true },
  );

  // try_pure: ineligible → pure -1 (no assign)
  assert.deepEqual(
    tryHistoryHudGetPlayerIdxPure({
      netplayBegin: 0,
      netplayEnd: 0,
      netplayLocalKnown: -1,
      field2c: 1,
      field3bc: 0,
      charType: 0,
      slot0Player: 0,
      slot1Player: 0,
      playerPtr: 0x1,
    }),
    { hostRequired: false, idx: -1, slot0: 0, slot1: 0, assigned: false },
  );
  assert.deepEqual(
    tryHistoryHudGetPlayerIdxPure({
      netplayBegin: 0,
      netplayEnd: 0,
      netplayLocalKnown: -1,
      field2c: 0,
      field3bc: 0,
      charType: HISTORY_GET_PLAYER_IDX_REJECT_CHAR,
      slot0Player: 0,
      slot1Player: 0,
      playerPtr: 0x1,
    }),
    { hostRequired: false, idx: -1, slot0: 0, slot1: 0, assigned: false },
  );

  assert.equal(HISTORY_GET_PLAYER_IDX_NETPLAY_EMBED_OFF, 0x4b3d8);
  assert.equal(HISTORY_GET_PLAYER_IDX_PLAYER_NET_IDX_OFF, 0x1618);
  assert.equal(HUD_HOST_VA_NETPLAY_IS_IDX_LOCAL, 0x0090b100);
});

test("JS oracle: list teardown / sized free residual (v9)", () => {
  // constants
  assert.equal(HISTORY_HUD_LIST_NODE_SUB_OFF, 0x8);
  assert.equal(HISTORY_HUD_LIST_NODE_CALLBACK_ARG_OFF, 0x4);
  assert.equal(HISTORY_HUD_LIST_VTABLE_RELEASE_ENTRY, 0xc);
  assert.equal(HISTORY_HUD_LIST_CALLBACK_GLOBAL, 0xc7163c);
  assert.equal(HISTORY_HUD_FREE_LARGE_GATE, 0x1000);
  assert.equal(HISTORY_HUD_FREE_HEADER_SIZE, 0x23);
  assert.equal(HISTORY_HUD_FREE_HEADER_OFFSET_BOUND, 0x1f);
  assert.equal(HUD_HOST_VA_INVALID_PARAMETER, 0x0083bba5);

  // dest-empty gate
  assert.equal(historyHudListTeardownNeeded(0), false);
  assert.equal(historyHudListTeardownNeeded(1), true);
  assert.equal(historyHudListTeardownNeeded(0xdeadbeef), true);

  // walk gate: begin == end skips nodes but still frees the buffer
  assert.equal(historyHudListWalkNeeded(0x1000, 0x1000), false);
  assert.equal(historyHudListWalkNeeded(0x1000, 0x1028), true);

  // walk count: exact for well-formed spans, -1 otherwise
  assert.equal(historyHudListWalkCount(0x1000, 0x1000), 0);
  assert.equal(historyHudListWalkCount(0x1000, 0x1000 + 0x28 * 3), 3);
  assert.equal(historyHudListWalkCount(0x1000, 0x1000 + 0x28 * 3 + 5), -1);
  assert.equal(historyHudListWalkCount(0x2000, 0x1000), -1); // negative span
  assert.equal(historyHudListWalkCount(0, 0x28), 1);
  assert.equal(historyHudListWalkCount(0xfffffff0, 0x28), -1); // span 0x38, non-stride

  // walk continue: pointer inequality
  assert.equal(historyHudListWalkContinue(0x1000, 0x1028), true);
  assert.equal(historyHudListWalkContinue(0x1028, 0x1028), false);
  assert.equal(historyHudListWalkContinue(0, 0), false);

  // per-node host edges
  assert.equal(historyHudListTeardownNodeReleaseNeeded(0), false);
  assert.equal(historyHudListTeardownNodeReleaseNeeded(0xabc), true);
  assert.equal(historyHudListTeardownCallbackNeeded(0), false);
  assert.equal(historyHudListTeardownCallbackNeeded(0xabc), true);

  // free size: exact PE magic (cross-checked against instruction emulation)
  assert.equal(historyHudListTeardownFreeSize(0x1000, 0x1000), 0);
  assert.equal(historyHudListTeardownFreeSize(0x1000, 0x1000 + 0x28 * 3), 0x78);
  assert.equal(historyHudListTeardownFreeSize(0x1000, 0x1000 + 0x28 * 3 + 5), 0x78);
  assert.equal(historyHudListTeardownFreeSize(0x1000, 0x1000 + 0x1000), 0xff0);
  assert.equal(historyHudListTeardownFreeSize(0x2000, 0x1000), -0xff0);
  assert.equal(historyHudListTeardownFreeSize(0x2000, 0x1000 + 0x18), -0xfc8);
  assert.equal(historyHudListTeardownFreeSize(0x1000, 0x1000 - 0x28), -0x28);
  assert.equal(historyHudListTeardownFreeSize(0, 0x7fffffff), 0x7ffffff8); // 53687091*40
  assert.equal(historyHudListTeardownFreeSize(0x80000000, 0), -2147483640); // 0x80000008
  assert.equal(historyHudListTeardownFreeSize(0, 0xdeadbeef), -559038720); // -0x21524100
  assert.equal(historyHudListTeardownFreeSize(0, 0x12345678), 0x12345668);
  assert.equal(historyHudListTeardownFreeSize(0x1000, 0x1027), 0); // 39 → 0
  assert.equal(historyHudListTeardownFreeSize(0x1000, 0x1028), 0x28);

  // large gate: UNSIGNED
  assert.equal(historyHudListTeardownLargeGate(0), false);
  assert.equal(historyHudListTeardownLargeGate(0xfff), false);
  assert.equal(historyHudListTeardownLargeGate(0x1000), true);
  assert.equal(historyHudListTeardownLargeGate(0x1001), true);
  assert.equal(historyHudListTeardownLargeGate(-1), true);  // 0xffffffff unsigned
  assert.equal(historyHudListTeardownLargeGate(-0xfff), true); // 0xfffff001 is huge unsigned
  assert.equal(historyHudListTeardownLargeGate(-0x1000), true);
  assert.equal(historyHudListTeardownLargeGate(0x80000000), true);

  // header resolve
  const ok1 = historyHudListTeardownHeaderResolve(0x400, 0x408, 0x1000);
  assert.equal(ok1.invalid, false); // begin-header-4 = 4 <= 0x1f
  assert.equal(ok1.freePtr, 0x400);
  assert.equal(ok1.freeSizeArg, 0x1023);
  const ok2 = historyHudListTeardownHeaderResolve(0x100, 0x123, 0x4080);
  assert.equal(ok2.invalid, false); // 0x123-0x100-4 = 0x1f, bound inclusive
  assert.equal(ok2.freePtr, 0x100);
  assert.equal(ok2.freeSizeArg, 0x40a3);
  const bad = historyHudListTeardownHeaderResolve(0x100, 0x124, 0x1000);
  assert.equal(bad.invalid, true); // 0x20 > 0x1f
  const wrap = historyHudListTeardownHeaderResolve(0xffffffff, 0, 0x1000);
  assert.equal(wrap.invalid, true); // (0 - 0xffffffff - 4) wraps to 0xfffffffd
  const wrapOk = historyHudListTeardownHeaderResolve(0xfffffff0, 0, 0x1000);
  assert.equal(wrapOk.invalid, false); // (0 - 0xfffffff0 - 4) = 0xc unsigned
  assert.equal(wrapOk.freePtr, 0xfffffff0);
  assert.equal(wrapOk.freeSizeArg, 0x1023);

  // plan: empty list → nothing
  const empty = historyHudListTeardownPlan({ listBegin: 0, listEnd: 0, listCap: 0 });
  assert.equal(empty.teardownNeeded, false);
  assert.equal(empty.hostFreeNeeded, false);
  assert.equal(empty.hostNodeEdges, 0);
  assert.equal(empty.invalidParameterNeeded, false);

  // plan: small list → walk + free(begin, size)
  const small = historyHudListTeardownPlan({
    listBegin: 0x2000,
    listEnd: 0x2000 + 0x28 * 2,
    listCap: 0x2000 + 0x28 * 4,
  });
  assert.equal(small.teardownNeeded, true);
  assert.equal(small.walkNeeded, true);
  assert.equal(small.walkCount, 2);
  assert.equal(small.hostNodeEdges, 2);
  assert.equal(small.freeSize, 0x28 * 4);
  assert.equal(small.largeGate, false);
  assert.equal(small.hostFreeNeeded, true);
  assert.equal(small.freePtr, 0x2000);
  assert.equal(small.freeSizeArg, 0xa0);
  assert.equal(small.freeMonolithic, false);

  // plan: begin == end → no node edges, free still runs
  const freeOnly = historyHudListTeardownPlan({
    listBegin: 0x3000,
    listEnd: 0x3000,
    listCap: 0x3000 + 0x1000,
  });
  assert.equal(freeOnly.walkNeeded, false);
  assert.equal(freeOnly.hostNodeEdges, 0);
  assert.equal(freeOnly.hostFreeNeeded, true);
  assert.equal(freeOnly.freeSize, 0xff0);
  assert.equal(freeOnly.largeGate, false);

  // plan: large + header known + valid → free(header, size+0x23)
  const largeOk = historyHudListTeardownPlan({
    listBegin: 0x2000,
    listEnd: 0x2000,
    listCap: 0x2000 + 0x1000 * 2,
    headerKnown: true,
    header: 0x1ff0,
  });
  assert.equal(largeOk.largeGate, true);
  assert.equal(largeOk.freeSize, 0x1fe0); // trunc(0x2000/0x28)*0x28
  assert.equal(largeOk.invalidParameterNeeded, false);
  assert.equal(largeOk.hostFreeNeeded, true);
  assert.equal(largeOk.freePtr, 0x1ff0); // 0x2000-0x1ff0-4 = 0xc <= 0x1f
  assert.equal(largeOk.freeSizeArg, 0x2003); // 0x1fe0 + 0x23
  assert.equal(largeOk.freeMonolithic, false);

  // plan: large + header known + bound fail → invalid_parameter edge
  const largeBad = historyHudListTeardownPlan({
    listBegin: 0x2000,
    listEnd: 0x2000,
    listCap: 0x2000 + 0x1000 * 2,
    headerKnown: true,
    header: 0x1f00, // 0x2000-0x1f00-4 = 0xfc > 0x1f
  });
  assert.equal(largeBad.invalidParameterNeeded, true);
  assert.equal(largeBad.hostFreeNeeded, false);

  // plan: large + no header sample → monolithic host
  const largeUnknown = historyHudListTeardownPlan({
    listBegin: 0x2000,
    listEnd: 0x2000,
    listCap: 0x2000 + 0x1000 * 2,
  });
  assert.equal(largeUnknown.hostFreeNeeded, true);
  assert.equal(largeUnknown.freeMonolithic, true);
  assert.equal(largeUnknown.freePtr, 0);
  assert.equal(largeUnknown.freeSizeArg, 0);

  // plan: large + header known + valid bound, exact boundary (0x1f inclusive)
  const boundOk = historyHudListTeardownPlan({
    listBegin: 0x2000,
    listEnd: 0x2000,
    listCap: 0x2000 + 0x1000 * 2,
    headerKnown: true,
    header: 0x1fe5, // 0x2000-0x1fe5-4 = 0x17 <= 0x1f
  });
  assert.equal(boundOk.invalidParameterNeeded, false);
  assert.equal(boundOk.freePtr, 0x1fe5);

  // plan: torn span → unbounded, no node edges, monolithic host
  const torn = historyHudListTeardownPlan({
    listBegin: 0x4000,
    listEnd: 0x4000 + 0x28 * 2 + 7,
    listCap: 0x4000 + 0x2000,
  });
  assert.equal(torn.walkCount, -1);
  assert.equal(torn.unbounded, true);
  assert.equal(torn.hostNodeEdges, 0);
  assert.equal(torn.hostFreeNeeded, true);
  assert.equal(torn.freeMonolithic, true);

  // plan: torn span with a SMALL buffer is still monolithic — the free edge
  // is not enumerable (the PE walk would never terminate before it).
  const tornSmall = historyHudListTeardownPlan({
    listBegin: 0x4000,
    listEnd: 0x4000 + 0x28 + 3,
    listCap: 0x4000 + 0x100,
  });
  assert.equal(tornSmall.walkCount, -1);
  assert.equal(tornSmall.largeGate, false);
  assert.equal(tornSmall.freeMonolithic, true);
  assert.equal(tornSmall.freePtr, 0);
  assert.equal(tornSmall.freeSizeArg, 0);
  assert.equal(tornSmall.hostFreeNeeded, true);

  // ordering of frees in the compact (0x0083b850 move 3)
  const ordNone = historyHudSlotCompactTeardownOrder({
    srcBeginAddr: 0x100000 + HISTORY_HUD_SLOT_LIST_BEGIN_OFFSET,
    tempAddr: 0x7ff000,
    srcBeginAfterMove2: 0, // move 2 zeroed src's triple
    tempBegin: 0x5000,
  });
  assert.equal(ordNone.siteANeeded, false);
  assert.equal(ordNone.siteBNeeded, false);
  assert.equal(ordNone.anyTeardownNeeded, false);
  // site A fires when src's post-move-2 begin is nonzero (never in
  // 0x0083b850, but the teardown would run BEFORE the adopt then)
  const ordA = historyHudSlotCompactTeardownOrder({
    srcBeginAddr: 0x100008,
    tempAddr: 0x7ff000,
    srcBeginAfterMove2: 0x3000,
    tempBegin: 0x5000,
  });
  assert.equal(ordA.siteANeeded, true);
  assert.equal(ordA.siteBNeeded, false);
  assert.equal(ordA.anyTeardownNeeded, true);
  // site B fires only on the address equality (slot vs stack — never)
  const ordB = historyHudSlotCompactTeardownOrder({
    srcBeginAddr: 0x100008,
    tempAddr: 0x100008,
    srcBeginAfterMove2: 0,
    tempBegin: 0x5000,
  });
  assert.equal(ordB.siteANeeded, false);
  assert.equal(ordB.siteBNeeded, true);
  assert.equal(ordB.anyTeardownNeeded, true);
  // site B with an empty temp does not fire
  const ordBEmpty = historyHudSlotCompactTeardownOrder({
    srcBeginAddr: 0x100008,
    tempAddr: 0x100008,
    srcBeginAfterMove2: 0,
    tempBegin: 0,
  });
  assert.equal(ordBEmpty.siteBNeeded, false);
  assert.equal(ordBEmpty.anyTeardownNeeded, false);
});

