test("JS oracle: StatHUD tail walk CF (v5)", () => {
  // Unsigned bound: failing it re-reads slot 0 rather than skipping.
  assert.equal(statHudWalkIndexSelect(0, 3), 0);
  assert.equal(statHudWalkIndexSelect(2, 3), 2);
  assert.equal(statHudWalkIndexSelect(3, 3), 0);
  assert.equal(statHudWalkIndexSelect(0x80000000, 3), 0);
  assert.equal(statHudWalkIndexSelect(7, -1), 7);

  assert.equal(statHudWalkNeedsEmptyFatal(0), true);
  assert.equal(statHudWalkNeedsEmptyFatal(1), false);
  assert.equal(statHudWalkNeedsEmptyFatal(-1), false);

  assert.equal(statHudWalkContinue(1, 3), true);
  assert.equal(statHudWalkContinue(3, 3), false);
  assert.equal(statHudWalkContinue(0, -1), true);

  assert.equal(statHudRecomputeCountArg(4), 4);
  assert.equal(statHudRecomputeCountArg(-2), -2);

  assert.equal(statHudOwnerFlagValue(0), 0);
  assert.equal(statHudOwnerFlagValue(0xdeadbeef), 1);
  assert.equal(statHudOwnerFlagValue(0), statHudApplyOwnerFlag(0));

  assert.equal(statHudTailHostCallCount(false, 5), 0);
  assert.equal(statHudTailHostCallCount(true, 0), 1);
  assert.equal(statHudTailHostCallCount(true, 3), 7);
  assert.equal(statHudTailHostCallCount(true, -3), 1);

  assert.equal(statHudTailPureComplete(0), true);
  assert.equal(statHudTailPureComplete(1), false);
});

test("JS oracle: StatHUD tail plan matrix (v5)", () => {
  const idle = statHudTailPlan({ managerStatFlag: 0, listBegin: 0x1000, listEnd: 0x1010 });
  assert.equal(idle.tailNeeded, false);
  assert.equal(idle.pureComplete, true);
  assert.equal(idle.hostCallCount, 0);
  assert.equal(idle.countdownApplied, false);

  const empty = statHudTailPlan({
    managerStatFlag: 1,
    listBegin: 0x1000,
    listEnd: 0x1000,
    ownerSample: 0,
    ownerKnown: 1,
  });
  assert.equal(empty.tailNeeded, true);
  assert.equal(empty.playerCount, 0);
  assert.equal(empty.walkIterations, 0);
  assert.equal(empty.hostCallCount, 1); // FirstCollectibleOwner only
  assert.equal(empty.emptyFatalNeeded, false);
  assert.equal(empty.countdownApplied, true);
  assert.equal(empty.ownerFlag, 0);
  assert.equal(empty.ownerFlagKnown, true);

  const walk = statHudTailPlan({
    managerStatFlag: 0x80,
    listBegin: 0x1000,
    listEnd: 0x100c,
    ownerSample: 0x1234,
    ownerKnown: 1,
  });
  assert.equal(walk.playerCount, 3);
  assert.equal(walk.walkIterations, 3);
  assert.equal(walk.hostCallCount, 7);
  assert.equal(walk.ownerFlag, 1);

  const noOwner = statHudTailPlan({
    managerStatFlag: 1,
    listBegin: 0x1000,
    listEnd: 0x1004,
  });
  assert.equal(noOwner.ownerFlagKnown, false);
  assert.equal(noOwner.ownerFlag, 0);
  assert.equal(noOwner.hostCallCount, 3);

  const torn = statHudTailPlan({
    managerStatFlag: 1,
    listBegin: 0x1010,
    listEnd: 0x1000,
  });
  assert.equal(torn.playerCount, -4);
  assert.equal(torn.walkIterations, 0);
  assert.equal(torn.emptyFatalNeeded, true);
  assert.equal(torn.hostCallCount, 1);
});

