test("JS oracle: v14 Game::GetPlayer unsigned clamp / empty fatal", () => {
  assert.equal(gameGetPlayerEmpty(0), 1);
  assert.equal(gameGetPlayerEmpty(1), 0);
  assert.equal(gameGetPlayerEmpty(-1), 0);
  // UNSIGNED: 0xffffffff < 1 is false
  assert.equal(gameGetPlayerInBounds(0, 1), 1);
  assert.equal(gameGetPlayerInBounds(1, 1), 0);
  assert.equal(gameGetPlayerInBounds(0xffffffff, 1), 0);
  // torn negative count: unsigned 0 < 0xffffffff is true
  assert.equal(gameGetPlayerInBounds(0, -1), 1);
  assert.equal(gameGetPlayerSlotAddr(0x1000, 0, 2), 0x1000);
  assert.equal(gameGetPlayerSlotAddr(0x1000, 1, 2), 0x1004);
  assert.equal(gameGetPlayerSlotAddr(0x1000, 2, 2), 0x1000); // clamp
  const empty = gameGetPlayerPlan({
    listBegin: 0x1000, listEnd: 0x1000, index: 0, slotSample: 0xabc,
  });
  assert.equal(empty.empty, 1);
  assert.equal(empty.hostFatal, 1);
  assert.equal(empty.resultKnown, 0);
  assert.equal(empty.result, 0); // must not fold sample
  const hit = gameGetPlayerPlan({
    listBegin: 0x1000, listEnd: 0x1008, index: 1, slotSample: 0xdef,
  });
  assert.equal(hit.empty, 0);
  assert.equal(hit.inBounds, 1);
  assert.equal(hit.slotAddr, 0x1004);
  assert.equal(hit.result, 0xdef);
  assert.equal(hit.resultKnown, 1);
});

test("JS oracle: v14 HasCollectible prefix / quest / held / inventory", () => {
  // field_2c == 1 only
  assert.equal(hasCollectibleRedirectNeeded(0), 0);
  assert.equal(hasCollectibleRedirectNeeded(1), 1);
  assert.equal(hasCollectibleRedirectNeeded(2), 0);
  assert.equal(hasCollectibleRedirectNeeded(0x100), 0);
  assert.equal(hasCollectibleParentQualify(0, 1), 0);
  assert.equal(hasCollectibleParentQualify(0x10, 0), 0);
  assert.equal(hasCollectibleParentQualify(0x10, 1), 1);
  assert.equal(hasCollectibleParentQualify(0x10, 2), 0);

  // byte mask + SIGNED challenge + DWORD 0x8000
  assert.equal(hasCollectibleQuestHide(0, 0, 0), 0);
  assert.equal(hasCollectibleQuestHide(1, 0, 0), 1);
  assert.equal(hasCollectibleQuestHide(0x100, 0, 0), 0);
  assert.equal(hasCollectibleQuestHide(0x1ff, 0, 0), 1);
  assert.equal(hasCollectibleQuestHide(1, 2, 0), 0);
  assert.equal(hasCollectibleQuestHide(1, 0xffffffff, 0), 1); // signed -1 < 2, still hides
  assert.equal(hasCollectibleQuestHide(1, 0, 0x8000), 0);
  assert.equal(hasCollectibleQuestHide(1, 0, 0x80), 1);

  assert.equal(hasCollectibleHeldTrue(0, 5, 1), 0);
  assert.equal(hasCollectibleHeldTrue(5, 5, 1), 1);
  assert.equal(hasCollectibleHeldTrue(5, 5, 0), 0);
  assert.equal(hasCollectibleHeldTrue(5, 5, 0x100), 0);
  assert.equal(hasCollectibleHeldTrue(5, 5, 0x1ff), 1);

  assert.equal(hasCollectibleIdNegative(-1), 1);
  assert.equal(hasCollectibleIdNegative(0x80000000), 1);
  assert.equal(hasCollectibleIdNegative(1), 0);

  assert.equal(hasCollectibleIgnoreModifiers(0), 0);
  assert.equal(hasCollectibleIgnoreModifiers(1), 1);
  assert.equal(hasCollectibleIgnoreModifiers(0x100), 0);
  assert.equal(hasCollectibleIgnoreModifiers(0x1ff), 1);

  assert.equal(hasCollectibleInventoryThreshold(5, 5, 0), 1);
  assert.equal(hasCollectibleInventoryThreshold(5, 5, 1), 0);
  assert.equal(hasCollectibleCountHit(1, 0), 1);
  assert.equal(hasCollectibleCountHit(0, 0), 0);
  assert.equal(hasCollectibleCountHit(0x80000000, 0), 0); // signed not >
  assert.equal(hasCollectibleCountHit(2, 1), 1);
  assert.equal(hasCollectibleCountHit(1, 1), 0);
  assert.equal(hasCollectibleCountSlotAddr(0x2000, 3), 0x200c);

  const skip = hasCollectibleRedirectNode({ playerIn: 0x3000, field2c: 0 });
  assert.equal(skip.redirectNeeded, 0);
  assert.equal(skip.hostGetPlayer, 0);
  assert.equal(skip.playerOut, 0x3000);

  const parent = hasCollectibleRedirectNode({
    playerIn: 0x3000, field2c: 1, parentPtr: 0x4000, parentField28: 1,
  });
  assert.equal(parent.parentQualify, 1);
  assert.equal(parent.hostGetPlayer, 0);
  assert.equal(parent.playerOut, 0x4000);

  const gpNull = hasCollectibleRedirectNode({
    playerIn: 0x3000, field2c: 1, parentPtr: 0, parentField28: 0,
    getPlayerKnown: 1, getPlayerResult: 0,
  });
  assert.equal(gpNull.hostGetPlayer, 1);
  assert.equal(gpNull.fallToInventory, 1);
  assert.equal(gpNull.playerOut, 0x3000);

  const none = hasCollectiblePlan({ configPtr: 0 });
  assert.equal(none.configNull, 1);
  assert.equal(none.pureComplete, 1);
  assert.equal(none.result, 0);

  const quest = hasCollectiblePlan({
    configPtr: 0x10, playerIn: 0x3000, field2c: 0,
    listBegin: 0x1000, listEnd: 0x1004, player0Sample: 0x3000,
    flag20a9: 1, challenge: 0, itemFlags: 0, id: 5, ignoreMod: 1, countSample: 3,
  });
  assert.equal(quest.questHide, 1);
  assert.equal(quest.result, 0);
  assert.equal(quest.pureComplete, 1);

  const held = hasCollectiblePlan({
    configPtr: 0x10, playerIn: 0x3000, field2c: 0,
    listBegin: 0x1000, listEnd: 0x1004, player0Sample: 0x3000,
    flag20a9: 0, heldId: 5, heldFlag: 1, id: 5, ignoreMod: 1, countSample: 0,
  });
  assert.equal(held.heldTrue, 1);
  assert.equal(held.result, 1);
  assert.equal(held.pureComplete, 1);

  const inv = hasCollectiblePlan({
    configPtr: 0x10, playerIn: 0x3000, field2c: 0,
    listBegin: 0x1000, listEnd: 0x1004, player0Sample: 0x3000,
    flag20a9: 0, heldId: 0, id: 5, ignoreMod: 1, countSample: 3,
  });
  assert.equal(inv.ignoreModifiers, 1);
  assert.equal(inv.hostModifierBody, 0);
  assert.equal(inv.countHit, 1);
  assert.equal(inv.result, 1);
  assert.equal(inv.pureComplete, 1);

  const hostBody = hasCollectiblePlan({
    configPtr: 0x10, playerIn: 0x3000, field2c: 0,
    listBegin: 0x1000, listEnd: 0x1004, player0Sample: 0x3000,
    flag20a9: 0, id: 0x1f2, ignoreMod: 0, countSample: 3,
  });
  assert.equal(hostBody.hostModifierBody, 1);
  assert.equal(hostBody.pureComplete, 0);
  assert.equal(hostBody.resultKnown, 0); // do not fold inventory

  const trinket = hasCollectiblePlan({
    configPtr: 0x10, playerIn: 0x3000, field2c: 0,
    listBegin: 0x1000, listEnd: 0x1004, id: -1, ignoreMod: 1,
  });
  assert.equal(trinket.hostTrinket, 1);
  assert.equal(trinket.pureComplete, 0);

  const fatal = hasCollectiblePlan({
    configPtr: 0x10, playerIn: 0x3000, field2c: 1,
    parentPtr: 0, parentField28: 0,
    listBegin: 0x1000, listEnd: 0x1000, player0Sample: 0xabc,
    id: 5, ignoreMod: 1, countSample: 3,
  });
  assert.equal(fatal.hostGetPlayer, 1);
  assert.equal(fatal.getPlayerFatal, 1);
  assert.equal(fatal.resultKnown, 0);
  assert.equal(fatal.pureComplete, 0);
});

test("v14 HasCollectible + GetPlayer native/Wasm differential + mutation pins", () => {
  const exp = loadExports();
  const view = new DataView(exp.memory.buffer);
  assert.equal(exp.abi(), 39);
  assert.equal(exp.vaGameGetPlayer(), 0x00417870);
  assert.equal(exp.vaHasTrinket(), 0x009e04b0);
  assert.equal(exp.hcField2cOff(), 0x2c);
  assert.equal(exp.hcQuestBit(), 0x8000);
  assert.equal(exp.hcTableOff(), 0x16c8);

  assert.equal(exp.gpEmpty(0), 1);
  assert.equal(exp.gpEmpty(-1), 0);
  assert.equal(exp.gpInBounds(0xffffffff >>> 0, 1), 0);
  assert.equal(exp.gpInBounds(0, -1), 1);
  assert.equal(exp.gpSlotAddr(0x1000, 2, 2), 0x1000);

  const gpPtr = 0x105000;
  exp.gpPlan(0x1000, 0x1000, 0, 0xabc, gpPtr);
  assert.equal(readI32(view, gpPtr + 4), 1); // empty
  assert.equal(readI32(view, gpPtr + 8), 1); // host_fatal
  assert.equal(readI32(view, gpPtr + 24), 0); // result_known
  assert.equal(readU32(view, gpPtr + 20), 0); // result not folded

  exp.gpPlan(0x1000, 0x1008, 1, 0xdef, gpPtr);
  assert.equal(readI32(view, gpPtr + 0), 2); // count
  assert.equal(readI32(view, gpPtr + 12), 1); // in_bounds
  assert.equal(readU32(view, gpPtr + 16), 0x1004);
  assert.equal(readU32(view, gpPtr + 20), 0xdef);

  // mutant pins
  assert.equal(exp.hcRedirect(0), 0);
  assert.equal(exp.hcRedirect(1), 1);
  assert.equal(exp.hcRedirect(2), 0);
  assert.equal(exp.hcQuestHide(0x100, 0, 0), 0);
  assert.equal(exp.hcQuestHide(0x1ff, 0, 0), 1);
  assert.equal(exp.hcQuestHide(1, 0xffffffff, 0), 1);
  assert.equal(exp.hcQuestHide(1, 0, 0x80), 1);
  assert.equal(exp.hcHeldTrue(5, 5, 0x100), 0);
  assert.equal(exp.hcIgnore(0x100), 0);
  assert.equal(exp.hcCountHit(0x80000000, 0), 0);
  assert.equal(exp.hcInvThresh(5, 5, 0), 1);
  assert.equal(exp.hcInvThresh(5, 5, 1), 0);

  const nodePtr = 0x105040;
  exp.hcRedirectNode(0x3000, 1, 0x4000, 1, 0, 0, nodePtr);
  assert.equal(readI32(view, nodePtr + 0), 1); // redirect
  assert.equal(readI32(view, nodePtr + 4), 1); // parent
  assert.equal(readI32(view, nodePtr + 8), 0); // no GetPlayer
  assert.equal(readU32(view, nodePtr + 12), 0x4000);

  const planPtr = 0x105080;
  const planCases = [
    { cfg: 0, p: 0x3000, f2c: 0, pp: 0, p28: 0, lb: 0, le: 0, p0: 0,
      fl: 0, ch: 0, ifl: 0, hid: 0, hf: 0, id: 0, im: 0, cs: 0 },
    { cfg: 0x10, p: 0x3000, f2c: 0, pp: 0, p28: 0, lb: 0x1000, le: 0x1004, p0: 0x3000,
      fl: 1, ch: 0, ifl: 0, hid: 0, hf: 0, id: 5, im: 1, cs: 3 },
    { cfg: 0x10, p: 0x3000, f2c: 0, pp: 0, p28: 0, lb: 0x1000, le: 0x1004, p0: 0x3000,
      fl: 0, ch: 0, ifl: 0, hid: 5, hf: 1, id: 5, im: 1, cs: 0 },
    { cfg: 0x10, p: 0x3000, f2c: 0, pp: 0, p28: 0, lb: 0x1000, le: 0x1004, p0: 0x3000,
      fl: 0, ch: 0, ifl: 0, hid: 0, hf: 0, id: 5, im: 1, cs: 3 },
    { cfg: 0x10, p: 0x3000, f2c: 0, pp: 0, p28: 0, lb: 0x1000, le: 0x1004, p0: 0x3000,
      fl: 0, ch: 0, ifl: 0, hid: 0, hf: 0, id: 0x1f2, im: 0, cs: 3 },
    { cfg: 0x10, p: 0x3000, f2c: 1, pp: 0, p28: 0, lb: 0x1000, le: 0x1000, p0: 0xabc,
      fl: 0, ch: 0, ifl: 0, hid: 0, hf: 0, id: 5, im: 1, cs: 3 },
  ];
  for (const c of planCases) {
    exp.hcPlan(c.cfg >>> 0, c.p >>> 0, c.f2c >>> 0, c.pp >>> 0, c.p28 >>> 0,
               c.lb >>> 0, c.le >>> 0, c.p0 >>> 0, c.fl >>> 0, c.ch | 0,
               c.ifl >>> 0, c.hid >>> 0, c.hf >>> 0, c.id | 0, c.im >>> 0,
               c.cs | 0, planPtr);
    const js = hasCollectiblePlan({
      configPtr: c.cfg, playerIn: c.p, field2c: c.f2c, parentPtr: c.pp,
      parentField28: c.p28, listBegin: c.lb, listEnd: c.le, player0Sample: c.p0,
      flag20a9: c.fl, challenge: c.ch, itemFlags: c.ifl, heldId: c.hid,
      heldFlag: c.hf, id: c.id, ignoreMod: c.im, countSample: c.cs,
    });
    const label = JSON.stringify(c);
    assert.equal(readI32(view, planPtr + 0), js.configNull, `${label} null`);
    assert.equal(readI32(view, planPtr + 4), js.redirectNeeded, `${label} red`);
    assert.equal(readI32(view, planPtr + 12), js.hostGetPlayer, `${label} hgp`);
    assert.equal(readI32(view, planPtr + 16), js.getPlayerFatal, `${label} fat`);
    assert.equal(readI32(view, planPtr + 28), js.questHide, `${label} qh`);
    assert.equal(readI32(view, planPtr + 32), js.heldTrue, `${label} held`);
    assert.equal(readI32(view, planPtr + 40), js.hostTrinket, `${label} tr`);
    assert.equal(readI32(view, planPtr + 48), js.hostModifierBody, `${label} mod`);
    assert.equal(readI32(view, planPtr + 60), js.result, `${label} res`);
    assert.equal(readI32(view, planPtr + 64), js.resultKnown, `${label} rk`);
    assert.equal(readI32(view, planPtr + 68), js.pureComplete, `${label} pure`);
  }

  let rng = (0x7706e0 ^ 0x417870) >>> 0;
  const nextRnd = () => {
    rng = (Math.imul(rng, 1664525) + 1013904223) >>> 0;
    return rng;
  };
  for (let t = 0; t < 200; t += 1) {
    const idx = nextRnd();
    const cnt = nextRnd() | 0;
    assert.equal(exp.gpInBounds(idx, cnt), gameGetPlayerInBounds(idx, cnt), `rnd gp ${t}`);
    const fl = nextRnd();
    const ch = nextRnd() | 0;
    const ifl = nextRnd();
    assert.equal(exp.hcQuestHide(fl, ch, ifl), hasCollectibleQuestHide(fl, ch, ifl),
      `rnd quest ${t}`);
    const hid = nextRnd();
    const id = nextRnd() | 0;
    const hf = nextRnd();
    assert.equal(exp.hcHeldTrue(hid, id, hf), hasCollectibleHeldTrue(hid, id, hf),
      `rnd held ${t}`);
    const c1 = nextRnd() | 0;
    const c2 = nextRnd() | 0;
    assert.equal(exp.hcCountHit(c1, c2), hasCollectibleCountHit(c1, c2), `rnd hit ${t}`);
    const im = nextRnd();
    assert.equal(exp.hcIgnore(im), hasCollectibleIgnoreModifiers(im), `rnd ign ${t}`);
  }
});


