test("JS oracle: v15 modifier arm / 0x2028 bits / signed mod4 / types", () => {
  assert.equal(hasCollectibleModArm(0x147), HAS_COLLECTIBLE_MOD_ARM_147_148);
  assert.equal(hasCollectibleModArm(0x148), HAS_COLLECTIBLE_MOD_ARM_147_148);
  assert.equal(hasCollectibleModArm(0x139), HAS_COLLECTIBLE_MOD_ARM_139);
  assert.equal(hasCollectibleModArm(9), HAS_COLLECTIBLE_MOD_ARM_9);
  assert.equal(hasCollectibleModArm(0x3b), HAS_COLLECTIBLE_MOD_ARM_3B);
  assert.equal(hasCollectibleModArm(0x131), HAS_COLLECTIBLE_MOD_ARM_131);
  assert.equal(hasCollectibleModArm(0x101), HAS_COLLECTIBLE_MOD_ARM_101);
  assert.equal(hasCollectibleModArm(0xe7), HAS_COLLECTIBLE_MOD_ARM_E7);
  assert.equal(hasCollectibleModArm(0xb6), HAS_COLLECTIBLE_MOD_ARM_B6);
  assert.equal(hasCollectibleModArm(0x1f2), HAS_COLLECTIBLE_MOD_ARM_OTHER);

  // low-byte mask: 0x100 must not set bit 0x10
  assert.equal(hasCollectibleFlags2028Bit(0x10, 0x10), 1);
  assert.equal(hasCollectibleFlags2028Bit(0x100, 0x10), 0);
  assert.equal(hasCollectibleFlags2028Bit(0x1ff, 0x10), 1);
  assert.equal(hasCollectibleFlags2028Bit(0x08, 0x10), 0);
  assert.equal(hasCollectibleFlags2028Bit(0x08, 0x08), 1);
  assert.equal(hasCollectibleFlags2028Bit(0x20, 0x20), 1);
  assert.equal(hasCollectibleFlags2028Bit(0x40, 0x40), 1);

  // signed mod4: 0x80000000 masked is negative, jns not taken
  assert.equal(hasCollectibleSeedMod4(0), 0);
  assert.equal(hasCollectibleSeedMod4(1), 1);
  assert.equal(hasCollectibleSeedMod4(2), 2);
  assert.equal(hasCollectibleSeedMod4(3), 3);
  assert.equal(hasCollectibleSeedMod4(4), 0);
  assert.equal(hasCollectibleSeedMod4(0x80000000), 0); // idiom correction lands on 0
  assert.equal(hasCollectibleSeedMod4(-1), -1); // unsigned & 3 would be 3
  assert.notEqual((-1) & 3, hasCollectibleSeedMod4(-1));
  assert.equal(hasCollectibleSeedMod4(-5), -1);

  // inner_true: SIGNED num>1; 0x80000000 is not > 1
  assert.equal(hasCollectibleInnerTrue(0x147, 2, 0), 1);
  assert.equal(hasCollectibleInnerTrue(0x148, 2, 1), 1);
  assert.equal(hasCollectibleInnerTrue(0x147, 2, 2), 0);
  assert.equal(hasCollectibleInnerTrue(0x147, 1, 0), 1);
  assert.equal(hasCollectibleInnerTrue(0x148, 1, 0), 0);
  assert.equal(hasCollectibleInnerTrue(0x147, 1, 1), 0);
  assert.equal(hasCollectibleInnerTrue(0x148, 1, 1), 1);
  assert.equal(hasCollectibleInnerTrue(0x147, 0x80000000, 0), 1); // not >1, mod==0 → 0x147
  assert.equal(hasCollectibleInnerTrue(0x148, 0x80000000, 0), 0);

  assert.equal(hasCollectibleType10(0xa), 1);
  assert.equal(hasCollectibleType10(0xb), 0);
  assert.equal(hasCollectibleType31(0x1f), 1);
  assert.equal(hasCollectibleType3OrC(3), 1);
  assert.equal(hasCollectibleType3OrC(0xc), 1);
  assert.equal(hasCollectibleType3OrC(2), 0);
  assert.equal(hasCollectibleType3OrC(0xd), 0);
});

test("JS oracle: v15 HasNullEffect + modifier plan gates", () => {
  assert.equal(tempfxHasNullDisabled(0), 0);
  assert.equal(tempfxHasNullDisabled(1), 1);
  assert.equal(tempfxHasNullDisabled(0x100), 0);
  assert.equal(tempfxHasNullDisabled(0x1ff), 1);
  assert.equal(tempfxHasNullEmpty(0x10, 0x10), 1);
  assert.equal(tempfxHasNullEmpty(0x10, 0x20), 0);
  assert.equal(tempfxHasNullNodeMatch(0, 0x70, 0x70), 1);
  assert.equal(tempfxHasNullNodeMatch(1, 0x70, 0x70), 0);
  assert.equal(tempfxHasNullWalkContinue(0x20, 0x20), 0);
  assert.equal(tempfxHasNullWalkContinue(0x20, 0x30), 1);

  const dis = tempfxHasNullPlan({ disabled: 1, begin: 0x10, end: 0x20, itemType: 0, itemId: 0x70, wanted: 0x70 });
  assert.equal(dis.pureComplete, 1);
  assert.equal(dis.result, 0);
  const empty = tempfxHasNullPlan({ disabled: 0, begin: 0x10, end: 0x10, itemType: 0, itemId: 0x70, wanted: 0x70 });
  assert.equal(empty.empty, 1);
  assert.equal(empty.pureComplete, 1);
  const hit = tempfxHasNullPlan({ disabled: 0, begin: 0x10, end: 0x20, itemType: 0, itemId: 0x70, wanted: 0x70 });
  assert.equal(hit.nodeMatch, 1);
  assert.equal(hit.result, 1);
  assert.equal(hit.pureComplete, 1);

  // bit TRUE: 0x131 with 0x10 set
  const bit = hasCollectibleModifierPlan({ id: 0x131, flags2028: 0x10 });
  assert.equal(bit.arm, HAS_COLLECTIBLE_MOD_ARM_131);
  assert.equal(bit.bitTrue, 1);
  assert.equal(bit.result, 1);
  assert.equal(bit.pureComplete, 1);
  assert.equal(bit.host7db8d0, 0);

  // bit not set → host 0x7db8d0
  const bitMiss = hasCollectibleModifierPlan({ id: 0x131, flags2028: 0 });
  assert.equal(bitMiss.bitTrue, 0);
  assert.equal(bitMiss.host7db8d0, 1);
  assert.equal(bitMiss.pureComplete, 0);

  // 0x147 with host samples
  const a147 = hasCollectibleModifierPlan({
    id: 0x147, seed264f8: 0, hasEffect15Known: 1, hasEffect15: 1, num15Known: 1, num15: 1,
  });
  assert.equal(a147.host771550, 1);
  assert.equal(a147.host7cb6e0, 1);
  assert.equal(a147.innerTrue, 1);
  assert.equal(a147.pureComplete, 1);

  const a148mod0 = hasCollectibleModifierPlan({
    id: 0x148, seed264f8: 0, hasEffect15Known: 1, hasEffect15: 1, num15Known: 1, num15: 1,
  });
  assert.equal(a148mod0.innerTrue, 0);
  assert.equal(a148mod0.host7db8d0, 1);

  // al=0x100 is low-byte 0
  const alWide = hasCollectibleModifierPlan({
    id: 0x147, hasEffect15Known: 1, hasEffect15: 0x100,
  });
  assert.equal(alWide.host7db8d0, 1);
  assert.equal(alWide.host7cb6e0, 0);

  // type 3/c recursive
  const t3 = hasCollectibleModifierPlan({
    id: 0x3b, charType: 3, rec26bKnown: 1, rec26b: 1,
  });
  assert.equal(t3.hostRec26b, 1);
  assert.equal(t3.pureComplete, 1);
  const t2 = hasCollectibleModifierPlan({ id: 0x3b, charType: 2 });
  assert.equal(t2.hostRec26b, 0);
  assert.equal(t2.host7db8d0, 1);

  // prefix plan still does not fold inventory when ignoreModifiers==0
  const prefix = hasCollectiblePlan({
    configPtr: 0x10, playerIn: 0x3000, field2c: 0,
    listBegin: 0x1000, listEnd: 0x1004, id: 0x1f2, ignoreMod: 0, countSample: 3,
  });
  assert.equal(prefix.hostModifierBody, 1);
  assert.equal(prefix.pureComplete, 0);
  assert.equal(prefix.resultKnown, 0);
});

test("v15 modifier ladder native/Wasm differential + mutation pins", () => {
  const exp = loadExports();
  const view = new DataView(exp.memory.buffer);
  assert.equal(exp.abi(), 39);
  assert.equal(exp.va771550() >>> 0, 0x00771550);
  assert.equal(exp.va7cb6e0() >>> 0, 0x007cb6e0);
  assert.equal(exp.vaTempfxHasNull() >>> 0, 0x00930680);
  assert.equal(exp.va7da770() >>> 0, 0x007da770);
  assert.equal(exp.va7db8d0() >>> 0, 0x007db8d0);
  assert.equal(exp.tempfxDisabledOff(), 0x11);
  assert.equal(exp.tempfxStride(), 0x10);
  assert.equal(exp.hcFlags2028Off(), 0x2028);

  for (const id of [0x147, 0x148, 0x139, 9, 0x3b, 0x131, 0x101, 0xe7, 0xb6, 0x1f2, 0, -1]) {
    assert.equal(exp.hcModArm(id | 0), hasCollectibleModArm(id), `arm ${id}`);
  }
  for (const [f, m] of [[0, 0x10], [0x10, 0x10], [0x100, 0x10], [0x1ff, 0x10], [0x08, 0x08], [0x08, 0x10]]) {
    assert.equal(exp.hcFlags2028Bit(f >>> 0, m >>> 0), hasCollectibleFlags2028Bit(f, m), `bit ${f}/${m}`);
  }
  for (const seed of [0, 1, 2, 3, 4, -1, -5, 0x80000000, 0x7fffffff, 0xffffffff]) {
    assert.equal(exp.hcSeedMod4(seed | 0), hasCollectibleSeedMod4(seed), `mod4 ${seed}`);
  }
  assert.equal(exp.hcInnerTrue(0x147, 0x80000000, 0), hasCollectibleInnerTrue(0x147, 0x80000000, 0));
  assert.equal(exp.hcInnerTrue(0x148, 1, 0), 0);
  assert.equal(exp.hcType3OrC(3), 1);
  assert.equal(exp.hcType3OrC(2), 0);
  assert.equal(exp.hcType3OrC(0xc), 1);
  assert.equal(exp.hcType3OrC(0xd), 0);
  assert.equal(exp.tempfxDisabled(0x100), 0);
  assert.equal(exp.tempfxDisabled(0x1ff), 1);
  assert.equal(exp.tempfxNodeMatch(1, 0x70, 0x70), 0);
  assert.equal(exp.tempfxNodeMatch(0, 0x70, 0x70), 1);

  const planPtr = 0x106000;
  const cases = [
    { id: 0x131, flags: 0x10, ct: 0, seed: 0, e15k: 0, e15: 0, n15k: 0, n15: 0, nk: 0, n: 0, e5k: 0, e5: 0, r26k: 0, r26: 0 },
    { id: 0x131, flags: 0, ct: 0, seed: 0, e15k: 0, e15: 0, n15k: 0, n15: 0, nk: 0, n: 0, e5k: 0, e5: 0, r26k: 0, r26: 0 },
    { id: 0x147, flags: 0, ct: 0, seed: 0, e15k: 1, e15: 1, n15k: 1, n15: 1, nk: 0, n: 0, e5k: 0, e5: 0, r26k: 0, r26: 0 },
    { id: 0x148, flags: 0, ct: 0, seed: 0, e15k: 1, e15: 1, n15k: 1, n15: 1, nk: 0, n: 0, e5k: 0, e5: 0, r26k: 0, r26: 0 },
    { id: 0x147, flags: 0, ct: 0, seed: 0x80000000, e15k: 1, e15: 1, n15k: 1, n15: 2, nk: 0, n: 0, e5k: 0, e5: 0, r26k: 0, r26: 0 },
    { id: 0x139, flags: 0, ct: 0xa, seed: 0, e15k: 0, e15: 0, n15k: 0, n15: 0, nk: 0, n: 0, e5k: 0, e5: 0, r26k: 0, r26: 0 },
    { id: 0x139, flags: 0, ct: 0, seed: 0, e15k: 0, e15: 0, n15k: 0, n15: 0, nk: 1, n: 0, e5k: 0, e5: 0, r26k: 0, r26: 0 },
    { id: 9, flags: 0, ct: 0, seed: 0, e15k: 0, e15: 0, n15k: 0, n15: 0, nk: 0, n: 0, e5k: 1, e5: 0x100, r26k: 0, r26: 0 },
    { id: 0x3b, flags: 0, ct: 3, seed: 0, e15k: 0, e15: 0, n15k: 0, n15: 0, nk: 0, n: 0, e5k: 0, e5: 0, r26k: 1, r26: 1 },
    { id: 0x3b, flags: 0, ct: 2, seed: 0, e15k: 0, e15: 0, n15k: 0, n15: 0, nk: 0, n: 0, e5k: 0, e5: 0, r26k: 0, r26: 0 },
    { id: 0x1f2, flags: 0, ct: 0, seed: 0, e15k: 0, e15: 0, n15k: 0, n15: 0, nk: 0, n: 0, e5k: 0, e5: 0, r26k: 0, r26: 0 },
  ];
  for (const c of cases) {
    exp.hcModPlan(c.id | 0, c.flags >>> 0, c.ct | 0, c.seed | 0,
                  c.e15k | 0, c.e15 | 0, c.n15k | 0, c.n15 | 0,
                  c.nk | 0, c.n | 0, c.e5k | 0, c.e5 | 0, c.r26k | 0, c.r26 | 0, planPtr);
    const js = hasCollectibleModifierPlan({
      id: c.id, flags2028: c.flags, charType: c.ct, seed264f8: c.seed,
      hasEffect15Known: c.e15k, hasEffect15: c.e15, num15Known: c.n15k, num15: c.n15,
      hasNullKnown: c.nk, hasNull: c.n, hasEffect5dKnown: c.e5k, hasEffect5d: c.e5,
      rec26bKnown: c.r26k, rec26b: c.r26,
    });
    const label = JSON.stringify(c);
    assert.equal(readI32(view, planPtr + 0), js.arm, `${label} arm`);
    assert.equal(readI32(view, planPtr + 4), js.bitTrue, `${label} bit`);
    assert.equal(readI32(view, planPtr + 20), js.seedMod4, `${label} mod4`);
    assert.equal(readI32(view, planPtr + 24), js.innerTrue, `${label} inner`);
    assert.equal(readI32(view, planPtr + 28), js.host771550, `${label} 771550`);
    assert.equal(readI32(view, planPtr + 32), js.host7cb6e0, `${label} 7cb6e0`);
    assert.equal(readI32(view, planPtr + 36), js.needHasNull, `${label} null`);
    assert.equal(readI32(view, planPtr + 40), js.hostRec26b, `${label} rec`);
    assert.equal(readI32(view, planPtr + 44), js.host7db8d0, `${label} 7db8d0`);
    assert.equal(readI32(view, planPtr + 48), js.host139Body, `${label} 139`);
    assert.equal(readI32(view, planPtr + 52), js.host9Body, `${label} 9`);
    assert.equal(readI32(view, planPtr + 56), js.result, `${label} res`);
    assert.equal(readI32(view, planPtr + 60), js.resultKnown, `${label} rk`);
    assert.equal(readI32(view, planPtr + 64), js.pureComplete, `${label} pure`);
  }

  // prefix ignoreModifiers==0 still hosts
  const hcPtr = 0x106080;
  exp.hcPlan(0x10, 0x3000, 0, 0, 0, 0x1000, 0x1004, 0x3000, 0, 0, 0, 0, 0, 0x1f2, 0, 3, hcPtr);
  assert.equal(readI32(view, hcPtr + 48), 1); // host_modifier_body
  assert.equal(readI32(view, hcPtr + 64), 0); // result_known
  assert.equal(readI32(view, hcPtr + 68), 0); // pure_complete
});

