test("JS oracle: v16 mod scan / fast dispatch / slow hash / resolve plan", () => {
  // fast dispatch table: entries 0 and 1 BOTH -> -1, then 0..5
  assert.equal(hasCollectibleModFastApplicable(0), 1);
  assert.equal(hasCollectibleModFastApplicable(7), 1);
  assert.equal(hasCollectibleModFastApplicable(8), 0);
  assert.equal(hasCollectibleModFastApplicable(0xff), 0);
  assert.equal(hasCollectibleModFastResult(0), -1);
  assert.equal(hasCollectibleModFastResult(1), -1);
  assert.equal(hasCollectibleModFastResult(2), 0);
  assert.equal(hasCollectibleModFastResult(3), 1);
  assert.equal(hasCollectibleModFastResult(4), 2);
  assert.equal(hasCollectibleModFastResult(5), 3);
  assert.equal(hasCollectibleModFastResult(6), 4);
  assert.equal(hasCollectibleModFastResult(7), 5);

  // scan gate
  const pass = { lastNodeDisabled: 0, lastNodeValue: 0x4f, lastNodeIsHead: 0, bufBegin: 0x100, bufEnd: 0x190 };
  assert.equal(hasCollectibleModScanActive(pass), 1);
  assert.equal(hasCollectibleModScanActive({ ...pass, lastNodeDisabled: 1 }), 0);
  assert.equal(hasCollectibleModScanActive({ ...pass, lastNodeDisabled: 0x100 }), 1); // low byte 0 -> not disabled
  assert.equal(hasCollectibleModScanActive({ ...pass, lastNodeDisabled: 0x101 }), 0); // low byte 1 -> disabled
  assert.equal(hasCollectibleModScanActive({ ...pass, lastNodeValue: 0x4f + 1 }), 0);
  assert.equal(hasCollectibleModScanActive({ ...pass, lastNodeValue: 0x4f }), 1);
  assert.equal(hasCollectibleModScanActive({ ...pass, lastNodeIsHead: 1 }), 0);
  assert.equal(hasCollectibleModScanActive({ ...pass, lastNodeIsHead: 0 }), 1);
  assert.equal(hasCollectibleModScanActive({ bufBegin: 0x100, bufEnd: 0x100 + 0x8f }), 0); // span == 0x8f
  assert.equal(hasCollectibleModScanActive({ bufBegin: 0x100, bufEnd: 0x100 + 0x90 }), 1); // span == 0x90
  assert.equal(hasCollectibleModScanActive({ bufBegin: 0x10, bufEnd: 0x4 }), 0); // signed span negative
  assert.equal(hasCollectibleModScanMode(pass), 0);
  assert.equal(hasCollectibleModScanMode({ ...pass, bufByte: 0x7f }), 0x7f);
  assert.equal(hasCollectibleModScanMode({ ...pass, bufByte: 0x100 }), 0); // low byte
  assert.equal(hasCollectibleModScanMode({ ...pass, bufByte: 0x2 }), 2);

  // slow hash exact vectors (xor-shift, shift dwords 0x3e2d6048/0x652f233e/0x4e31313e)
  assert.equal(hasCollectibleModSlowHash(0, 8), 2);
  assert.equal(hasCollectibleModSlowHash(0, 9), 2);
  assert.equal(hasCollectibleModSlowHash(0, 0xff), 2);
  assert.equal(hasCollectibleModSlowHash(0x7fffffff, 0), 3);
  assert.equal(hasCollectibleModSlowHash(0x7fffffff, 8), 4);
  assert.equal(hasCollectibleModSlowHash(0x7fffffff, 0xff), 4);
  assert.equal(hasCollectibleModSlowHash(0x80000000, 0), 4);
  assert.equal(hasCollectibleModSlowHash(0x2e6, 9), 2);
  assert.equal(hasCollectibleModSlowHash(0xffffffff, 1), 2); // sum wraps to 0 -> v = 1
  assert.equal(hasCollectibleModSlowFatal(0), 1);
  assert.equal(hasCollectibleModSlowFatal(1), 0);

  // resolve plan: fast path is pure even with count 0 (never reads the count)
  const fastLow = hasCollectibleModResolvePlan({ ...pass, bufByte: 3 });
  assert.equal(fastLow.scanActive, 1);
  assert.equal(fastLow.mode, 3);
  assert.equal(fastLow.fastApplicable, 1);
  assert.equal(fastLow.fastResult, 1);
  assert.equal(fastLow.result, 1);
  assert.equal(fastLow.resultKnown, 1);
  assert.equal(fastLow.pureComplete, 1);
  assert.equal(fastLow.hostNeeded, 0);
  const fastZeroCount = hasCollectibleModResolvePlan({ ...pass, bufByte: 3, countKnown: 1, gameCount: 0 });
  assert.equal(fastZeroCount.pureComplete, 1); // count irrelevant on fast path
  // slow with unknown count -> host needed
  const slowUnknown = hasCollectibleModResolvePlan({ ...pass, bufByte: 8, countKnown: 0 });
  assert.equal(slowUnknown.fastApplicable, 0);
  assert.equal(slowUnknown.hostNeeded, 1);
  assert.equal(slowUnknown.resultKnown, 0);
  assert.equal(slowUnknown.pureComplete, 0);
  // slow with count 0 -> host fatal (0x00a112c0 residual)
  const slowFatal = hasCollectibleModResolvePlan({ ...pass, bufByte: 8, countKnown: 1, gameCount: 0 });
  assert.equal(slowFatal.slowFatal, 1);
  assert.equal(slowFatal.hostNeeded, 1);
  assert.equal(slowFatal.pureComplete, 0);
  assert.equal(slowFatal.resultKnown, 0);
  // slow with count != 0 -> pure hash result
  const slowPure = hasCollectibleModResolvePlan({ ...pass, bufByte: 8, countKnown: 1, gameCount: 5 });
  assert.equal(slowPure.slowFatal, 0);
  assert.equal(slowPure.result, hasCollectibleModSlowHash(5, 8));
  assert.equal(slowPure.pureComplete, 1);
  // count 0x80000000 is not fatal (only ==0) and hashes in the slow path
  const slowBig = hasCollectibleModResolvePlan({ ...pass, bufByte: 8, countKnown: 1, gameCount: 0x80000000 });
  assert.equal(slowBig.slowFatal, 0);
  assert.equal(slowBig.result, hasCollectibleModSlowHash(0x80000000, 8));
});

test("v16 mod resolver native/Wasm differential + mutation pins", () => {
  const exp = loadExports();
  const view = new DataView(exp.memory.buffer);
  assert.equal(exp.abi(), 39);
  assert.equal(exp.va7db860() >>> 0, 0x007db860);
  assert.equal(exp.vaScan4288a0() >>> 0, 0x004288a0);
  // wasm pinned vectors mirror the JS oracle
  assert.equal(exp.modFastRes(0), -1);
  assert.equal(exp.modFastRes(1), -1);
  assert.equal(exp.modFastRes(2), 0);
  assert.equal(exp.modFastRes(7), 5);
  assert.equal(exp.modFastApp(8), 0);
  assert.equal(exp.modFastApp(7), 1);
  assert.equal(exp.modSlowHash(0x7fffffff, 8), 4);
  assert.equal(exp.modSlowHash(0x7fffffff, 0), 3);
  assert.equal(exp.modSlowHash(0, 8), 2);
  assert.equal(exp.modSlowHash(0xffffffff, 1), 2);
  assert.equal(exp.modSlowFatal(0), 1);
  assert.equal(exp.modSlowFatal(1), 0);
  assert.equal(exp.modScanActive(0, 0x4f, 0, 0x100, 0x190), hasCollectibleModScanActive({ lastNodeDisabled: 0, lastNodeValue: 0x4f, lastNodeIsHead: 0, bufBegin: 0x100, bufEnd: 0x190 }));
  assert.equal(exp.modScanActive(0x100, 0x4f, 0, 0x100, 0x190), 1); // low byte 0 -> not disabled
  assert.equal(exp.modScanActive(0x101, 0x4f, 0, 0x100, 0x190), 0); // low byte 1 -> disabled
  assert.equal(exp.modScanActive(0, 0x50, 0, 0x100, 0x190), 0);
  assert.equal(exp.modScanActive(0, 0x4f, 1, 0x100, 0x190), 0);
  assert.equal(exp.modScanActive(0, 0x4f, 0, 0x100, 0x100 + 0x8f), 0); // span == 0x8f
  assert.equal(exp.modScanActive(0, 0x4f, 0, 0x100, 0x100 + 0x90), 1); // span == 0x90
  assert.equal(exp.modScanActive(0, 0x4f, 0, 0x10, 0x4), 0); // signed span
  assert.equal(exp.modScanMode(0, 0x4f, 0, 0x100, 0x190, 0x100), 0);
  assert.equal(exp.modScanMode(0, 0x4f, 0, 0x100, 0x190, 0x7f), 0x7f);

  const planPtr = 0x107000;
  const disableds = [0, 1, 0x100];
  const values = [0x4e, 0x4f, 0x50, 0x100];
  const heads = [0, 1];
  const spans = [[0x100, 0x190], [0x100, 0x100 + 0x8f], [0x100, 0x100 + 0x90], [0x10, 0x4]];
  const bytes = [0, 1, 2, 3, 7, 8, 9, 0x7f, 0x80, 0xff, 0x100];
  const counts = [0, 1, 5, 0x2e6, 0x7fffffff, 0x80000000, 0xffffffff];
  const knowns = [0, 1];
  let n = 0;
  for (const d of disableds) {
    for (const v of values) {
      for (const h of heads) {
        for (const [b0, b1] of spans) {
          for (const by of bytes) {
            for (const ck of knowns) {
              for (const gc of counts) {
                exp.modResolvePlan(d >>> 0, v >>> 0, h >>> 0, b0 >>> 0, b1 >>> 0, by | 0, ck | 0, gc | 0, planPtr);
                const js = hasCollectibleModResolvePlan({
                  lastNodeDisabled: d, lastNodeValue: v, lastNodeIsHead: h,
                  bufBegin: b0, bufEnd: b1, bufByte: by, countKnown: ck, gameCount: gc,
                });
                const label = `${d}/${v}/${h}/${b0}/${b1}/${by}/${ck}/${gc}`;
                assert.equal(readI32(view, planPtr + 0), js.scanActive, `${label} active`);
                assert.equal(readI32(view, planPtr + 4), js.mode, `${label} mode`);
                assert.equal(readI32(view, planPtr + 8), js.fastApplicable, `${label} fast`);
                assert.equal(readI32(view, planPtr + 12), js.fastResult, `${label} fres`);
                assert.equal(readI32(view, planPtr + 16), js.slowFatal, `${label} fatal`);
                assert.equal(readI32(view, planPtr + 20), js.slowHash, `${label} hash`);
                assert.equal(readI32(view, planPtr + 24), js.result, `${label} res`);
                assert.equal(readI32(view, planPtr + 28), js.resultKnown, `${label} rk`);
                assert.equal(readI32(view, planPtr + 32), js.hostNeeded, `${label} host`);
                assert.equal(readI32(view, planPtr + 36), js.pureComplete, `${label} pure`);
                n += 1;
              }
            }
          }
        }
      }
    }
  }
  assert.ok(n >= 3 * 4 * 2 * 4 * 11 * 2 * 7);
});

test("header documents v17 0x00771550 narrowed gates", () => {
  const h = readFileSync(header, "utf8");
  assert.match(h, /Helpers ABI v17/);
  assert.match(h, /ISAAC_HUD_POST_UPDATE_PURE_HELPERS_ABI_VERSION = 39/);
  assert.match(h, /0x00771550/);
  assert.match(h, /mem-stores 0/);
  assert.match(h, /IsaacHasCollectible771550Plan/);
  assert.match(h, /isaac_has_collectible_771550_owned/);
  assert.match(h, /isaac_has_collectible_771550_plan/);
  assert.match(h, /0x7cb6e0/);
  assert.match(h, /0x16c0/);
  assert.match(h, /short.?circuit/i);
  assert.doesNotMatch(h, /ISAAC_HUD_POST_UPDATE_PURE_HELPERS_ABI_VERSION = 16/);
  const s = readFileSync(source, "utf8");
  assert.match(s, /Helpers ABI v17/);
  assert.match(s, /0x00771612/);
  assert.match(s, /setg/);
  assert.match(s, /0x1ca/);
  assert.equal(HUD_POST_UPDATE_PURE_ABI_VERSION, 39);
  assert.equal(HAS_COLLECTIBLE_771550_FIELD_OFF, 0x2ef8);
  assert.equal(HAS_COLLECTIBLE_771550_BYTE_OFF, 0x2ef0);
  assert.equal(HAS_COLLECTIBLE_771550_SLOT_BASE_OFF, 0x16c0);
  assert.equal(HAS_COLLECTIBLE_771550_SLOT_STRIDE, 4);
  assert.equal(HAS_COLLECTIBLE_771550_SLOT_MASK, 0x7fff);
  assert.equal(HAS_COLLECTIBLE_771550_WHICH_8B, 0x8b);
  assert.equal(HAS_COLLECTIBLE_771550_WHICH_1CA, 0x1ca);
  assert.equal(HAS_COLLECTIBLE_771550_STRICT_CMP, 1);
});

test("JS oracle: v17 0x00771550 owned / strict / count / scan gates", () => {
  // owned: f != 0 && f == id && byte != 0 (byte gate low-byte)
  assert.equal(hasCollectible771550Owned(0x15, 1, 0x15), 1);
  assert.equal(hasCollectible771550Owned(0x15, 0x100, 0x15), 0); // byte low 0
  assert.equal(hasCollectible771550Owned(0, 1, 0x15), 0);
  assert.equal(hasCollectible771550Owned(0x16, 1, 0x15), 0);
  assert.equal(hasCollectible771550Owned(0x15, 1, 0x150), 0); // id full dword
  // strict: f != 0 && f == id && byte == 0
  assert.equal(hasCollectible771550Strict(0x15, 0, 0x15), 1);
  assert.equal(hasCollectible771550Strict(0x15, 0x101, 0x15), 0); // byte low 1
  assert.equal(hasCollectible771550Strict(0, 0, 0x15), 0);
  assert.equal(hasCollectible771550Strict(0x15, 0, 0x16), 0);
  // count compare SIGNED: strict -> count > 1; loose -> count > 0
  assert.equal(hasCollectible771550CountGt(0, 0), 0);
  assert.equal(hasCollectible771550CountGt(1, 0), 1);
  assert.equal(hasCollectible771550CountGt(1, 1), 0);
  assert.equal(hasCollectible771550CountGt(2, 1), 1);
  assert.equal(hasCollectible771550CountGt(-1, 0), 0); // signed
  assert.equal(hasCollectible771550CountGt(-1, 1), 0);
  assert.equal(hasCollectible771550CountGt(0x7fffffff, 1), 1);
  assert.equal(hasCollectible771550CountGt(0x80000000 | 0, 0), 0); // negative
  // scan width: 1 + (has_8b || has_1ca), byte-masked
  assert.equal(hasCollectible771550ScanWidth(0, 0), 1);
  assert.equal(hasCollectible771550ScanWidth(1, 0), 2);
  assert.equal(hasCollectible771550ScanWidth(0, 1), 2);
  assert.equal(hasCollectible771550ScanWidth(0x100, 0), 1); // byte low 0
  assert.equal(hasCollectible771550ScanWidth(0, 0x101), 2);
  // slot mask 0x7fff
  assert.equal(hasCollectible771550SlotMatch(0x15, 0x15), 1);
  assert.equal(hasCollectible771550SlotMatch(0x8015, 0x15), 1); // upper bit masked
  assert.equal(hasCollectible771550SlotMatch(0x8015, 0x8015 >>> 0), 0);
  // scan result: UNSIGNED loop over first `width` slots
  assert.equal(hasCollectible771550ScanResult(0x15, 0x16, 1, 0x16), 0);
  assert.equal(hasCollectible771550ScanResult(0x15, 0x16, 2, 0x16), 1);
  assert.equal(hasCollectible771550ScanResult(0x15, 0x16, 2, 0x15), 1);
  assert.equal(hasCollectible771550ScanResult(0x15, 0x16, 1, 0x15), 1);
  assert.equal(hasCollectible771550ScanResult(0, 0, 0, 0x15), 0); // width 0
  assert.equal(hasCollectible771550ScanResult(0, 0, -1, 0x15), 0); // unsigned bound
});

test("v17 0x00771550 native/Wasm differential + mutation pins", () => {
  const exp = loadExports();
  const view = new DataView(exp.memory.buffer);
  assert.equal(exp.abi(), 39);
  assert.equal(exp.hc771550FieldOff() >>> 0, HAS_COLLECTIBLE_771550_FIELD_OFF);
  assert.equal(exp.hc771550ByteOff() >>> 0, HAS_COLLECTIBLE_771550_BYTE_OFF);
  assert.equal(exp.hc771550SlotBaseOff() >>> 0, HAS_COLLECTIBLE_771550_SLOT_BASE_OFF);
  assert.equal(exp.hc771550SlotStride(), HAS_COLLECTIBLE_771550_SLOT_STRIDE);
  assert.equal(exp.hc771550SlotMask() >>> 0, HAS_COLLECTIBLE_771550_SLOT_MASK);
  assert.equal(exp.hc771550Which8b() >>> 0, HAS_COLLECTIBLE_771550_WHICH_8B);
  assert.equal(exp.hc771550Which1ca() >>> 0, HAS_COLLECTIBLE_771550_WHICH_1CA);

  // wasm pinned vectors mirror the JS oracle
  assert.equal(exp.hc771550Owned(0x15, 1, 0x15), 1);
  assert.equal(exp.hc771550Owned(0x15, 0x100, 0x15), 0);
  assert.equal(exp.hc771550Owned(0, 1, 0x15), 0);
  assert.equal(exp.hc771550Strict(0x15, 0, 0x15), 1);
  assert.equal(exp.hc771550Strict(0x15, 0x101, 0x15), 0);
  assert.equal(exp.hc771550CountGt(1, 0), 1);
  assert.equal(exp.hc771550CountGt(1, 1), 0);
  assert.equal(exp.hc771550CountGt(-1, 0), 0);
  assert.equal(exp.hc771550ScanWidth(0, 1), 2);
  assert.equal(exp.hc771550ScanWidth(0x100, 0), 1);
  assert.equal(exp.hc771550SlotMatch(0x8015, 0x15), 1);
  assert.equal(exp.hc771550ScanResult(0x15, 0x16, 2, 0x16), 1);
  assert.equal(exp.hc771550ScanResult(0x15, 0x16, 1, 0x16), 0);

  const planPtr = 0x108000;
  const fields = [0, 0x15, 0x16, 0x1000];
  const bytes = [0, 1, 0x100, 0x101, 0xff];
  const ids = [0x15, 0x16, 0x5d];
  const flags = [0, 1, 0x100];
  const cntKs = [0, 1];
  const counts = [0, 1, 2, -1, 0x7fffffff, 0x80000000 | 0];
  const h8Ks = [0, 1];
  const h8s = [0, 1, 0x100];
  const h1Ks = [0, 1];
  const h1s = [0, 1, 0x101];
  const slots0 = [0, 0x15, 0x8015];
  const slots1 = [0, 0x16, 0x8016];
  let n = 0;
  for (const f of fields) {
    for (const b of bytes) {
      for (const id of ids) {
        for (const fl of flags) {
          for (const ck of cntKs) {
            for (const c of counts) {
              for (const h8k of h8Ks) {
                for (const h8 of h8s) {
                  for (const h1k of h1Ks) {
                    for (const h1 of h1s) {
                      for (const s0 of slots0) {
                        for (const s1 of slots1) {
                          exp.hc771550Plan(f >>> 0, b | 0, id >>> 0, fl | 0, ck | 0, c | 0, h8k | 0, h8 | 0, h1k | 0, h1 | 0, s0 >>> 0, s1 >>> 0, planPtr);
                          const js = hasCollectible771550Plan({
                            field2ef8: f, byte2ef0: b, id, flag: fl,
                            countKnown: ck, count: c,
                            has8bKnown: h8k, has8b: h8, has1caKnown: h1k, has1ca: h1,
                            slot0: s0, slot1: s1,
                          });
                          const label = `${f}/${b}/${id}/${fl}/${ck}/${c}/${h8k}/${h8}/${h1k}/${h1}/${s0}/${s1}`;
                          assert.equal(readI32(view, planPtr + 0), js.owned, `${label} owned`);
                          assert.equal(readI32(view, planPtr + 4), js.strict, `${label} strict`);
                          assert.equal(readI32(view, planPtr + 8), js.host7cb6e0, `${label} hostcount`);
                          assert.equal(readI32(view, planPtr + 12), js.countKnown, `${label} ck`);
                          assert.equal(readI32(view, planPtr + 16), js.count, `${label} count`);
                          assert.equal(readI32(view, planPtr + 20), js.hostHas8b, `${label} h8b`);
                          assert.equal(readI32(view, planPtr + 24), js.hostHas1ca, `${label} h1ca`);
                          assert.equal(readI32(view, planPtr + 28), js.scanWidth, `${label} width`);
                          assert.equal(readI32(view, planPtr + 32), js.scanResult, `${label} sres`);
                          assert.equal(readI32(view, planPtr + 36), js.result, `${label} res`);
                          assert.equal(readI32(view, planPtr + 40), js.resultKnown, `${label} rk`);
                          assert.equal(readI32(view, planPtr + 44), js.hostNeeded, `${label} host`);
                          assert.equal(readI32(view, planPtr + 48), js.pureComplete, `${label} pure`);
                          n += 1;
                        }
                      }
                    }
                  }
                }
              }
            }
          }
        }
      }
    }
  }
  assert.ok(n >= 4 * 5 * 3 * 3 * 2 * 6 * 2 * 3 * 2 * 3 * 3 * 3);

  // mutation pin: the early-TRUE gate must fire BEFORE the flag dispatch
  // (owned == 1 -> pure result regardless of flag/count/samples).
  exp.hc771550Plan(0x15, 1, 0x15, 0, 0, 0, 0, 0, 0, 0, 0, 0, planPtr);
  assert.equal(readI32(view, planPtr + 0), 1);   // owned
  assert.equal(readI32(view, planPtr + 40), 1);  // result_known
  assert.equal(readI32(view, planPtr + 36), 1);  // result
  assert.equal(readI32(view, planPtr + 44), 0);  // host_needed
  assert.equal(readI32(view, planPtr + 48), 1);  // pure_complete
  // flag==0 with count sample: pure result, count > strict ? 1 : 0
  exp.hc771550Plan(0x15, 0, 0x15, 0, 1, 2, 0, 0, 0, 0, 0, 0, planPtr);
  assert.equal(readI32(view, planPtr + 4), 1);   // strict
  assert.equal(readI32(view, planPtr + 8), 1);   // host_7cb6e0
  assert.equal(readI32(view, planPtr + 36), 1);  // 2 > 1
  assert.equal(readI32(view, planPtr + 44), 0);
  // flag!=0, has_8b TRUE short-circuits (host_has_1ca stays 0)
  exp.hc771550Plan(0, 0, 0x15, 1, 0, 0, 1, 1, 0, 0, 0, 0, planPtr);
  assert.equal(readI32(view, planPtr + 20), 1);  // host_has_8b
  assert.equal(readI32(view, planPtr + 24), 0);  // host_has_1ca (short-circuit)
  assert.equal(readI32(view, planPtr + 28), 2);  // width
  // flag!=0, has_8b FALSE -> 0x1ca sample needed
  exp.hc771550Plan(0, 0, 0x15, 1, 0, 0, 1, 0, 1, 1, 0, 0, planPtr);
  assert.equal(readI32(view, planPtr + 24), 1);
  assert.equal(readI32(view, planPtr + 28), 2);
  // flag!=0, has_8b FALSE, 0x1ca FALSE -> width 1, scan slot0 only
  exp.hc771550Plan(0, 0, 0x16, 1, 0, 0, 1, 0, 1, 0, 0x16, 0x16, planPtr);
  assert.equal(readI32(view, planPtr + 28), 1);
  assert.equal(readI32(view, planPtr + 32), 1);  // slot0 (0x16) matches id
  exp.hc771550Plan(0, 0, 0x16, 1, 0, 0, 1, 0, 1, 0, 0x15, 0x16, planPtr);
  assert.equal(readI32(view, planPtr + 32), 0);  // width 1: slot1 not read
  // flag!=0 unknown samples -> host_needed
  exp.hc771550Plan(0, 0, 0x15, 1, 0, 0, 0, 0, 0, 0, 0, 0, planPtr);
  assert.equal(readI32(view, planPtr + 44), 1);
});

