test("JS oracle: v23 preamble walk + player-eligible gate (0x7cb6fb..0x7cb733)", () => {
  // walk_active: FULL-WORD == 1 (0x7cb6fb cmp dword) — 0x101 must NOT walk.
  assert.equal(hudCount7cb6e0WalkActive(1), 1);
  assert.equal(hudCount7cb6e0WalkActive(0), 0);
  assert.equal(hudCount7cb6e0WalkActive(0x100), 0);
  assert.equal(hudCount7cb6e0WalkActive(0x101), 0);
  assert.equal(hudCount7cb6e0WalkActive(0xffffffff), 0);
  // m3bc eligible: non-null && +0x28 == 1 (full dword, 0x7cb70b).
  assert.equal(hudCount7cb6e0M3bcEligible(0x3000, 1), 1);
  assert.equal(hudCount7cb6e0M3bcEligible(0, 1), 0);
  assert.equal(hudCount7cb6e0M3bcEligible(0x3000, 0), 0);
  assert.equal(hudCount7cb6e0M3bcEligible(0x3000, 0x101), 0);
  assert.equal(hudCount7cb6e0M3bcEligible(0x3000, 0xffffffff), 0);

  const mem = new ArrayBuffer(0x8000);
  const view = new DataView(mem);
  const put = (addr, off, v) => view.setUint32(addr + off, v >>> 0, true);
  const S = 0x1000;

  // (A) gate closed: field_2c == 0x101 -> no walk, resolved = input player.
  const PA = 0x200;
  put(PA, HUD_COUNT_7CB6E0_FIELD_2C_OFF, 0x101);
  assert.deepEqual(hudCount7cb6e0WalkPlan(view, PA, S, 4, 16), {
    resolvedPlayer: PA, walkActive: 0, iterations: 0, hostEdges: 0,
    truncated: 0, stoppedNull: 0, hostNeeded: 0,
  });

  // (B) m3bc chain with no GetPlayer edges (candidate +0x28 == 1 both hops).
  const PB0 = 0x400, PB1 = 0x600, PB2 = 0x800;
  put(PB0, HUD_COUNT_7CB6E0_FIELD_2C_OFF, 1);
  put(PB0, HUD_COUNT_7CB6E0_FIELD_3BC_OFF, PB1);
  put(PB1, HUD_COUNT_7CB6E0_FIELD_28_OFF, 1);
  put(PB1, HUD_COUNT_7CB6E0_FIELD_2C_OFF, 1);
  put(PB1, HUD_COUNT_7CB6E0_FIELD_3BC_OFF, PB2);
  put(PB2, HUD_COUNT_7CB6E0_FIELD_28_OFF, 1);
  put(PB2, HUD_COUNT_7CB6E0_FIELD_2C_OFF, 0); // chain ends (0x7cb72e fallthrough)
  assert.deepEqual(hudCount7cb6e0WalkPlan(view, PB0, S, 4, 16), {
    resolvedPlayer: PB2, walkActive: 1, iterations: 2, hostEdges: 0,
    truncated: 0, stoppedNull: 0, hostNeeded: 0,
  });

  // (C) m3bc null -> GetPlayer(0) sample consumed; result field_2c 0 ends.
  const PC0 = 0xa00;
  put(PC0, HUD_COUNT_7CB6E0_FIELD_2C_OFF, 1);
  put(PC0, HUD_COUNT_7CB6E0_FIELD_3BC_OFF, 0);
  put(S + 0, 0, 1);      // known
  put(S + 0, 4, 0xc00);  // result
  put(0xc00, HUD_COUNT_7CB6E0_FIELD_2C_OFF, 0);
  assert.deepEqual(hudCount7cb6e0WalkPlan(view, PC0, S, 4, 16), {
    resolvedPlayer: 0xc00, walkActive: 1, iterations: 1, hostEdges: 1,
    truncated: 0, stoppedNull: 0, hostNeeded: 0,
  });

  // (D) sample unknown -> host_needed, resolved stays the current player.
  put(S + 0, 0, 0);
  assert.deepEqual(hudCount7cb6e0WalkPlan(view, PC0, S, 4, 16), {
    resolvedPlayer: PC0, walkActive: 1, iterations: 0, hostEdges: 1,
    truncated: 0, stoppedNull: 0, hostNeeded: 1,
  });

  // (E) sample null result -> stopped_null (0x7cb726 je 0x7cb730).
  put(S + 0, 0, 1);
  put(S + 0, 4, 0);
  assert.deepEqual(hudCount7cb6e0WalkPlan(view, PC0, S, 4, 16), {
    resolvedPlayer: PC0, walkActive: 1, iterations: 0, hostEdges: 1,
    truncated: 0, stoppedNull: 1, hostNeeded: 0,
  });

  // (F) samples exhausted -> host_needed.
  assert.deepEqual(hudCount7cb6e0WalkPlan(view, PC0, S, 0, 16), {
    resolvedPlayer: PC0, walkActive: 1, iterations: 0, hostEdges: 0,
    truncated: 0, stoppedNull: 0, hostNeeded: 1,
  });

  // (G) iterations >= iter_cap on a continuing chain -> truncated.
  const PG0 = 0xe00, PG1 = 0x1000, PG2 = 0x1200;
  put(PG0, HUD_COUNT_7CB6E0_FIELD_2C_OFF, 1);
  put(PG0, HUD_COUNT_7CB6E0_FIELD_3BC_OFF, PG1);
  put(PG1, HUD_COUNT_7CB6E0_FIELD_28_OFF, 1);
  put(PG1, HUD_COUNT_7CB6E0_FIELD_2C_OFF, 1);
  put(PG1, HUD_COUNT_7CB6E0_FIELD_3BC_OFF, PG2);
  put(PG2, HUD_COUNT_7CB6E0_FIELD_28_OFF, 1);
  put(PG2, HUD_COUNT_7CB6E0_FIELD_2C_OFF, 1); // would continue past cap
  assert.deepEqual(hudCount7cb6e0WalkPlan(view, PG0, S, 4, 2), {
    resolvedPlayer: PG2, walkActive: 1, iterations: 2, hostEdges: 0,
    truncated: 1, stoppedNull: 0, hostNeeded: 0,
  });
  // zero cap: truncate after the FIRST adoption.
  assert.deepEqual(hudCount7cb6e0WalkPlan(view, PG0, S, 4, 0), {
    resolvedPlayer: PG1, walkActive: 1, iterations: 1, hostEdges: 0,
    truncated: 1, stoppedNull: 0, hostNeeded: 0,
  });
});

test("JS oracle: v23 RNG-draw + twin/recursion PREP laws (0x7cb865..0x7cb8b7)", () => {
  // rng gate: full dword != 0 (0x7cb875).
  assert.equal(hudCount7cb6e0RngGate(0), 0);
  assert.equal(hudCount7cb6e0RngGate(1), 1);
  assert.equal(hudCount7cb6e0RngGate(0x100), 1);
  // rng prep: 16-byte RandomInt receiver (seed = room, consts from
  // qword[0xb1f564] = {2,7}, dword[0xb1f56c] = 0x19).
  assert.deepEqual(hudCount7cb6e0RngPrep(0x1234), { seed: 0x1234, aLo: 0x2, aHi: 0x7, b: 0x19 });
  assert.deepEqual(hudCount7cb6e0RngPrep(0xffffffff), { seed: 0xffffffff, aLo: 0x2, aHi: 0x7, b: 0x19 });
  assert.equal(hudCount7cb6e0RngMax(), 0xbd);
  // room prep: receiver = Game, idx = [Game+0x18304], arg2 = -1.
  assert.deepEqual(hudCount7cb6e0RoomPrep(0xc71678, 0x42), { receiver: 0xc71678, idx: 0x42, arg2: -1 });
  assert.deepEqual(hudCount7cb6e0RoomPrep(0x1000, 0xffffffff), { receiver: 0x1000, idx: 0xffffffff, arg2: -1 });
  // 4b chain: gate && known && (rng+1 & 0xffffffff) == idm -> count4b.
  assert.equal(hudCount7cb6e04bChain(0x100, 1, 0xa, 3, 0xb), 3);  // 0xa+1 == 0xb
  assert.equal(hudCount7cb6e04bChain(0x100, 1, 0xb, 3, 0xb), 0);  // 0xb+1 != 0xb
  assert.equal(hudCount7cb6e04bChain(0x100, 0, 0xb, 3, 0xb), 0);
  assert.equal(hudCount7cb6e04bChain(0, 1, 0xa, 3, 0xb), 0);
  assert.equal(hudCount7cb6e04bChain(0x100, 1, 0xffffffff, 3, 0), 3); // inc wraps u32
  assert.equal(hudCount7cb6e04bChain(0x100, 1, 0x7fff, 3, 0), 0); // +1 crosses 0x7fff unmasked
  // twin17 prep: receiver = p+0x1508 (32-bit wrap), arg = 0x17.
  assert.deepEqual(hudCount7cb6e0Twin17Prep(0x2000), { receiver: 0x3508, arg: 0x17 });
  assert.deepEqual(hudCount7cb6e0Twin17Prep(0xfffff000), { receiver: 0x508, arg: 0x17 });
  // recurse prep: receiver = resolved player verbatim, arg = id VERBATIM
  // (the machine pushes constants; no 0x7fff mask).
  assert.deepEqual(hudCount7cb6e0RecursePrep(0x3000, 0x15), { receiver: 0x3000, arg: 0x15 });
  assert.deepEqual(hudCount7cb6e0RecursePrep(0x3000, 0x10040), { receiver: 0x3000, arg: 0x10040 });
});

test("v23 0x007cb6e0 walk/RNG/twin native/Wasm differential + mutation pins", () => {
  const exp = loadExports();
  const view = new DataView(exp.memory.buffer);
  assert.equal(exp.abi(), 39);

  // constant accessors
  assert.equal(exp.cntRngConstVa() >>> 0, HUD_COUNT_7CB6E0_RNG_CONST_VA);
  assert.equal(exp.cntRngConstALo() >>> 0, HUD_COUNT_7CB6E0_RNG_CONST_A_LO);
  assert.equal(exp.cntRngConstAHi() >>> 0, HUD_COUNT_7CB6E0_RNG_CONST_A_HI);
  assert.equal(exp.cntRngConstB() >>> 0, HUD_COUNT_7CB6E0_RNG_CONST_B);
  assert.equal(exp.cntRngMax() >>> 0, HUD_COUNT_7CB6E0_RNG_MAX);
  assert.equal(exp.cntField2cOff() >>> 0, HUD_COUNT_7CB6E0_FIELD_2C_OFF);
  assert.equal(exp.cntField3bcOff() >>> 0, HUD_COUNT_7CB6E0_FIELD_3BC_OFF);
  assert.equal(exp.cntField28Off() >>> 0, HUD_COUNT_7CB6E0_FIELD_28_OFF);
  assert.equal(exp.cntGameRoomIdxOff() >>> 0, HUD_COUNT_7CB6E0_GAME_ROOM_IDX_OFF);
  assert.equal(exp.cntRoomField5cOff() >>> 0, HUD_COUNT_7CB6E0_ROOM_FIELD_5C_OFF);
  assert.equal(exp.cntTwinRecvOff() >>> 0, HUD_COUNT_7CB6E0_TWIN_RECV_OFF);
  assert.equal(exp.cntVaWalkGate() >>> 0, HUD_COUNT_7CB6E0_VA_WALK_GATE);
  assert.equal(exp.cntVaGetPlayerCall() >>> 0, HUD_COUNT_7CB6E0_VA_GETPLAYER_CALL);
  assert.equal(exp.cntVaRoomCall() >>> 0, HUD_COUNT_7CB6E0_VA_ROOM_CALL);
  assert.equal(exp.cntVaRngGate() >>> 0, HUD_COUNT_7CB6E0_VA_RNG_GATE);
  assert.equal(exp.cntVaRngCall() >>> 0, HUD_COUNT_7CB6E0_VA_RNG_CALL);
  assert.equal(exp.cntVaTwin17Call() >>> 0, HUD_COUNT_7CB6E0_VA_TWIN17_CALL);
  assert.equal(exp.cntWalkIterCap() >>> 0, HUD_COUNT_7CB6E0_WALK_ITER_CAP);

  // scalar laws
  assert.equal(exp.cntWalkActive(1), 1);
  assert.equal(exp.cntWalkActive(0), 0);
  assert.equal(exp.cntWalkActive(0x101), 0);
  assert.equal(exp.cntM3bcEligible(0x3000, 1), 1);
  assert.equal(exp.cntM3bcEligible(0x3000, 0x101), 0);
  assert.equal(exp.cntRngGate(0), 0);
  assert.equal(exp.cntRngGate(0x100), 1);
  assert.equal(exp.cnt4bChain(0x100, 1, 0xa, 3, 0xb), 3);
  assert.equal(exp.cnt4bChain(0x100, 1, 0xb, 3, 0xb), 0);
  assert.equal(exp.cnt4bChain(0x100, 0, 0xb, 3, 0xb), 0);
  assert.equal(exp.cnt4bChain(0, 1, 0xa, 3, 0xb), 0);
  assert.equal(exp.cnt4bChain(0x100, 1, 0xffffffff, 3, 0), 3);
  assert.equal(exp.cnt4bChain(0x100, 1, 0x7fff, 3, 0), 0);

  // struct / out-param preps
  const B = 0x5f0000;
  const planOut = B + 0x3000;
  exp.cntRngPrep(0x1234, planOut);
  assert.equal(readU32(view, planOut + RNG3.seed), 0x1234);
  assert.equal(readU32(view, planOut + RNG3.aLo), 0x2);
  assert.equal(readU32(view, planOut + RNG3.aHi), 0x7);
  assert.equal(readU32(view, planOut + RNG3.b), 0x19);
  exp.cntRngPrep(0xffffffff, planOut);
  assert.equal(readU32(view, planOut + RNG3.seed), 0xffffffff);
  assert.equal(readU32(view, planOut + RNG3.b), 0x19);
  exp.cntRoomPrep(0xc71678, 0x42, planOut + 0x40, planOut + 0x44, planOut + 0x48);
  assert.equal(readU32(view, planOut + 0x40), 0xc71678);
  assert.equal(readI32(view, planOut + 0x44), 0x42);
  assert.equal(readI32(view, planOut + 0x48), -1);
  exp.cntRoomPrep(0x1000, 0xffffffff, planOut + 0x40, planOut + 0x44, planOut + 0x48);
  assert.equal(readI32(view, planOut + 0x44), -1); // idx wraps to int -1
  exp.cntTwin17Prep(0x2000, planOut + 0x80, planOut + 0x84);
  assert.equal(readU32(view, planOut + 0x80), 0x3508);
  assert.equal(readU32(view, planOut + 0x84), 0x17);
  exp.cntTwin17Prep(0xfffff000, planOut + 0x80, planOut + 0x84);
  assert.equal(readU32(view, planOut + 0x80), 0x508); // 32-bit wrap
  exp.cntRecursePrep(0x3000, 0x10040, planOut + 0x80, planOut + 0x84);
  assert.equal(readU32(view, planOut + 0x80), 0x3000);
  assert.equal(readU32(view, planOut + 0x84), 0x10040); // verbatim, no mask

  // walk plan differential (wasm vs JS trace) over an image matrix
  const S = B + 0x2000;
  const P = (i) => (B + 0x100 + i * 0x200) >>> 0;
  const writePlayer = (addr, { f2c, m3bc, f28 }) => {
    writeU32(view, addr + HUD_COUNT_7CB6E0_FIELD_2C_OFF, f2c >>> 0);
    writeU32(view, addr + HUD_COUNT_7CB6E0_FIELD_3BC_OFF, m3bc >>> 0);
    writeU32(view, addr + HUD_COUNT_7CB6E0_FIELD_28_OFF, f28 >>> 0);
  };
  const writeSample = (idx, known, result) => {
    writeU32(view, S + idx * HUD_COUNT_7CB6E0_WALK_SAMPLE_STRIDE, known >>> 0);
    writeU32(view, S + idx * HUD_COUNT_7CB6E0_WALK_SAMPLE_STRIDE + 4, result >>> 0);
  };
  const runWalk = (playerPtr, samplesCount, iterCap, label) => {
    exp.cntWalkPlan(playerPtr >>> 0, S >>> 0, samplesCount >>> 0, iterCap >>> 0, planOut);
    const w = readWalkPlan3(view, planOut);
    const o = hudCount7cb6e0WalkPlan(view, playerPtr >>> 0, S >>> 0, samplesCount >>> 0, iterCap >>> 0);
    for (const k of Object.keys(w)) {
      assert.equal(w[k], o[k], `${label} ${k}`);
    }
    return w;
  };

  // gate closed (wide field_2c)
  writePlayer(P(0), { f2c: 0x101, m3bc: 0, f28: 0 });
  let w = runWalk(P(0), 4, 16, "closed");
  assert.equal(w.walkActive, 0);
  assert.equal(w.resolvedPlayer >>> 0, P(0));

  // m3bc chain, zero GetPlayer edges
  writePlayer(P(0), { f2c: 1, m3bc: P(1), f28: 0 });
  writePlayer(P(1), { f2c: 1, m3bc: P(2), f28: 1 });
  writePlayer(P(2), { f2c: 0, m3bc: 0, f28: 1 });
  w = runWalk(P(0), 4, 16, "chain");
  assert.equal(w.resolvedPlayer >>> 0, P(2));
  assert.equal(w.iterations, 2);
  assert.equal(w.hostEdges, 0);

  // m3bc ineligible (wide +0x28) -> GetPlayer sample; result ends chain
  writePlayer(P(0), { f2c: 1, m3bc: P(1), f28: 0 });
  writePlayer(P(1), { f2c: 1, m3bc: 0, f28: 0x101 });
  writePlayer(P(2), { f2c: 0, m3bc: 0, f28: 1 });
  writeSample(0, 1, P(2));
  w = runWalk(P(0), 4, 16, "sample");
  assert.equal(w.resolvedPlayer >>> 0, P(2));
  assert.equal(w.iterations, 1);
  assert.equal(w.hostEdges, 1);
  assert.equal(w.hostNeeded, 0);

  // unknown sample
  writeSample(0, 0, P(2));
  w = runWalk(P(0), 4, 16, "unknown");
  assert.equal(w.resolvedPlayer >>> 0, P(0));
  assert.equal(w.hostEdges, 1);
  assert.equal(w.hostNeeded, 1);
  assert.equal(w.stoppedNull, 0);

  // null sample
  writeSample(0, 1, 0);
  w = runWalk(P(0), 4, 16, "null");
  assert.equal(w.resolvedPlayer >>> 0, P(0));
  assert.equal(w.stoppedNull, 1);
  assert.equal(w.hostNeeded, 0);

  // exhausted samples
  w = runWalk(P(0), 0, 16, "exhausted");
  assert.equal(w.hostEdges, 0);
  assert.equal(w.hostNeeded, 1);
  assert.equal(w.resolvedPlayer >>> 0, P(0));

  // truncated chain (cap 2; P2 field_2c 1 would continue)
  writePlayer(P(0), { f2c: 1, m3bc: P(1), f28: 0 });
  writePlayer(P(1), { f2c: 1, m3bc: P(2), f28: 1 });
  writePlayer(P(2), { f2c: 1, m3bc: 0, f28: 1 });
  w = runWalk(P(0), 0, 2, "cap2");
  assert.equal(w.resolvedPlayer >>> 0, P(2));
  assert.equal(w.iterations, 2);
  assert.equal(w.truncated, 1);
  w = runWalk(P(0), 0, 0, "cap0");
  assert.equal(w.resolvedPlayer >>> 0, P(1));
  assert.equal(w.iterations, 1);
  assert.equal(w.truncated, 1);
});

test("v23 0x007cb6e0 walk/RNG/twin mutation round-trips (write -> fail -> restore)", () => {
  const original = readFileSync(source, "utf8");
  const crlfFile = original.includes("\r\n");
  const base = original.replace(/\r\n/g, "\n");
  const toFile = (s) => (crlfFile ? s.replace(/\n/g, "\r\n") : s);
  const withMutant = (label, mutate, check) => {
    const bad = mutate(base);
    assert.notEqual(bad, base, `${label}: mutant did not apply`);
    writeSourceRetry( toFile(bad), "utf8");
    let threw = false;
    try { check(); } catch { threw = true; }
    writeSourceRetry( original, "utf8");
    assert.ok(threw, `${label}: mutant survived every assertion`);
  };
  const planOut = 0x5f3000;
  try {
    /* Each mutant check loads a FRESH wasm instance (zeroed memory), so
       any memory-image the check needs must be written into THAT
       instance's own memory (v22 lesson). */

    withMutant("walk_active byte-fold",
      (s) => s.replace(
        "return player_field_2c == 1u ? 1 : 0;",
        "return ((player_field_2c & 0xffu) == 1u) ? 1 : 0;"),
      () => {
        const e = loadExports();
        assert.equal(e.cntWalkActive(0x101), 0,
          "PE 0x7cb6fb is cmp dword [edi+0x2c],1 — 0x101 must NOT walk");
      });

    withMutant("twin17 receiver offset",
      (s) => s.replace(
        "*out_receiver = player_ptr + ISAAC_HUD_COUNT_7CB6E0_TWIN_RECV_OFF;",
        "*out_receiver = player_ptr;"),
      () => {
        const e = loadExports();
        const v = new DataView(e.memory.buffer);
        e.cntTwin17Prep(0x2000, planOut, planOut + 4);
        assert.equal(readU32(v, planOut), 0x3508,
          "0x7cb8ac is lea ecx,[edi+0x1508] — receiver must be player+0x1508");
      });

    withMutant("4b_chain gate polarity",
      (s) => s.replace(
        "if (room_field_5c == 0u || rng_known == 0) {",
        "if (room_field_5c != 0u || rng_known == 0) {"),
      () => {
        const e = loadExports();
        assert.equal(e.cnt4bChain(0, 1, 0xa, 3, 0xb), 0,
          "0x7cb875 test eax,eax ; je 0x7cb8a6 — a closed gate never reaches the RNG");
      });

    withMutant("rng_prep const b",
      (s) => s.replace(
        "out->b = ISAAC_HUD_COUNT_7CB6E0_RNG_CONST_B;",
        "out->b = 0x18u;"),
      () => {
        const e = loadExports();
        const v = new DataView(e.memory.buffer);
        e.cntRngPrep(0x1234, planOut);
        assert.equal(readU32(v, planOut + RNG3.b), 0x19,
          "0x7cb896 stores dword[0xb1f56c] = 0x19");
      });

    withMutant("walk_plan exhausted->stopped_null",
      (s) => s.replace(
        "      if (sample_idx >= samples_count) {\n        out->host_needed = 1;\n        break;\n      }",
        "      if (sample_idx >= samples_count) {\n        out->stopped_null = 1;\n        break;\n      }"),
      () => {
        const e = loadExports();
        const v = new DataView(e.memory.buffer);
        /* image in THIS instance's memory: gate open, m3bc null. */
        writeU32(v, 0x5f0100 + HUD_COUNT_7CB6E0_FIELD_2C_OFF, 1);
        writeU32(v, 0x5f0100 + HUD_COUNT_7CB6E0_FIELD_3BC_OFF, 0);
        e.cntWalkPlan(0x5f0100, 0x5f2000, 0, 16, planOut);
        assert.equal(readI32(v, planOut + WALK3.hostNeeded), 1,
          "a missing GetPlayer sample is a host dependency, not a null result");
        assert.equal(readI32(v, planOut + WALK3.stoppedNull), 0,
          "the 0x7cb724 null check (stopped_null) is a SEPARATE branch");
      });
  } finally {
    writeSourceRetry( original, "utf8");
  }
  assert.equal(readFileSync(source, "utf8"), original, "source restored");
  const exp = loadExports();
  const view = new DataView(exp.memory.buffer);
  assert.equal(exp.abi(), 39);
  assert.equal(exp.cntWalkActive(0x101), 0);
  assert.equal(exp.cnt4bChain(0, 1, 0xa, 3, 0xb), 0);
  exp.cntRngPrep(0x1234, planOut);
  assert.equal(readU32(view, planOut + RNG3.b), 0x19);
  exp.cntTwin17Prep(0x2000, planOut, planOut + 4);
  assert.equal(readU32(view, planOut), 0x3508);
  /* fresh instance: image the player in THIS memory before the walk. */
  writeU32(view, 0x5f0100 + HUD_COUNT_7CB6E0_FIELD_2C_OFF, 1);
  writeU32(view, 0x5f0100 + HUD_COUNT_7CB6E0_FIELD_3BC_OFF, 0);
  exp.cntWalkPlan(0x5f0100, 0x5f2000, 0, 16, planOut);
  assert.equal(readI32(view, planOut + WALK3.hostNeeded), 1);
  assert.equal(readI32(view, planOut + WALK3.stoppedNull), 0);
});

/* ================= ABI v24: 0x007e9020 RNG::RandomInt BODY =================
   Evidence: section-notes/hud-v24-rng/NOTES.md; cpu-dump/007e9020.txt
   (0x7e9020..0x7e9075, ret 4). SEPARATE xorshift32 LCG — NOT the room
   MT19937 (0x006eef60). The count4b receiver (v23 rng_prep) seeds
   {seed, 2, 7, 0x19}; the body law is shared. */
// IsaacHudRng7e9020Draw layout (3 x u32).
const RNG7 = { value: 0, seedAfter: 4, fatal: 8 };

test("header documents v24 0x007e9020 RNG::RandomInt body law", () => {
  assert.equal(HUD_POST_UPDATE_PURE_ABI_VERSION, 39);
  const h = readFileSync(header, "utf8");
  assert.match(h, /ABI v24: RNG::RandomInt BODY/);
  assert.match(h, /ISAAC_HUD_RNG_7E9020_VA = 0x007e9020u/);
  assert.match(h, /ISAAC_HUD_RNG_7E9020_FATAL_LOG_VA = 0x00a112c0u/);
  assert.match(h, /ISAAC_HUD_RNG_7E9020_FATAL_STR_VA = 0x00b6bf54u/);
  assert.match(h, /ISAAC_HUD_RNG_7E9020_FATAL_LEVEL = 0x10/);
  assert.match(h, /ISAAC_HUD_RNG_7E9020_FATAL_INT3_VA = 0x007e9041u/);
  assert.match(h, /ISAAC_HUD_RNG_7E9020_STATE_BYTES = 0x10/);
  assert.match(h, /ISAAC_HUD_RNG_7E9020_COUNT4B_SHIFT3 = 0x19u/);
  assert.match(h, /ISAAC_HUD_RNG_7E9020_COUNT4B_MAX = 0xbdu/);
  assert.match(h, /typedef struct IsaacHudRng7e9020Draw \{/);
  assert.match(h, /isaac_hud_rng_7e9020_random_int\(/);
  const s = readFileSync(source, "utf8");
  assert.match(s, /0x7e9026 mov edx,\[esi\]/);
  assert.match(s, /CRT fatal/);
  assert.match(s, /mov \[esi\],eax — the state store happens BEFORE the max test/);
  assert.match(s, /UNSIGNED 32-bit/);
  // model pins
  assert.equal(HUD_RNG_7E9020_VA, 0x007e9020);
  assert.equal(HUD_RNG_7E9020_RET_VA_MAX0, 0x007e906a);
  assert.equal(HUD_RNG_7E9020_RET_VA_MOD, 0x007e9075);
  assert.equal(HUD_RNG_7E9020_FATAL_LOG_VA, 0x00a112c0);
  assert.equal(HUD_RNG_7E9020_FATAL_STR_VA, 0x00b6bf54);
  assert.equal(HUD_RNG_7E9020_FATAL_LEVEL, 0x10);
  assert.equal(HUD_RNG_7E9020_FATAL_INT3_VA, 0x007e9041);
  assert.equal(HUD_RNG_7E9020_STATE_BYTES, 0x10);
  assert.equal(HUD_RNG_7E9020_SEED_OFF, 0x0);
  assert.equal(HUD_RNG_7E9020_SHIFT1_OFF, 0x4);
  assert.equal(HUD_RNG_7E9020_SHIFT2_OFF, 0x8);
  assert.equal(HUD_RNG_7E9020_SHIFT3_OFF, 0xc);
  assert.equal(HUD_RNG_7E9020_COUNT4B_SHIFT1, 0x2);
  assert.equal(HUD_RNG_7E9020_COUNT4B_SHIFT2, 0x7);
  assert.equal(HUD_RNG_7E9020_COUNT4B_SHIFT3, 0x19);
  assert.equal(HUD_RNG_7E9020_COUNT4B_MAX, 0xbd);
});

test("JS oracle: v24 RNG::RandomInt body (0x7e9020) — xorshift + state + max", () => {
  // seed_zero: FULL-DWORD gate (0x7e9028 test edx,edx) — 0x100 NOT fatal.
  assert.equal(hudRng7e9020SeedZero(0), 1);
  assert.equal(hudRng7e9020SeedZero(1), 0);
  assert.equal(hudRng7e9020SeedZero(0x100), 0);
  assert.equal(hudRng7e9020SeedZero(0xffffffff), 0);

  // xorshift step: shifts are CL-masked (&31), u32 wrap.
  assert.equal(hudRng7e9020Xorshift(1, 2, 7, 0x19), 0x81); // verified PE stream
  assert.equal(hudRng7e9020Xorshift(0x12345678, 2, 7, 0x19), 0x4a18b0c3);
  assert.equal(hudRng7e9020Xorshift(0xffffffff, 2, 7, 0x19), 0xc0000060);
  // wide shift: 0x21 masks to 1 (cl & 31).
  assert.equal(hudRng7e9020Xorshift(0x80000000, 0x21, 0x27, 0x39), hudRng7e9020Xorshift(0x80000000, 1, 7, 0x19));

  // full law: fatal on seed 0 (state unchanged, value 0).
  assert.deepEqual(hudRng7e9020RandomInt(0, 2, 7, 0x19, 0xbd), { value: 0, seedAfter: 0, fatal: 1 });
  // normal: value = new_seed % max (UNSIGNED), state advances.
  const d = hudRng7e9020RandomInt(0x12345678, 2, 7, 0x19, 0xbd);
  assert.equal(d.seedAfter, 0x4a18b0c3);
  assert.equal(d.value, 0x4a18b0c3 % 0xbd); // == 97
  assert.equal(d.fatal, 0);
  // max==0 -> value 0 BUT the state still advanced (0x7e9060 store is
  // BEFORE the 0x7e9062 max test).
  const d0 = hudRng7e9020RandomInt(0x12345678, 2, 7, 0x19, 0);
  assert.equal(d0.value, 0);
  assert.equal(d0.seedAfter, 0x4a18b0c3);
  assert.equal(d0.fatal, 0);
  // high-bit seeds: the modulo runs on the XORSHIFTED seed (0x7e906d div
  // uses eax = the new state). next(0xffffffff) = 0xc0000060; unsigned
  // 0xc0000060 % 5 = 3 (signed int32 -2^31+... % 5 would differ).
  const dhi = hudRng7e9020RandomInt(0xffffffff, 2, 7, 0x19, 5);
  assert.equal(dhi.seedAfter, 0xc0000060);
  assert.equal(dhi.value, 0xc0000060 % 5);
  // count4b caller prep (v23 rng_prep) + max 0xbd wired through the law.
  const c = hudRng7e9020RandomInt(0x1f, HUD_RNG_7E9020_COUNT4B_SHIFT1, HUD_RNG_7E9020_COUNT4B_SHIFT2, HUD_RNG_7E9020_COUNT4B_SHIFT3, HUD_RNG_7E9020_COUNT4B_MAX);
  assert.equal(c.seedAfter, hudRng7e9020Xorshift(0x1f, 2, 7, 0x19));
});

test("v24 0x007e9020 RNG::RandomInt native/Wasm differential + mutation pins", () => {
  const exp = loadExports();
  const view = new DataView(exp.memory.buffer);
  assert.equal(exp.abi(), 39);

  // constant accessors
  assert.equal(exp.rngVa() >>> 0, HUD_RNG_7E9020_VA);
  assert.equal(exp.rngRetVaMax0() >>> 0, HUD_RNG_7E9020_RET_VA_MAX0);
  assert.equal(exp.rngRetVaMod() >>> 0, HUD_RNG_7E9020_RET_VA_MOD);
  assert.equal(exp.rngFatalLogVa() >>> 0, HUD_RNG_7E9020_FATAL_LOG_VA);
  assert.equal(exp.rngFatalStrVa() >>> 0, HUD_RNG_7E9020_FATAL_STR_VA);
  assert.equal(exp.rngFatalLevel() >>> 0, HUD_RNG_7E9020_FATAL_LEVEL);
  assert.equal(exp.rngFatalInt3Va() >>> 0, HUD_RNG_7E9020_FATAL_INT3_VA);
  assert.equal(exp.rngStateBytes() >>> 0, HUD_RNG_7E9020_STATE_BYTES);
  assert.equal(exp.rngSeedOff() >>> 0, HUD_RNG_7E9020_SEED_OFF);
  assert.equal(exp.rngShift1Off() >>> 0, HUD_RNG_7E9020_SHIFT1_OFF);
  assert.equal(exp.rngShift2Off() >>> 0, HUD_RNG_7E9020_SHIFT2_OFF);
  assert.equal(exp.rngShift3Off() >>> 0, HUD_RNG_7E9020_SHIFT3_OFF);
  assert.equal(exp.rngCount4bShift1() >>> 0, HUD_RNG_7E9020_COUNT4B_SHIFT1);
  assert.equal(exp.rngCount4bShift2() >>> 0, HUD_RNG_7E9020_COUNT4B_SHIFT2);
  assert.equal(exp.rngCount4bShift3() >>> 0, HUD_RNG_7E9020_COUNT4B_SHIFT3);
  assert.equal(exp.rngCount4bMax() >>> 0, HUD_RNG_7E9020_COUNT4B_MAX);

  // scalar laws (wasm vs JS oracle)
  assert.equal(exp.rngSeedZero(0), 1);
  assert.equal(exp.rngSeedZero(1), 0);
  assert.equal(exp.rngSeedZero(0x100), 0);
  assert.equal(exp.rngXorshift(0x12345678, 2, 7, 0x19) >>> 0, 0x4a18b0c3);
  assert.equal(exp.rngXorshift(0x80000000, 0x21, 0x27, 0x39) >>> 0,
    exp.rngXorshift(0x80000000, 1, 7, 0x19) >>> 0);

  // random_int out-struct differential over a seed/max matrix
  const out = 0x5f4000;
  const cases = [
    { seed: 0x12345678, s1: 2, s2: 7, s3: 0x19, max: 0xbd },
    { seed: 0x12345678, s1: 2, s2: 7, s3: 0x19, max: 0 },
    { seed: 0, s1: 2, s2: 7, s3: 0x19, max: 0xbd },
    { seed: 0xffffffff, s1: 2, s2: 7, s3: 0x19, max: 3 },
    { seed: 0x80000000, s1: 2, s2: 7, s3: 0x19, max: 3 },
    { seed: 0x1f, s1: HUD_RNG_7E9020_COUNT4B_SHIFT1, s2: HUD_RNG_7E9020_COUNT4B_SHIFT2, s3: HUD_RNG_7E9020_COUNT4B_SHIFT3, max: HUD_RNG_7E9020_COUNT4B_MAX },
  ];
  for (const c of cases) {
    exp.rngRandomInt(c.seed >>> 0, c.s1 >>> 0, c.s2 >>> 0, c.s3 >>> 0, c.max >>> 0, out);
    const w = { value: readU32(view, out + RNG7.value), seedAfter: readU32(view, out + RNG7.seedAfter), fatal: readI32(view, out + RNG7.fatal) };
    const o = hudRng7e9020RandomInt(c.seed, c.s1, c.s2, c.s3, c.max);
    for (const k of ["value", "seedAfter", "fatal"]) {
      assert.equal(w[k], o[k], `seed=${c.seed} max=${c.max} ${k}`);
    }
  }
});

test("v24 0x007e9020 RNG::RandomInt mutation round-trips (write -> fail -> restore)", () => {
  const original = readFileSync(source, "utf8");
  const crlfFile = original.includes("\r\n");
  const base = original.replace(/\r\n/g, "\n");
  const toFile = (s) => (crlfFile ? s.replace(/\n/g, "\r\n") : s);
  const withMutant = (label, mutate, check) => {
    const bad = mutate(base);
    assert.notEqual(bad, base, `${label}: mutant did not apply`);
    writeSourceRetry( toFile(bad), "utf8");
    let threw = false;
    try { check(); } catch { threw = true; }
    writeSourceRetry( original, "utf8");
    assert.ok(threw, `${label}: mutant survived every assertion`);
  };
  const out = 0x5f4000;
  try {
    withMutant("M1 seed_zero byte-fold",
      (s) => s.replace(
        "return seed == 0u ? 1 : 0;",
        "return ((seed & 0xffu) == 0u) ? 1 : 0;"),
      () => {
        const e = loadExports();
        assert.equal(e.rngSeedZero(0x100), 0,
          "PE 0x7e9028 is test edx,edx (FULL-DWORD) — 0x100 must NOT be a seed fatal");
      });

    withMutant("M2 xorshift shift mask width (31 -> 15)",
      (s) => s.replace(
        "uint32_t eax = (seed >> (shift1 & 31u)) ^ seed;",
        "uint32_t eax = (seed >> (shift1 & 15u)) ^ seed;"),
      () => {
        const e = loadExports();
        assert.equal(e.rngXorshift(0x80000000, 0x10, 7, 0x19) >>> 0, 0x80408040,
          "0x7e9047 shr eax,cl — the shift count is CL-masked to 5 bits (shift 0x10 -> 16, not 0)");
      });

    withMutant("M3 max==0 stops the advance",
      (s) => s.replace(
        "  out->seed_after = next;\n  out->fatal = 0;\n  if (max == 0u) {",
        "  if (max == 0u) {\n    out->seed_after = 0u;\n    out->fatal = 0;"),
      () => {
        const e = loadExports();
        const v = new DataView(e.memory.buffer);
        e.rngRandomInt(0x12345678, 2, 7, 0x19, 0, out);
        assert.equal(readU32(v, out + RNG7.seedAfter), 0x4a18b0c3,
          "0x7e9060 mov [esi],eax happens BEFORE 0x7e9062 test ecx,ecx — max==0 still advances");
      });

    withMutant("M4 modulo signedness",
      (s) => s.replace(
        "  out->value = next % max;",
        "  out->value = (uint32_t)((int32_t)next % (int32_t)max);"),
      () => {
        const e = loadExports();
        const v = new DataView(e.memory.buffer);
        /* next(0xffffffff) = 0xc0000060: unsigned % 5 = 3, signed int32
           % 5 = -3 (would read as 0xfffffffd). */
        e.rngRandomInt(0xffffffff, 2, 7, 0x19, 5, out);
        assert.equal(readU32(v, out + RNG7.value), 3,
          "0x7e906d xor edx,edx ; div ecx — the remainder is UNSIGNED (signed % gives -3)");
      });

    withMutant("M5 xorshift step order (s2 before s1)",
      (s) => s.replace(
        "  uint32_t eax = (seed >> (shift1 & 31u)) ^ seed;\n  const uint32_t edx = (eax << (shift2 & 31u)) ^ eax;\n  eax = (edx >> (shift3 & 31u)) ^ edx;",
        "  uint32_t eax = (seed << (shift1 & 31u)) ^ seed;\n  const uint32_t edx = (eax >> (shift2 & 31u)) ^ eax;\n  eax = (edx << (shift3 & 31u)) ^ edx;"),
      () => {
        const e = loadExports();
        assert.equal(e.rngXorshift(0x12345678, 2, 7, 0x19) >>> 0, 0x4a18b0c3,
          "PE order is shr s1, shl s2, shr s3 (0x7e9047/0x7e9050/0x7e9059) — a different order changes the stream");
      });
  } finally {
    writeSourceRetry( original, "utf8");
  }
  assert.equal(readFileSync(source, "utf8"), original, "source restored");
  const exp = loadExports();
  const view = new DataView(exp.memory.buffer);
  assert.equal(exp.abi(), 39);
  assert.equal(exp.rngSeedZero(0x100), 0);
  assert.equal(exp.rngXorshift(0x12345678, 2, 7, 0x19) >>> 0, 0x4a18b0c3);
  exp.rngRandomInt(0x12345678, 2, 7, 0x19, 0, out);
  assert.equal(readU32(view, out + RNG7.seedAfter), 0x4a18b0c3);
  exp.rngRandomInt(0xffffffff, 2, 7, 0x19, 5, out);
  assert.equal(readU32(view, out + RNG7.value), 3);
});

/* ============ ABI v24: HasCollectible 0x007706e0 QUERY accept gate ======
   + composed redirect WALK =================================================
   Evidence: section-notes/hud-v24-has-collectible/NOTES.md;
   cpu-dump/007706e0.txt (0x7706e0..0x770c92). The query is invoked cdecl
   0x1b7 / 0 from the process-input record 0x009be6b0 and its result is
   LOW-BYTE accepted (0x009be719 test bl,bl / 0x009be71f test al,al). */

// IsaacHasCollectibleWalkPlan layout (6 x i32 = 24 bytes).
const WALK4 = {
  status: 0, resolvedPlayer: 4, configPtr: 8, iterations: 12,
  hostEdges: 16, hostNeeded: 20, size: 24,
};

function readWalkPlan4(view, base) {
  return {
    status: readI32(view, base + WALK4.status),
    resolvedPlayer: readU32(view, base + WALK4.resolvedPlayer),
    configPtr: readU32(view, base + WALK4.configPtr),
    iterations: readI32(view, base + WALK4.iterations),
    hostEdges: readI32(view, base + WALK4.hostEdges),
    hostNeeded: readI32(view, base + WALK4.hostNeeded),
  };
}

function writeHcSample(view, base, idx, ck, cr, gk, gr) {
  const b = base + idx * HAS_COLLECTIBLE_WALK_SAMPLE_STRIDE;
  writeU32(view, b + 0, ck >>> 0);
  writeU32(view, b + 4, cr >>> 0);
  writeU32(view, b + 8, gk >>> 0);
  writeU32(view, b + 12, gr >>> 0);
}

test("header documents v24 0x007706e0 query accept gate + redirect walk", () => {
  assert.equal(HUD_POST_UPDATE_PURE_ABI_VERSION, 39);
  const h = readFileSync(header, "utf8");
  assert.match(h, /Helpers ABI v24 \(0x007706e0\): the HasCollectible QUERY accept gate/);
  assert.match(h, /ISAAC_HAS_COLLECTIBLE_QUERY_ARG_ID = 0x1b7/);
  assert.match(h, /ISAAC_HAS_COLLECTIBLE_ACCEPT_VA_BL = 0x009be719u/);
  assert.match(h, /ISAAC_HAS_COLLECTIBLE_ACCEPT_VA_AL = 0x009be71fu/);
  assert.match(h, /ISAAC_HAS_COLLECTIBLE_WALK_VA_F2C_GATE = 0x00770716u/);
  assert.match(h, /ISAAC_HAS_COLLECTIBLE_WALK_VA_GETPLAYER = 0x0077072cu/);
  assert.match(h, /ISAAC_HAS_COLLECTIBLE_WALK_VA_CONFIG_LOOP = 0x00770756u/);
  assert.equal(HAS_COLLECTIBLE_WALK_ITER_CAP, 16);
  assert.equal(HAS_COLLECTIBLE_WALK_SAMPLE_STRIDE, 16);
  assert.equal(HAS_COLLECTIBLE_WALK_STATUS_CONFIG_NULL, 1);
  assert.equal(HAS_COLLECTIBLE_WALK_STATUS_GETPLAYER_NULL, 2);
  assert.equal(HAS_COLLECTIBLE_WALK_STATUS_TRUNCATED, 4);
});

test("JS oracle: v24 accept gate + walk plan (0x77070d..0x770758)", () => {
  assert.equal(HAS_COLLECTIBLE_QUERY_ARG_ID, 0x1b7);
  assert.equal(HAS_COLLECTIBLE_QUERY_ARG_IGNORE, 0);
  assert.equal(HAS_COLLECTIBLE_ACCEPT_VA_BL, 0x009be719);
  assert.equal(HAS_COLLECTIBLE_ACCEPT_VA_AL, 0x009be71f);

  // accept gate: both tests are LOW BYTE (0x9be719 test bl,bl / 0x9be71f
  // test al,al) — 0x100 on either side is a miss.
  assert.equal(hasCollectibleQueryHit(0), 0);
  assert.equal(hasCollectibleQueryHit(1), 1);
  assert.equal(hasCollectibleQueryHit(0x100), 0, "test al,al — 0x100 is a miss");
  assert.equal(hasCollectibleQueryHit(0xffffffff), 1);
  assert.equal(hasCollectibleAcceptGate(0, 1), 0);
  assert.equal(hasCollectibleAcceptGate(1, 1), 1);
  assert.equal(hasCollectibleAcceptGate(1, 0x100), 0);
  assert.equal(hasCollectibleAcceptGate(0x100, 1), 0, "test bl,bl — bl 0x100 has low byte 0");
  assert.equal(hasCollectibleAcceptGate(0x100, 0x100), 0);

  // walk plan trace over a small image.
  const view = new DataView(new ArrayBuffer(0x4000));
  const P0 = 0x1000, P1 = 0x2000, S = 0x3000;
  const put = (addr, off, v) => writeU32(view, addr + off, v >>> 0);
  const w = (count, cap) =>
    hasCollectibleWalkPlan(view, P0, S, count, cap);

  // (a) entry config null -> FALSE (0x770712 je 0x77075a).
  writeHcSample(view, S, 0, 1, 0, 1, 0x100);
  assert.deepEqual(w(2, 16), {
    status: HAS_COLLECTIBLE_WALK_STATUS_CONFIG_NULL, resolvedPlayer: P0,
    configPtr: 0, iterations: 0, hostEdges: 1, hostNeeded: 0,
  });

  // (b) no redirect (field_2c != 1) -> interior with the known config.
  put(P0, HAS_COLLECTIBLE_PLAYER_FIELD_2C_OFF, 2);
  writeHcSample(view, S, 0, 1, 0xbeef, 1, 0x100);
  assert.deepEqual(w(2, 16), {
    status: HAS_COLLECTIBLE_WALK_STATUS_INTERIOR, resolvedPlayer: P0,
    configPtr: 0xbeef, iterations: 0, hostEdges: 1, hostNeeded: 0,
  });

  // (c) parent qualifies (P0.m3bc=P1, P1.f28=1, P1.f2c=0) -> adopt P1,
  //     refetch config known -> interior at P1.
  put(P0, HAS_COLLECTIBLE_PLAYER_FIELD_2C_OFF, 1);
  put(P0, HAS_COLLECTIBLE_PARENT_PTR_OFF, P1);
  put(P1, HAS_COLLECTIBLE_PARENT_FLAG_OFF, 1);
  put(P1, HAS_COLLECTIBLE_PLAYER_FIELD_2C_OFF, 0);
  writeHcSample(view, S, 0, 1, 0xaaa, 1, 0x100); // entry config
  writeHcSample(view, S, 1, 1, 0xbeef, 0, 0);    // refetch config (gp unused)
  assert.deepEqual(w(2, 16), {
    status: HAS_COLLECTIBLE_WALK_STATUS_INTERIOR, resolvedPlayer: P1,
    configPtr: 0xbeef, iterations: 1, hostEdges: 2, hostNeeded: 0,
  });

  // (d) parent NULL, GetPlayer null -> interior, edi UNCHANGED (0x770739
  //     je 0x77076f).
  put(P0, HAS_COLLECTIBLE_PARENT_PTR_OFF, 0);
  writeHcSample(view, S, 0, 1, 0xaaa, 1, 0);
  assert.deepEqual(w(1, 16), {
    status: HAS_COLLECTIBLE_WALK_STATUS_GETPLAYER_NULL, resolvedPlayer: P0,
    configPtr: 0xaaa, iterations: 0, hostEdges: 2, hostNeeded: 0,
  });

  // (e) gp sample unknown -> host needed (never a null result).
  put(P0, HAS_COLLECTIBLE_PLAYER_FIELD_2C_OFF, 1);
  writeHcSample(view, S, 0, 1, 0xaaa, 0, 0);
  assert.deepEqual(w(1, 16), {
    status: HAS_COLLECTIBLE_WALK_STATUS_HOST_NEEDED, resolvedPlayer: P0,
    configPtr: 0, iterations: 0, hostEdges: 2, hostNeeded: 1,
  });

  // (f) zero samples -> host needed at the entry edge.
  assert.deepEqual(w(0, 16), {
    status: HAS_COLLECTIBLE_WALK_STATUS_HOST_NEEDED, resolvedPlayer: P0,
    configPtr: 0, iterations: 0, hostEdges: 0, hostNeeded: 1,
  });

  // (g) refetch config sample exhausted (count 1) after an adoption ->
  //     host needed, resolved is the ADOPTED player.
  writeHcSample(view, S, 0, 1, 0xaaa, 1, 0x5000);
  assert.deepEqual(w(1, 16), {
    status: HAS_COLLECTIBLE_WALK_STATUS_HOST_NEEDED, resolvedPlayer: 0x5000,
    configPtr: 0, iterations: 1, hostEdges: 2, hostNeeded: 1,
  });

  // (h) iter cap: truncate after the FIRST adoption.
  put(P0, HAS_COLLECTIBLE_PARENT_PTR_OFF, P1);
  put(P1, HAS_COLLECTIBLE_PARENT_FLAG_OFF, 1);
  writeHcSample(view, S, 0, 1, 0xaaa, 0, 0);
  assert.deepEqual(w(1, 0), {
    status: HAS_COLLECTIBLE_WALK_STATUS_TRUNCATED, resolvedPlayer: P1,
    configPtr: 0, iterations: 1, hostEdges: 1, hostNeeded: 1,
  });

  // (i) entry config sample unknown -> host needed.
  writeHcSample(view, S, 0, 0, 0, 0, 0);
  assert.deepEqual(w(1, 16), {
    status: HAS_COLLECTIBLE_WALK_STATUS_HOST_NEEDED, resolvedPlayer: P0,
    configPtr: 0, iterations: 0, hostEdges: 1, hostNeeded: 1,
  });
});

test("v24 0x007706e0 accept/walk native/Wasm differential + pins", () => {
  const exp = loadExports();
  const view = new DataView(exp.memory.buffer);
  assert.equal(exp.abi(), 39);

  // constants / call-site accessors
  assert.equal(exp.hcQueryArgId(), HAS_COLLECTIBLE_QUERY_ARG_ID);
  assert.equal(exp.hcQueryArgIgnore(), HAS_COLLECTIBLE_QUERY_ARG_IGNORE);
  assert.equal(exp.hcWalkIterCap(), HAS_COLLECTIBLE_WALK_ITER_CAP);
  assert.equal(exp.hcWalkSampleStride(), HAS_COLLECTIBLE_WALK_SAMPLE_STRIDE);
  assert.equal(exp.hcAcceptVaBl(), HAS_COLLECTIBLE_ACCEPT_VA_BL);
  assert.equal(exp.hcAcceptVaAl(), HAS_COLLECTIBLE_ACCEPT_VA_AL);
  assert.equal(exp.hcWalkVaConfigTest(), HAS_COLLECTIBLE_WALK_VA_CONFIG_TEST);
  assert.equal(exp.hcWalkVaF2cGate(), HAS_COLLECTIBLE_WALK_VA_F2C_GATE);
  assert.equal(exp.hcWalkVaParentProbe(), HAS_COLLECTIBLE_WALK_VA_PARENT_PROBE);
  assert.equal(exp.hcWalkVaParentTest(), HAS_COLLECTIBLE_WALK_VA_PARENT_TEST);
  assert.equal(exp.hcWalkVaGetplayer(), HAS_COLLECTIBLE_WALK_VA_GETPLAYER);
  assert.equal(exp.hcWalkVaGetplayerTest(), HAS_COLLECTIBLE_WALK_VA_GETPLAYER_TEST);
  assert.equal(exp.hcWalkVaAdopt(), HAS_COLLECTIBLE_WALK_VA_ADOPT);
  assert.equal(exp.hcWalkVaConfigRefetch(), HAS_COLLECTIBLE_WALK_VA_CONFIG_REFETCH);
  assert.equal(exp.hcWalkVaConfigLoop(), HAS_COLLECTIBLE_WALK_VA_CONFIG_LOOP);
  assert.equal(exp.hcWalkVaFalse(), HAS_COLLECTIBLE_WALK_VA_FALSE);
  assert.equal(exp.hcWalkVaInterior(), HAS_COLLECTIBLE_WALK_VA_INTERIOR);
  assert.equal(exp.hcWalkStatusInterior(), HAS_COLLECTIBLE_WALK_STATUS_INTERIOR);
  assert.equal(exp.hcWalkStatusConfigNull(), HAS_COLLECTIBLE_WALK_STATUS_CONFIG_NULL);
  assert.equal(exp.hcWalkStatusGetplayerNull(), HAS_COLLECTIBLE_WALK_STATUS_GETPLAYER_NULL);
  assert.equal(exp.hcWalkStatusHostNeeded(), HAS_COLLECTIBLE_WALK_STATUS_HOST_NEEDED);
  assert.equal(exp.hcWalkStatusTruncated(), HAS_COLLECTIBLE_WALK_STATUS_TRUNCATED);

  // scalar accept pins (WIDE-driven)
  assert.equal(exp.hcQueryHit(0), 0);
  assert.equal(exp.hcQueryHit(1), 1);
  assert.equal(exp.hcQueryHit(0x100), 0, "0x9be71f test al,al");
  assert.equal(exp.hcQueryHit(0x1ff), 1);
  assert.equal(exp.hcQueryHit(0xffffffff), 1);
  assert.equal(exp.hcAcceptGate(0, 1), 0);
  assert.equal(exp.hcAcceptGate(1, 1), 1);
  assert.equal(exp.hcAcceptGate(1, 0x100), 0);
  assert.equal(exp.hcAcceptGate(0x100, 1), 0, "0x9be719 test bl,bl");
  assert.equal(exp.hcAcceptGate(0x101, 1), 1);

  // walk differential (wasm vs JS trace) over an image matrix
  const P0 = 0x5f0100, P1 = 0x5f0200, P2 = 0x5f0300, S = 0x5f2000;
  const planOut = 0x5f3000;
  const writePlayer = (addr, { f2c, m3bc, f28 }) => {
    writeU32(view, addr + HAS_COLLECTIBLE_PLAYER_FIELD_2C_OFF, f2c >>> 0);
    writeU32(view, addr + HAS_COLLECTIBLE_PARENT_PTR_OFF, m3bc >>> 0);
    writeU32(view, addr + HAS_COLLECTIBLE_PARENT_FLAG_OFF, f28 >>> 0);
  };
  const runWalk = (playerPtr, samplesCount, iterCap, label) => {
    exp.hcWalkPlan(playerPtr >>> 0, S >>> 0, samplesCount >>> 0, iterCap >>> 0, planOut);
    const w = readWalkPlan4(view, planOut);
    const o = hasCollectibleWalkPlan(view, playerPtr >>> 0, S >>> 0, samplesCount >>> 0, iterCap >>> 0);
    for (const k of Object.keys(w)) {
      assert.equal(w[k], o[k], `${label} ${k}`);
    }
    return w;
  };

  // 1. entry config null -> config_null (FALSE).
  writeHcSample(view, S, 0, 1, 0, 1, 0x100);
  writePlayer(P0, { f2c: 1, m3bc: P1, f28: 1 });
  let w = runWalk(P0, 2, 16, "entry-config-null");
  assert.equal(w.status, HAS_COLLECTIBLE_WALK_STATUS_CONFIG_NULL);
  assert.equal(w.resolvedPlayer, P0);
  assert.equal(w.configPtr, 0);
  assert.equal(w.hostEdges, 1);

  // 2. field_2c != 1 -> interior with known config (WIDE f2c 0x101).
  writeHcSample(view, S, 0, 1, 0xbeef, 1, 0x100);
  writePlayer(P0, { f2c: 0x101, m3bc: P1, f28: 1 });
  w = runWalk(P0, 2, 16, "no-redirect");
  assert.equal(w.status, HAS_COLLECTIBLE_WALK_STATUS_INTERIOR);
  assert.equal(w.resolvedPlayer, P0);
  assert.equal(w.configPtr, 0xbeef);

  // 3. parent chain P0->P1 (parent qualify), P1 not redirecting.
  writeHcSample(view, S, 0, 1, 0xaaa, 1, 0x100);
  writeHcSample(view, S, 1, 1, 0xbeef, 0, 0);
  writePlayer(P0, { f2c: 1, m3bc: P1, f28: 1 });
  writePlayer(P1, { f2c: 0, m3bc: 0, f28: 1 });
  w = runWalk(P0, 2, 16, "parent-chain");
  assert.equal(w.status, HAS_COLLECTIBLE_WALK_STATUS_INTERIOR);
  assert.equal(w.resolvedPlayer, P1);
  assert.equal(w.configPtr, 0xbeef);
  assert.equal(w.iterations, 1);
  assert.equal(w.hostEdges, 2);

  // 4. GetPlayer null -> interior, edi UNCHANGED.
  writeHcSample(view, S, 0, 1, 0xaaa, 1, 0);
  writePlayer(P0, { f2c: 1, m3bc: 0, f28: 0 });
  w = runWalk(P0, 1, 16, "gp-null");
  assert.equal(w.status, HAS_COLLECTIBLE_WALK_STATUS_GETPLAYER_NULL);
  assert.equal(w.resolvedPlayer, P0);
  assert.equal(w.configPtr, 0xaaa);
  assert.equal(w.hostEdges, 2);

  // 5. unknown gp sample -> host needed.
  writeHcSample(view, S, 0, 1, 0xaaa, 0, 0);
  writePlayer(P0, { f2c: 1, m3bc: 0, f28: 0 });
  w = runWalk(P0, 1, 16, "gp-unknown");
  assert.equal(w.status, HAS_COLLECTIBLE_WALK_STATUS_HOST_NEEDED);
  assert.equal(w.hostNeeded, 1);
  assert.equal(w.resolvedPlayer, P0);

  // 6. double adoption via parent chain to a NULL refetch -> config_null.
  writeHcSample(view, S, 0, 1, 0xaaa, 0, 0);
  writeHcSample(view, S, 1, 1, 0xbbb, 0, 0);
  writeHcSample(view, S, 2, 1, 0, 0, 0);
  writePlayer(P0, { f2c: 1, m3bc: P1, f28: 1 });
  writePlayer(P1, { f2c: 1, m3bc: P2, f28: 1 });
  writePlayer(P2, { f2c: 1, m3bc: 0, f28: 1 });
  w = runWalk(P0, 3, 16, "chain-null");
  assert.equal(w.status, HAS_COLLECTIBLE_WALK_STATUS_CONFIG_NULL);
  assert.equal(w.resolvedPlayer, P2);
  assert.equal(w.iterations, 2);
  assert.equal(w.hostEdges, 3);

  // 7. truncation at iter_cap == 1 (after the first adoption).
  writeHcSample(view, S, 0, 1, 0xaaa, 0, 0);
  writePlayer(P0, { f2c: 1, m3bc: P1, f28: 1 });
  writePlayer(P1, { f2c: 1, m3bc: 0, f28: 1 });
  w = runWalk(P0, 1, 0, "cap0");
  assert.equal(w.status, HAS_COLLECTIBLE_WALK_STATUS_TRUNCATED);
  assert.equal(w.hostNeeded, 1);
  assert.equal(w.resolvedPlayer, P1);
  assert.equal(w.configPtr, 0);

  // 8. no samples at all -> host needed at the entry edge.
  w = runWalk(P0, 0, 16, "no-samples");
  assert.equal(w.status, HAS_COLLECTIBLE_WALK_STATUS_HOST_NEEDED);
  assert.equal(w.hostEdges, 0);
  assert.equal(w.hostNeeded, 1);
});

test("v24 0x007706e0 accept/walk mutation round-trips (write -> fail -> restore)", () => {
  const original = readFileSync(source, "utf8");
  const crlfFile = original.includes("\r\n");
  const base = original.replace(/\r\n/g, "\n");
  const toFile = (s) => (crlfFile ? s.replace(/\n/g, "\r\n") : s);
  const planOut = 0x104000;
  const withMutant = (label, mutate, check) => {
    const bad = mutate(base);
    assert.notEqual(bad, base, `${label}: mutant did not apply`);
    writeSourceRetry( toFile(bad), "utf8");
    let threw = false;
    try { check(); } catch { threw = true; }
    writeSourceRetry( original, "utf8");
    assert.ok(threw, `${label}: mutant survived every assertion`);
  };
  try {
    withMutant("M1 query_hit full-word test",
      (s) => s.replace(
        "  /* 0x009be71f test al,al ; jne epilogue-B — the 0x7706e0 result is\n     accepted as a LOW BYTE. RAW uint32: 0x100 is a miss. */\n  return (query_result & 0xffu) != 0u ? 1 : 0;",
        "  /* 0x009be71f test al,al ; jne epilogue-B — the 0x7706e0 result is\n     accepted as a LOW BYTE. RAW uint32: 0x100 is a miss. */\n  return query_result != 0u ? 1 : 0;"),
      () => {
        const e = loadExports();
        assert.equal(e.hcQueryHit(0x100), 0,
          "0x9be71f is test al,al — a full-word test would accept 0x100");
      });

    withMutant("M2 accept_gate bl low-byte dropped",
      (s) => s.replace(
        "  if ((bl & 0xffu) == 0u) {",
        "  if (bl == 0u) {"),
      () => {
        const e = loadExports();
        assert.equal(e.hcAcceptGate(0x100, 1), 0,
          "0x9be719 is test bl,bl — bl 0x100 has low byte 0 and must be skipped");
      });

    withMutant("M3 walk gp-null adopted instead of keep-current",
      (s) => s.replace(
        "      if (gp_result == 0u) {\n        out->status = ISAAC_HAS_COLLECTIBLE_WALK_STATUS_GETPLAYER_NULL;\n        out->resolved_player = edi;\n        out->config_ptr = config;\n        return;\n      }",
        "      if (gp_result == 0u) {\n        out->status = ISAAC_HAS_COLLECTIBLE_WALK_STATUS_GETPLAYER_NULL;\n      }"),
      () => {
        const e = loadExports();
        const v = new DataView(e.memory.buffer);
        const P0 = 0x5f0100, S = 0x5f2000;
        /* image in THIS instance's memory (fresh instance = fresh image). */
        writeU32(v, P0 + HAS_COLLECTIBLE_PLAYER_FIELD_2C_OFF, 1);
        writeU32(v, P0 + HAS_COLLECTIBLE_PARENT_PTR_OFF, 0);
        writeHcSample(v, S, 0, 1, 0xbeef, 1, 0);
        e.hcWalkPlan(P0, S, 1, 16, planOut);
        assert.equal(readI32(v, planOut + WALK4.status),
          HAS_COLLECTIBLE_WALK_STATUS_GETPLAYER_NULL,
          "0x770739 test eax,eax ; je 0x77076f");
        assert.equal(readU32(v, planOut + WALK4.resolvedPlayer), P0,
          "a null GetPlayer keeps the CURRENT player — edi unchanged");
      });

    withMutant("M4 walk post-adoption config-null folded to interior",
      (s) => s.replace(
        "    /* 0x770712: test esi,esi ; je 0x77075a — config NULL -> FALSE. */\n    if (config == 0u) {\n      out->status = ISAAC_HAS_COLLECTIBLE_WALK_STATUS_CONFIG_NULL;",
        "    /* 0x770712: test esi,esi ; je 0x77075a — config NULL -> FALSE. */\n    if (config == 0u) {\n      out->status = ISAAC_HAS_COLLECTIBLE_WALK_STATUS_INTERIOR;"),
      () => {
        const e = loadExports();
        const v = new DataView(e.memory.buffer);
        const P0 = 0x5f0100, P1 = 0x5f0200, S = 0x5f2000;
        writeU32(v, P0 + HAS_COLLECTIBLE_PLAYER_FIELD_2C_OFF, 1);
        writeU32(v, P0 + HAS_COLLECTIBLE_PARENT_PTR_OFF, P1);
        writeU32(v, P1 + HAS_COLLECTIBLE_PARENT_FLAG_OFF, 1);
        writeHcSample(v, S, 0, 1, 0xbeef, 0, 0); // entry config known
        writeHcSample(v, S, 1, 1, 0, 0, 0);      // refetch config NULL
        e.hcWalkPlan(P0, S, 2, 16, planOut);
        assert.equal(readI32(v, planOut + WALK4.status),
          HAS_COLLECTIBLE_WALK_STATUS_CONFIG_NULL,
          "0x770756 test esi,esi ; je 0x77075a — a null refetched config returns FALSE, never interior");
      });
  } finally {
    writeSourceRetry( original, "utf8");
  }
  assert.equal(readFileSync(source, "utf8"), original, "source restored");
  const exp = loadExports();
  const view = new DataView(exp.memory.buffer);
  assert.equal(exp.abi(), 39);
  assert.equal(exp.hcQueryHit(0x100), 0);
  assert.equal(exp.hcAcceptGate(0x100, 1), 0);
});

/* ============ ABI v25: HasCollectible 0x007706e0 RNG-path PREPs ==========
   (0x770a7e..0x770ad9 ladder RNG path + embedded table 0xb6bcd0;
   0x770942..0x77095f id==9 arm prep + 0x21/0x26614 gates).
   Evidence: section-notes/hud-v25-rng-preps/NOTES.md;
   cpu-dump/007706e0.txt. Host leaves stay samples (0x7db860 x2,
   0x436140, 0x771550, the g_game->[0x18300]->[4]->[0x58] walk,
   Game+0x26614); the RNG draws compose the v24 0x7e9020 law. */

// IsaacHud770a7eDraw / IsaacHud770a7ePlan layout.
const A7E_DRAW = { seed: 0, draw: 4 };
const A7E_PLAN = { status: 0, seed: 4, draw: 8, hostEdges: 12 };
// IsaacHud770915Draw / IsaacHud770915Plan layout.
const A915_DRAW = { draw: 0, fatal: 4 };
const A915_PLAN = { status: 0, seed: 4, draw: 8, hitDraw: 12, tailTrue: 16, result: 20 };

function readA7eDraw(view, base) {
  return { seed: readU32(view, base + A7E_DRAW.seed), draw: readU32(view, base + A7E_DRAW.draw) };
}
function readA7ePlan(view, base) {
  return {
    status: readI32(view, base + A7E_PLAN.status),
    seed: readU32(view, base + A7E_PLAN.seed),
    draw: readU32(view, base + A7E_PLAN.draw),
    hostEdges: readI32(view, base + A7E_PLAN.hostEdges),
  };
}
function readA915Draw(view, base) {
  return { draw: readU32(view, base + A915_DRAW.draw), fatal: readI32(view, base + A915_DRAW.fatal) };
}
function readA915Plan(view, base) {
  return {
    status: readI32(view, base + A915_PLAN.status),
    seed: readU32(view, base + A915_PLAN.seed),
    draw: readU32(view, base + A915_PLAN.draw),
    hitDraw: readI32(view, base + A915_PLAN.hitDraw),
    tailTrue: readI32(view, base + A915_PLAN.tailTrue),
    result: readI32(view, base + A915_PLAN.result),
  };
}

test("header documents v25 0x007706e0 RNG-path preps (0x770a7e + 0x770942)", () => {
  assert.equal(HUD_POST_UPDATE_PURE_ABI_VERSION, 39);
  const h = readFileSync(header, "utf8");
  assert.match(h, /Helpers ABI v25 \(0x007706e0\): the two RNG-path PREPs/);
  assert.match(h, /ISAAC_HUD_770A7E_VA = 0x00770a7eu/);
  assert.match(h, /ISAAC_HUD_770A7E_VA_CMOVA = 0x00770abcu/);
  assert.match(h, /ISAAC_HUD_770A7E_TABLE_VA = 0x00b6bcd0u/);
  assert.match(h, /ISAAC_HUD_770A7E_TABLE_3 = 0x101/);
  assert.match(h, /ISAAC_HUD_770915_VA_HIT_JB = 0x00770967u/);
  assert.match(h, /ISAAC_HUD_770915_GATE2_JL = 0x00770979u/);
  assert.match(h, /typedef struct IsaacHud770a7ePlan \{/);
  assert.match(h, /typedef struct IsaacHud770915Plan \{/);
  assert.equal(HUD_770A7E_TABLE_SIZE, 6);
  assert.equal(HUD_770A7E_TABLE[2], 0x23a);
  assert.equal(HUD_770A7E_TABLE[5], 0xe0);
  assert.equal(HUD_770915_ARM_ID, 9);
  assert.equal(HUD_770915_HIT_THRESHOLD, 0x21);
  assert.equal(HUD_770915_GATE2_THRESHOLD, 2);
});

test("JS oracle: v25 RNG-path preps (0x770a7e ladder + 0x770915 arm-9)", () => {
  // ---- Region A: 0x770a7e..0x770ad9 ----
  // open: SIGNED jle (0x770a88) — full-word -1 CLOSES.
  assert.equal(hud770a7eOpen(9), 1);
  assert.equal(hud770a7eOpen(8), 0);
  assert.equal(hud770a7eOpen(0xffffffff), 0, "(int32)-1 <= 8 -> jle taken");
  assert.equal(hud770a7eOpen(0x10000000), 1);
  // seed: cmova UNSIGNED + 32-bit wrap — 0xffffffff stays.
  assert.equal(hud770a7eSeed(0, 0), 1, "cmova clamp to 1");
  assert.equal(hud770a7eSeed(1, 0), 1);
  assert.equal(hud770a7eSeed(5, 0), 5);
  assert.equal(hud770a7eSeed(0x100, 0), 0x100);
  assert.equal(hud770a7eSeed(0xfffffffe, 1), 0xffffffff,
    "sum wraps and stays above 1u (unsigned cmova)");
  // draw composes the v24 law: xorshift(seed,1,0x1b,0x1b) % 6.
  assert.deepEqual(hud770a7eDraw(0, 0), { seed: 1, draw: 2 });
  assert.deepEqual(hud770a7eDraw(3, 0), { seed: 3, draw: 4 });
  assert.deepEqual(hud770a7eDraw(0xffffffff, 0), { seed: 0xffffffff, draw: 0 });
  // table compare (0x770ad2 cmp ebx,table[eax*4]).
  assert.deepEqual([0, 1, 2, 3, 4, 5].map(hud770a7eTableEntry),
    [0x131, 0x3, 0x23a, 0x101, 0x254, 0xe0]);
  assert.equal(hud770a7eTableEntry(6), 0xffffffff, "oob sentinel");
  assert.equal(hud770a7eTableEntry(0x100), 0xffffffff);
  // plan: closed / hit / miss + host edges.
  assert.deepEqual(hud770a7ePlan(0x131, 0xffffffff, 0, 0),
    { status: HUD_770A7E_STATUS_CLOSED, seed: 0, draw: 0, hostEdges: 1 });
  assert.deepEqual(hud770a7ePlan(0x23a, 9, 0, 0),
    { status: HUD_770A7E_STATUS_HIT, seed: 1, draw: 2, hostEdges: 3 });
  assert.deepEqual(hud770a7ePlan(0x101, 9, 0, 0),
    { status: HUD_770A7E_STATUS_MISS, seed: 1, draw: 2, hostEdges: 3 });
  assert.deepEqual(hud770a7ePlan(0x131, 9, 0xfffffffe, 1),
    { status: HUD_770A7E_STATUS_HIT, seed: 0xffffffff, draw: 0, hostEdges: 3 });
  // countB is a RE-CALL (0x770a9f) — never folded from countA: same id,
  // count_a, only countB differs, must change seed AND draw AND verdict.
  assert.deepEqual(hud770a7ePlan(0x254, 9, 3, 0),
    { status: HUD_770A7E_STATUS_HIT, seed: 3, draw: 4, hostEdges: 3 });
  assert.deepEqual(hud770a7ePlan(0x254, 9, 9, 0),
    { status: HUD_770A7E_STATUS_MISS, seed: 9, draw: 2, hostEdges: 3 });

  // ---- Region B: 0x770915 arm (id==9) ----
  // open: id full-dword + h1550 LOW BYTE (0x770925 test al,al).
  assert.equal(hud770915Open(9, 1), 1);
  assert.equal(hud770915Open(9, 0), 0);
  assert.equal(hud770915Open(9, 0x100), 0, "test al,al — 0x100 is false");
  assert.equal(hud770915Open(9, 0x1ff), 1);
  assert.equal(hud770915Open(8, 1), 0);
  // seed: [+0x58] read only when p18300_4 != 0 (0x77093b..0x77093f).
  assert.equal(hud770915Seed(0, 0x1234), 0, "null p18300_4 -> seed 0 (FATAL)");
  assert.equal(hud770915Seed(6, 6), 6);
  assert.equal(hud770915Seed(0x100, 0x58), 0x58);
  // draw: compose the v24 law with {1,0xb,6}, max 0x64.
  assert.deepEqual(hud770915Draw(0), { draw: 0, fatal: 1 });
  assert.deepEqual(hud770915Draw(6), { draw: 5, fatal: 0 });
  assert.deepEqual(hud770915Draw(5), { draw: 67, fatal: 0 });
  // hit: jb UNSIGNED strict below (0x770967).
  assert.equal(hud770915Hit(0x20), 1);
  assert.equal(hud770915Hit(0x21), 0, "jb is STRICT below — 0x21 is a miss");
  assert.equal(hud770915Hit(67), 0);
  assert.equal(hud770915Hit(0x100), 0);
  assert.equal(hud770915Hit(0xffffffff), 0);
  // tail gate: jl SIGNED (0x770979) — 0xffffffff chains.
  assert.equal(hud770915TailGate(2), 1);
  assert.equal(hud770915TailGate(3), 1);
  assert.equal(hud770915TailGate(1), 0);
  assert.equal(hud770915TailGate(0), 0);
  assert.equal(hud770915TailGate(0xffffffff), 0, "(int32)-1 < 2 -> jl taken");
  // plan statuses.
  assert.deepEqual(hud770915Plan(8, 1, 0, 0, 2),
    { status: HUD_770915_STATUS_CLOSED, seed: 0, draw: 0, hitDraw: 0, tailTrue: 0, result: 0 });
  assert.deepEqual(hud770915Plan(9, 0, 0, 0, 2),
    { status: HUD_770915_STATUS_H1550_FALSE, seed: 0, draw: 0, hitDraw: 0, tailTrue: 0, result: 0 });
  assert.deepEqual(hud770915Plan(9, 1, 0, 0x1234, 2),
    { status: HUD_770915_STATUS_FATAL, seed: 0, draw: 0, hitDraw: 0, tailTrue: 0, result: 0 });
  assert.deepEqual(hud770915Plan(9, 1, 6, 6, 2),
    { status: HUD_770915_STATUS_HIT, seed: 6, draw: 5, hitDraw: 1, tailTrue: 1, result: 1 });
  assert.deepEqual(hud770915Plan(9, 1, 5, 5, 2),
    { status: HUD_770915_STATUS_MISS_TRUE, seed: 5, draw: 67, hitDraw: 0, tailTrue: 1, result: 1 });
  assert.deepEqual(hud770915Plan(9, 1, 5, 5, 1),
    { status: HUD_770915_STATUS_MISS_CHAIN, seed: 5, draw: 67, hitDraw: 0, tailTrue: 0, result: 0 });
  assert.deepEqual(hud770915Plan(9, 1, 5, 5, 0xffffffff),
    { status: HUD_770915_STATUS_MISS_CHAIN, seed: 5, draw: 67, hitDraw: 0, tailTrue: 0, result: 0 });
});

test("v25 0x007706e0 RNG-path preps native/Wasm differential + pins", () => {
  const exp = loadExports();
  const view = new DataView(exp.memory.buffer);
  assert.equal(exp.abi(), 39);

  // constant accessors (Region A)
  assert.equal(exp.a7eVa() >>> 0, HUD_770A7E_VA);
  assert.equal(exp.a7eVaOpenGate() >>> 0, HUD_770A7E_VA_OPEN_CMP);
  assert.equal(exp.a7eVaJle() >>> 0, HUD_770A7E_VA_OPEN_JLE);
  assert.equal(exp.a7eVaCountACall() >>> 0, HUD_770A7E_VA_COUNT_A_CALL);
  assert.equal(exp.a7eVaExtraCall() >>> 0, HUD_770A7E_VA_EXTRA_CALL);
  assert.equal(exp.a7eVaCountBCall() >>> 0, HUD_770A7E_VA_COUNT_B_CALL);
  assert.equal(exp.a7eVaRngCall() >>> 0, HUD_770A7E_VA_RNG_CALL);
  assert.equal(exp.a7eVaTableCmp() >>> 0, HUD_770A7E_VA_TABLE_CMP);
  assert.equal(exp.a7eVaTableJe() >>> 0, HUD_770A7E_VA_TABLE_JE);
  assert.equal(exp.a7eVaMiss() >>> 0, HUD_770A7E_VA_MISS);
  assert.equal(exp.a7eVaTail() >>> 0, HUD_770A7E_VA_TAIL);
  assert.equal(exp.a7eVaTrue() >>> 0, HUD_770A7E_VA_TRUE);
  assert.equal(exp.a7eHostVaCount() >>> 0, HUD_770A7E_HOST_VA_COUNT);
  assert.equal(exp.a7eHostVaExtra() >>> 0, HUD_770A7E_HOST_VA_EXTRA);
  assert.equal(exp.a7eGameGlobal() >>> 0, HUD_770A7E_GAME_GLOBAL);
  assert.equal(exp.a7eGameExtraOff() >>> 0, HUD_770A7E_GAME_EXTRA_OFF);
  assert.equal(exp.a7eShiftsConstVa() >>> 0, HUD_770A7E_SHIFTS_CONST_VA);
  assert.equal(exp.a7eShift3ConstVa() >>> 0, HUD_770A7E_SHIFT3_CONST_VA);
  assert.equal(exp.a7eShift1() >>> 0, HUD_770A7E_SHIFT1);
  assert.equal(exp.a7eShift2() >>> 0, HUD_770A7E_SHIFT2);
  assert.equal(exp.a7eShift3() >>> 0, HUD_770A7E_SHIFT3);
  assert.equal(exp.a7eMax() >>> 0, HUD_770A7E_MAX);
  assert.equal(exp.a7eCmovaMin() >>> 0, HUD_770A7E_CMOVA_MIN);
  assert.equal(exp.a7eOpenGt() >>> 0, HUD_770A7E_OPEN_GT);
  assert.equal(exp.a7eTableVa() >>> 0, HUD_770A7E_TABLE_VA);
  assert.equal(exp.a7eTableSize() >>> 0, HUD_770A7E_TABLE_SIZE);

  // constant accessors (Region B)
  assert.equal(exp.a915Va() >>> 0, HUD_770915_VA_ARM);
  assert.equal(exp.a915VaIdJne() >>> 0, HUD_770915_VA_ID_JNE);
  assert.equal(exp.a915Va1550Call() >>> 0, HUD_770915_VA_1550_CALL);
  assert.equal(exp.a915Va1550Test() >>> 0, HUD_770915_VA_1550_TEST);
  assert.equal(exp.a915VaSeedJe() >>> 0, HUD_770915_VA_SEED_JE);
  assert.equal(exp.a915VaPrep() >>> 0, HUD_770915_VA_PREP);
  assert.equal(exp.a915VaRngCall() >>> 0, HUD_770915_VA_RNG_CALL);
  assert.equal(exp.a915VaHitCmp() >>> 0, HUD_770915_VA_HIT_CMP);
  assert.equal(exp.a915VaHitJb() >>> 0, HUD_770915_VA_HIT_JB);
  assert.equal(exp.a915VaGate2Cmp() >>> 0, HUD_770915_VA_GATE2_CMP);
  assert.equal(exp.a915VaGate2Jl() >>> 0, HUD_770915_VA_GATE2_JL);
  assert.equal(exp.a915VaTrue() >>> 0, HUD_770915_VA_TRUE);
  assert.equal(exp.a915HostVa1550() >>> 0, HUD_770915_HOST_VA_1550);
  assert.equal(exp.a915ArmId() >>> 0, HUD_770915_ARM_ID);
  assert.equal(exp.a915ArgId() >>> 0, HUD_770915_ARG_ID);
  assert.equal(exp.a915ArgFlag() >>> 0, HUD_770915_ARG_FLAG);
  assert.equal(exp.a915GameGlobal() >>> 0, HUD_770915_GAME_GLOBAL);
  assert.equal(exp.a915GameP18300Off() >>> 0, HUD_770915_GAME_P18300_OFF);
  assert.equal(exp.a915GameP18300P4Off() >>> 0, HUD_770915_GAME_P18300_P4_OFF);
  assert.equal(exp.a915GameP18300P458Off() >>> 0, HUD_770915_GAME_P18300_P4_58_OFF);
  assert.equal(exp.a915Game26614Off() >>> 0, HUD_770915_GAME_26614_OFF);
  assert.equal(exp.a915ShiftsConstVa() >>> 0, HUD_770915_SHIFTS_CONST_VA);
  assert.equal(exp.a915Shift3ConstVa() >>> 0, HUD_770915_SHIFT3_CONST_VA);
  assert.equal(exp.a915Shift1() >>> 0, HUD_770915_SHIFT1);
  assert.equal(exp.a915Shift2() >>> 0, HUD_770915_SHIFT2);
  assert.equal(exp.a915Shift3() >>> 0, HUD_770915_SHIFT3);
  assert.equal(exp.a915Max() >>> 0, HUD_770915_MAX);
  assert.equal(exp.a915HitThreshold() >>> 0, HUD_770915_HIT_THRESHOLD);
  assert.equal(exp.a915Gate2Threshold() >>> 0, HUD_770915_GATE2_THRESHOLD);
  assert.equal(exp.a915StatusFatal(), HUD_770915_STATUS_FATAL);
  assert.equal(exp.a915StatusMissChain(), HUD_770915_STATUS_MISS_CHAIN);

  // scalar laws (wasm vs JS)
  assert.equal(exp.a7eOpen(9), 1);
  assert.equal(exp.a7eOpen(8), 0);
  assert.equal(exp.a7eOpen(0xffffffff), 0, "SIGNED jle — -1 closes");
  assert.equal(exp.a7eOpen(0x10000000), 1);
  assert.equal(exp.a7eSeed(0, 0) >>> 0, 1);
  assert.equal(exp.a7eSeed(0xfffffffe, 1) >>> 0, 0xffffffff, "cmova UNSIGNED");
  assert.equal(exp.a7eTableEntry(2) >>> 0, 0x23a);
  assert.equal(exp.a7eTableEntry(6) >>> 0, 0xffffffff);
  assert.equal(exp.a915Open(9, 1), 1);
  assert.equal(exp.a915Open(9, 0x100), 0, "test al,al — 0x100 false");
  assert.equal(exp.a915Open(8, 1), 0);
  assert.equal(exp.a915Seed(0, 0x1234) >>> 0, 0);
  assert.equal(exp.a915Hit(0x20), 1);
  assert.equal(exp.a915Hit(0x21), 0, "jb strict — 0x21 miss");
  assert.equal(exp.a915TailGate(2), 1);
  assert.equal(exp.a915TailGate(0xffffffff), 0, "SIGNED jl — -1 chains");

  // Region A draw/plan out-struct differential over a matrix
  const a7eOut = 0x5f4000, a7ePlanOut = 0x5f4100;
  const a7eCases = [
    { id: 0x131, countA: 9, countB: 0, extra: 0 },
    { id: 0x23a, countA: 9, countB: 0, extra: 0 },
    { id: 0x254, countA: 9, countB: 3, extra: 0 },
    { id: 0x254, countA: 9, countB: 9, extra: 0 },
    { id: 0x101, countA: 8, countB: 5, extra: 0 },
    { id: 0x101, countA: 9, countB: 0xfffffffe, extra: 1 },
    { id: 0x3, countA: 9, countB: 0xfffffffe, extra: 1 },
    { id: 0x131, countA: 9, countB: 0x100, extra: 0 },
    { id: 0x131, countA: 0xffffffff, countB: 5, extra: 0 },
  ];
  for (const c of a7eCases) {
    exp.a7eDraw(c.countB >>> 0, c.extra >>> 0, a7eOut);
    const wd = readA7eDraw(view, a7eOut);
    const od = hud770a7eDraw(c.countB, c.extra);
    assert.equal(wd.seed, od.seed, `draw seed ${JSON.stringify(c)}`);
    assert.equal(wd.draw, od.draw, `draw value ${JSON.stringify(c)}`);
    exp.a7ePlan(c.id >>> 0, c.countA >>> 0, c.countB >>> 0, c.extra >>> 0, a7ePlanOut);
    const wp = readA7ePlan(view, a7ePlanOut);
    const op = hud770a7ePlan(c.id, c.countA, c.countB, c.extra);
    for (const k of Object.keys(op)) {
      assert.equal(wp[k], op[k], `plan ${k} ${JSON.stringify(c)}`);
    }
  }

  // Region B draw/plan out-struct differential over a matrix
  const a915Out = 0x5f4200, a915PlanOut = 0x5f4300;
  const a915Cases = [
    { id: 9, h1550: 1, p4: 6, p458: 6, g: 2 },
    { id: 9, h1550: 1, p4: 0, p458: 0x1234, g: 2 },
    { id: 9, h1550: 1, p4: 5, p458: 5, g: 2 },
    { id: 9, h1550: 1, p4: 5, p458: 5, g: 1 },
    { id: 9, h1550: 1, p4: 5, p458: 5, g: 0xffffffff },
    { id: 9, h1550: 0, p4: 6, p458: 6, g: 2 },
    { id: 8, h1550: 1, p4: 6, p458: 6, g: 2 },
    { id: 9, h1550: 0x100, p4: 6, p458: 6, g: 2 },
    { id: 9, h1550: 1, p4: 0x100, p458: 0x58, g: 3 },
  ];
  for (const c of a915Cases) {
    exp.a915Draw(c.p458 >>> 0, a915Out);
    const wd = readA915Draw(view, a915Out);
    const od = hud770915Draw(c.p458);
    assert.equal(wd.draw, od.draw, `915 draw ${JSON.stringify(c)}`);
    assert.equal(wd.fatal, od.fatal, `915 fatal ${JSON.stringify(c)}`);
    exp.a915Plan(c.id >>> 0, c.h1550 >>> 0, c.p4 >>> 0, c.p458 >>> 0, c.g >>> 0, a915PlanOut);
    const wp = readA915Plan(view, a915PlanOut);
    const op = hud770915Plan(c.id, c.h1550, c.p4, c.p458, c.g);
    for (const k of Object.keys(op)) {
      assert.equal(wp[k], op[k], `915 plan ${k} ${JSON.stringify(c)}`);
    }
  }
  // a fatal draw drives the REGION-B law only via the SEED param
  // (p18300_4 == 0 -> seed 0 -> v24 law fatal); the wasm fill is pinned.
  exp.a915Draw(0, a915Out);
  assert.equal(readU32(view, a915Out + A915_DRAW.draw), 0);
  assert.equal(readI32(view, a915Out + A915_DRAW.fatal), 1);
});

test("v25 0x007706e0 RNG-path preps mutation round-trips (write -> fail -> restore)", () => {
  const original = readFileSync(source, "utf8");
  const crlfFile = original.includes("\r\n");
  const base = original.replace(/\r\n/g, "\n");
  const toFile = (s) => (crlfFile ? s.replace(/\n/g, "\r\n") : s);
  const withMutant = (label, mutate, check) => {
    const bad = mutate(base);
    assert.notEqual(bad, base, `${label}: mutant did not apply`);
    writeSourceRetry( toFile(bad), "utf8");
    let threw = false;
    try { check(); } catch { threw = true; }
    writeSourceRetry( original, "utf8");
    assert.ok(threw, `${label}: mutant survived every assertion`);
  };
  const a7eOut = 0x5f4000, a7ePlanOut = 0x5f4100, a915Out = 0x5f4200, a915PlanOut = 0x5f4300;
  try {
    withMutant("M1 770a7e open unsigned compare",
      (s) => s.replace(
        "  return (int64_t)(int32_t)count_a > (int64_t)ISAAC_HUD_770A7E_OPEN_GT ? 1 : 0;",
        "  return (int64_t)(uint32_t)count_a > (int64_t)ISAAC_HUD_770A7E_OPEN_GT ? 1 : 0;"),
      () => {
        const e = loadExports();
        assert.equal(e.a7eOpen(0xffffffff), 0,
          "0x770a88 jle is SIGNED — (int32)-1 must CLOSE the path");
      });

    withMutant("M2 770a7e seed signed cmovg",
      (s) => s.replace(
        "  return sum > ISAAC_HUD_770A7E_CMOVA_MIN ? sum : 1u;",
        "  return (int64_t)(int32_t)sum > (int64_t)ISAAC_HUD_770A7E_CMOVA_MIN ? sum : 1u;"),
      () => {
        const e = loadExports();
        assert.equal(e.a7eSeed(0xfffffffe, 1) >>> 0, 0xffffffff,
          "0x770abc cmova is UNSIGNED above — sum 0xffffffff must stay");
      });

    withMutant("M3 770a7e seed cmova clamp dropped",
      (s) => s.replace(
        "  return sum > ISAAC_HUD_770A7E_CMOVA_MIN ? sum : 1u;",
        "  return sum;"),
      () => {
        const e = loadExports();
        const v = new DataView(e.memory.buffer);
        assert.equal(e.a7eSeed(0, 0) >>> 0, 1,
          "seed = max(sum, 1) — countB 0 + extra 0 must clamp to 1 (else the RNG would fatal)");
        e.a7ePlan(0x101, 9, 0, 0, a7ePlanOut);
        assert.equal(readU32(v, a7ePlanOut + A7E_PLAN.seed), 1,
          "plan seed must be the clamped 1");
      });

    withMutant("M4 770a7e table oob sentinel -> 0",
      (s) => s.replace(
        "    default: return ISAAC_HUD_770A7E_TABLE_OOB;",
        "    default: return 0u;"),
      () => {
        const e = loadExports();
        assert.equal(e.a7eTableEntry(6) >>> 0, 0xffffffff,
          "a bad draw index must be VISIBLE (0xffffffff), never a silent 0");
      });

    withMutant("M5 770915 hit threshold folded to <=",
      (s) => s.replace(
        "  return draw < ISAAC_HUD_770915_HIT_THRESHOLD ? 1 : 0;",
        "  return draw <= ISAAC_HUD_770915_HIT_THRESHOLD ? 1 : 0;"),
      () => {
        const e = loadExports();
        assert.equal(e.a915Hit(0x21), 0,
          "0x770967 jb is STRICT below — draw 0x21 is a miss");
      });

    withMutant("M6 770915 hit direction inverted (>=)",
      (s) => s.replace(
        "  return draw < ISAAC_HUD_770915_HIT_THRESHOLD ? 1 : 0;",
        "  return draw >= ISAAC_HUD_770915_HIT_THRESHOLD ? 1 : 0;"),
      () => {
        const e = loadExports();
        assert.equal(e.a915Hit(0x20), 1,
          "0x770967 jb — draw 0x20 is a hit");
      });

    withMutant("M7 770915 tail gate unsigned compare",
      (s) => s.replace(
        "  return (int64_t)(int32_t)game_26614 >=\n                 (int64_t)ISAAC_HUD_770915_GATE2_THRESHOLD\n             ? 1\n             : 0;",
        "  return (int64_t)(uint32_t)game_26614 >=\n                 (int64_t)ISAAC_HUD_770915_GATE2_THRESHOLD\n             ? 1\n             : 0;"),
      () => {
        const e = loadExports();
        assert.equal(e.a915TailGate(0xffffffff), 0,
          "0x770979 jl is SIGNED — (int32)-1 must CHAIN to 0x770a44");
      });

    withMutant("M8 770915 seed null-fold (always +0x58)",
      (s) => s.replace(
        "  return (p18300_4 != 0u) ? p18300_4_58 : 0u;",
        "  return p18300_4_58;"),
      () => {
        const e = loadExports();
        const v = new DataView(e.memory.buffer);
        assert.equal(e.a915Seed(0, 0x1234) >>> 0, 0,
          "0x77093d je 0x770942 — a null p18300_4 leaves seed 0 (FATAL)");
        e.a915Plan(9, 1, 0, 0x1234, 2, a915PlanOut);
        assert.equal(readI32(v, a915PlanOut + A915_PLAN.status),
          HUD_770915_STATUS_FATAL,
          "seed 0 makes the PE RNG int3 — the plan must report FATAL, never a draw verdict");
      });
  } finally {
    writeSourceRetry( original, "utf8");
  }
  assert.equal(readFileSync(source, "utf8"), original, "source restored");
  const exp = loadExports();
  const view = new DataView(exp.memory.buffer);
  assert.equal(exp.abi(), 39);
  assert.equal(exp.a7eOpen(0xffffffff), 0);
  assert.equal(exp.a7eSeed(0xfffffffe, 1) >>> 0, 0xffffffff);
  assert.equal(exp.a7eTableEntry(6) >>> 0, 0xffffffff);
  assert.equal(exp.a915Hit(0x21), 0);
  assert.equal(exp.a915TailGate(0xffffffff), 0);
  exp.a915Plan(9, 1, 0, 0x1234, 2, a915PlanOut);
  assert.equal(readI32(view, a915PlanOut + A915_PLAN.status), HUD_770915_STATUS_FATAL);
});

/* ============ ABI v26: HasCollectible 0x007706e0 tail true-chain ==========
   (0x770ba1 scalar [p+0x1fb8]==id gate — pure, full-dword — plus the
   pure DECISION laws of the recorded sampled tail gates 0x170/0x202c/
   0x1f84/0x9e0650/0x7307b0+0x9305f0/0x7911c0/0xbf/0x1e8).
   Evidence: section-notes/hud-v26-next/NOTES.md; cpu-dump/007706e0.txt.
   Host leaves stay samples (0x557b00, 0x9e0650, 0x7307b0, 0x9305f0 x2,
   0x7911c0, the 0x7706e0 recursion, 0x771200, the 0x5b1500 pair); the
   0x770c3e counter epilogue is the next frontier. */

test("header documents v26 0x007706e0 tail scalar gate (0x770ba1) + sampled tail-gate laws", () => {
  assert.equal(HUD_POST_UPDATE_PURE_ABI_VERSION, 39);
  const h = readFileSync(header, "utf8");
  assert.match(h, /Helpers ABI v26 \(0x007706e0\): the tail true-chain window/);
  assert.match(h, /ISAAC_HUD_770BA1_VA_GATE = 0x00770ba1u/);
  assert.match(h, /ISAAC_HUD_770BA1_VA_JE_TRUE = 0x00770badu/);
  assert.match(h, /ISAAC_HUD_770BA1_VA_JG_9E0650 = 0x00770bbdu/);
  assert.match(h, /ISAAC_HUD_770BA1_VA_JNS_7911C0 = 0x00770be9u/);
  assert.match(h, /ISAAC_HUD_770BA1_VA_JG_557B00 = 0x00770b9bu/);
  assert.match(h, /ISAAC_HUD_770BA1_VA_TEST_REC = 0x00770c01u/);
  assert.match(h, /ISAAC_HUD_770BA1_OFF_1FB8 = 0x1fb8u/);
  assert.match(h, /ISAAC_HUD_770BA1_HOST_VA_7911C0 = 0x007911c0u/);
  assert.match(h, /ISAAC_HUD_770BA1_REC_ID = 0xbfu/);
  assert.match(h, /ISAAC_HUD_770BA1_ID_1E8 = 0x1e8u/);
  assert.match(h, /int32_t isaac_hud_770ba1_scalar_gate\(uint32_t p_1fb8, uint32_t id\);/);
  assert.equal(HUD_770BA1_OFF_1FB8, 0x1fb8);
  assert.equal(HUD_770BA1_OFF_1390, 0x1390);
  assert.equal(HUD_770BA1_OFF_1388, 0x1388);
  assert.equal(HUD_770BA1_HOST_VA_9E0650, 0x009e0650);
  assert.equal(HUD_770BA1_HOST_VA_557B00, 0x00557b00);
  assert.equal(HUD_770BA1_HOST_VA_9305F0, 0x009305f0);
  assert.equal(HUD_770BA1_HOST_VA_7307B0, 0x007307b0);
  assert.equal(HUD_770BA1_HOST_VA_7911C0, 0x007911c0);
  assert.equal(HUD_770BA1_HOST_VA_771200, 0x00771200);
  assert.equal(HUD_770BA1_REC_ID, 0xbf);
  assert.equal(HUD_770BA1_ID_1E8, 0x1e8);
  assert.equal(HUD_770BA1_REC_FLAG, 0);
});

test("JS oracle: v26 0x007706e0 tail true-chain laws", () => {
  // scalar gate: FULL-dword equality behind a full-dword zero test —
  // p_1fb8 0 + id 0 is FALSE (0x770ba9 je skips the gate).
  assert.equal(hud770ba1ScalarGate(0, 0), 0, "null p_1fb8 skips the gate");
  assert.equal(hud770ba1ScalarGate(0, 5), 0);
  assert.equal(hud770ba1ScalarGate(5, 5), 1);
  assert.equal(hud770ba1ScalarGate(5, 6), 0);
  assert.equal(hud770ba1ScalarGate(0x100, 0), 0, "FULL dword — 0x100 != 0");
  assert.equal(hud770ba1ScalarGate(0xffffffff, 0xffffffff), 1);
  // byte pre-gates: LOW-BYTE (0x100 is false).
  assert.equal(hud770ba1Gate170(0), 0);
  assert.equal(hud770ba1Gate170(1), 1);
  assert.equal(hud770ba1Gate170(0x100), 0, "cmp byte — 0x100 is false");
  assert.equal(hud770ba1Gate170(0x1ff), 1);
  assert.equal(hud770ba1Gate202c(0), 0);
  assert.equal(hud770ba1Gate202c(0x100), 0);
  assert.equal(hud770ba1Gate202c(0x80), 1);
  // dword pre-gate: FULL word — 0x100 OPENS.
  assert.equal(hud770ba1Gate1f84(0), 0);
  assert.equal(hud770ba1Gate1f84(0x100), 1, "cmp dword — 0x100 opens");
  assert.equal(hud770ba1Gate1f84(0xffffffff), 1);
  // signed compares: wide case 0xffffffff must NOT open.
  assert.equal(hud770ba1Elem557b00Open(0), 0);
  assert.equal(hud770ba1Elem557b00Open(1), 1);
  assert.equal(hud770ba1Elem557b00Open(0xffffffff), 0, "SIGNED jg — (int32)-1 does not open");
  assert.equal(hud770ba19e0650Open(0), 0);
  assert.equal(hud770ba19e0650Open(1), 1);
  assert.equal(hud770ba19e0650Open(0xffffffff), 0, "SIGNED jg — (int32)-1 does not open");
  assert.equal(hud770ba17911c0Open(0), 1, "SIGNED jns — 0 opens");
  assert.equal(hud770ba17911c0Open(1), 1);
  assert.equal(hud770ba17911c0Open(-1), 0);
  assert.equal(hud770ba17911c0Open(0xffffffff), 0, "SIGNED jns — (int32)-1 does not open");
  // low-byte host results: 0x100 is false everywhere.
  assert.equal(hud770ba19305f0Open(0), 0);
  assert.equal(hud770ba19305f0Open(1), 1);
  assert.equal(hud770ba19305f0Open(0x100), 0, "test al,al — 0x100 is false");
  assert.equal(hud770ba1BfRecursiveOpen(0), 0);
  assert.equal(hud770ba1BfRecursiveOpen(0x100), 0);
  assert.equal(hud770ba1BfRecursiveOpen(0x1), 1);
  assert.equal(hud770ba19305f01e8Open(0), 0);
  assert.equal(hud770ba19305f01e8Open(0x100), 0);
  assert.equal(hud770ba19305f01e8Open(0xff), 1);
  // field equality gates: full-dword (sampled fields).
  assert.equal(hud770ba1Field1390Eq(0x1390, 0x1390), 1);
  assert.equal(hud770ba1Field1390Eq(0x100, 0), 0, "FULL dword — 0x100 != 0");
  assert.equal(hud770ba1Field1388Eq(0x1388, 0x1388), 1);
  assert.equal(hud770ba1Field1388Eq(0x100, 0), 0);
});

