test("JS oracle: v28 0x00771200 mode dispatch + case laws + tail gate", () => {
  // dispatch: FULL-dword switch over the 8 modes; 0x100000d != 0xd.
  assert.equal(hud771200ModeOpen(0), 0);
  assert.equal(hud771200ModeOpen(3), 0);
  assert.equal(hud771200ModeOpen(0xd), 1);
  assert.equal(hud771200ModeOpen(0xa), 1);
  assert.equal(hud771200ModeOpen(2), 1);
  assert.equal(hud771200ModeOpen(5), 1);
  assert.equal(hud771200ModeOpen(6), 1);
  assert.equal(hud771200ModeOpen(8), 1);
  assert.equal(hud771200ModeOpen(0xb), 1);
  assert.equal(hud771200ModeOpen(0x12), 1);
  assert.equal(hud771200ModeOpen(0x100000d), 0, "FULL dword dispatch — 0x100000d is not 0xd");
  assert.equal(hud771200ModeOpen(0xffffffff), 0);
  // room_game shared chain: room FULL dword == 2, g_game null, UNSIGNED
  // ja 26630 (0xffffffff OPENS), byte 26589 (0x100 FALSE).
  assert.equal(hud771200RoomGameOpen(2, 1, 0, 0), 0);
  assert.equal(hud771200RoomGameOpen(2, 1, 1, 0), 1);
  assert.equal(hud771200RoomGameOpen(2, 1, 0xffffffff, 0), 1, "UNSIGNED ja — 0xffffffff opens");
  assert.equal(hud771200RoomGameOpen(2, 1, 0, 1), 1);
  assert.equal(hud771200RoomGameOpen(2, 1, 0, 0x100), 0, "cmp byte — 0x100 is false");
  assert.equal(hud771200RoomGameOpen(2, 1, 0, 0xff), 1);
  assert.equal(hud771200RoomGameOpen(2, 0, 0xffffffff, 0), 0, "g_game null closes");
  assert.equal(hud771200RoomGameOpen(0x102, 1, 1, 0), 0, "FULL dword room — 0x102 != 2");
  assert.equal(hud771200RoomGameOpen(0, 1, 1, 0), 0);
  // case 0xd: FULL-dword id set {0x168, 0x19c}.
  assert.equal(hud771200CaseD(0x168), 1);
  assert.equal(hud771200CaseD(0x19c), 1);
  assert.equal(hud771200CaseD(0x169), 0);
  assert.equal(hud771200CaseD(0x10168), 0, "FULL dword — 0x10168 != 0x168");
  // case 0xa: id 0x139 FULL dword; byte[edi+0x132] LOW BYTE or room_game.
  assert.equal(hud771200CaseA(0x139, 1, 0, 0, 0, 0), 1);
  assert.equal(hud771200CaseA(0x139, 0x100, 0, 0, 0, 0), 0, "cmp byte — 0x100 is false");
  assert.equal(hud771200CaseA(0x139, 0x1ff, 0, 0, 0, 0), 1);
  assert.equal(hud771200CaseA(0x139, 0, 2, 1, 3, 0), 1, "room_game fallback");
  assert.equal(hud771200CaseA(0x139, 0, 2, 0, 3, 0), 0);
  assert.equal(hud771200CaseA(0x10139, 1, 0, 0, 0, 0), 0, "FULL dword — 0x10139 != 0x139");
  // cases 2/5/6: FULL-dword id sets.
  assert.equal(hud771200Case2(0x2e), 1);
  assert.equal(hud771200Case2(0x12e), 0);
  assert.equal(hud771200Case5(0x7a), 1);
  assert.equal(hud771200Case5(0x75), 1);
  assert.equal(hud771200Case5(0x76), 0);
  assert.equal(hud771200Case5(0x1075), 0, "FULL dword — 0x1075 != 0x75");
  assert.equal(hud771200Case6(0x9d), 1);
  assert.equal(hud771200Case6(0x19d), 0);
  // case 8: id 0xd6 FULL dword; byte[edi+0x183] LOW BYTE or room_game;
  // [g_game+0x26584] == 0 FULL dword (mode != 0xb reaches it).
  assert.equal(hud771200Case8(0xd6, 0, 0, 0, 0, 0, 0), 0);
  assert.equal(hud771200Case8(0xd6, 1, 0, 0, 0, 0, 0), 1, "byte alone opens");
  assert.equal(hud771200Case8(0xd6, 0x100, 0, 0, 0, 0, 0), 0, "cmp byte — 0x100 is false");
  assert.equal(hud771200Case8(0xd6, 1, 0, 0, 0, 0, 0x100), 0, "FULL dword — 26584 0x100 != 0");
  assert.equal(hud771200Case8(0xd6, 0, 2, 1, 0, 1, 0), 1, "room_game + 26584 clear");
  assert.equal(hud771200Case8(0xd6, 0, 2, 1, 0, 1, 1), 0, "26584 set closes");
  assert.equal(hud771200Case8(0x1d6, 1, 0, 0, 0, 0, 0), 0, "FULL dword — 0x1d6 != 0xd6");
  // case 0xb: same byte/room_game gate, NO 26584 test.
  assert.equal(hud771200CaseB(0xd6, 1, 0, 0, 0, 0), 1);
  assert.equal(hud771200CaseB(0xd6, 0, 2, 1, 0, 1), 1);
  assert.equal(hud771200CaseB(0xd6, 0, 2, 1, 0, 0x100), 0, "26589 byte 0x100 false");
  assert.equal(hud771200CaseB(0xd6, 0, 0, 0, 0, 0), 0);
  assert.equal(hud771200CaseB(0x1d6, 1, 0, 0, 0, 0), 0, "FULL dword — 0x1d6 != 0xd6");
  // case 0x12: id 0x248 FULL dword; 26584 not in {0x25, 0x26}.
  assert.equal(hud771200Case18(0x248, 0x24), 1);
  assert.equal(hud771200Case18(0x248, 0x25), 0, "26584 0x25 closes");
  assert.equal(hud771200Case18(0x248, 0x26), 0, "26584 0x26 closes");
  assert.equal(hud771200Case18(0x248, 0x1025), 1, "FULL dword — 0x1025 != 0x25");
  assert.equal(hud771200Case18(0x1248, 0x24), 0, "FULL dword — 0x1248 != 0x248");
  assert.equal(hud771200Case18(0x248, 0xffffffff), 1);
  // composed gate: dispatch + case; unknown modes FALSE.
  assert.equal(hud771200Gate({ id: 0x168, mode: 0xd }), 1);
  assert.equal(hud771200Gate({ id: 0x169, mode: 0xd }), 0);
  assert.equal(hud771200Gate({ id: 0x139, mode: 0xa, byte132: 0x100, room8: 0, gGame: 0, gGame26630: 0, gGame26589: 0 }), 0);
  assert.equal(hud771200Gate({ id: 0xd6, mode: 8, byte183: 1, room8: 0, gGame: 0, gGame26630: 0, gGame26589: 0, gGame26584: 0 }), 1);
  assert.equal(hud771200Gate({ id: 0xd6, mode: 8, byte183: 1, room8: 0, gGame: 0, gGame26630: 0, gGame26589: 0, gGame26584: 0x100 }), 0, "mode 8 needs 26584 clear");
  assert.equal(hud771200Gate({ id: 0xd6, mode: 0xb, byte183: 1, room8: 0, gGame: 0, gGame26630: 0, gGame26589: 0 }), 1, "mode 0xb has no 26584 test");
  assert.equal(hud771200Gate({ id: 0x248, mode: 0x12, gGame26584: 0x25 }), 0);
  assert.equal(hud771200Gate({ id: 0x248, mode: 0x12, gGame26584: 0x24 }), 1);
  assert.equal(hud771200Gate({ id: 0x2e, mode: 2 }), 1);
  assert.equal(hud771200Gate({ id: 0x75, mode: 5 }), 1);
  assert.equal(hud771200Gate({ id: 0x9d, mode: 6 }), 1);
  assert.equal(hud771200Gate({ id: 0x9d, mode: 3 }), 0, "dispatch default FALSE");
  assert.equal(hud771200Gate({ id: 0x9d, mode: 0x1000006 }), 0, "FULL dword dispatch");
  // 0x770ae2 tail gate: LOW-BYTE on both results; id 0x76 FULL dword.
  assert.equal(hud770ae2Open(0, 5, 0), 0);
  assert.equal(hud770ae2Open(1, 5, 0), 1, "0x771200 result opens");
  assert.equal(hud770ae2Open(0x100, 5, 0), 0, "test al,al — 0x100 is false");
  assert.equal(hud770ae2Open(0xff, 5, 0), 1);
  assert.equal(hud770ae2Open(0, 0x76, 0), 0);
  assert.equal(hud770ae2Open(0, 0x76, 1), 1, "0x9305f0(0x76) arm opens");
  assert.equal(hud770ae2Open(0, 0x76, 0x100), 0, "test al,al — 0x100 is false");
  assert.equal(hud770ae2Open(0, 0x176, 1), 0, "FULL dword — 0x176 != 0x76");
  assert.equal(hud770ae2Open(0, 0x1b6, 1), 0);
  assert.equal(hud770ae2Open(0, 0x76, 0x1ff), 1);
  // ---- 0x7711a0 VoidHasCollectible: FULL dword everywhere ----
  assert.equal(hud7711a0VoidSlotHit(0, 0, 0, 0), 0);
  assert.equal(hud7711a0VoidSlotHit(0x1dd, 0, 0, 0), 1);
  assert.equal(hud7711a0VoidSlotHit(0, 0x1dd, 0, 0), 1);
  assert.equal(hud7711a0VoidSlotHit(0, 0, 0x1dd, 0), 1);
  assert.equal(hud7711a0VoidSlotHit(0, 0, 0, 0x1dd), 1);
  assert.equal(hud7711a0VoidSlotHit(0x101dd, 0, 0, 0), 0, "FULL dword — 0x101dd != 0x1dd");
  assert.equal(hud7711a0VoidSlotHit(0x1de, 0, 0, 0), 0);
  assert.equal(hud7711a0VoidListGate(0), 0);
  assert.equal(hud7711a0VoidListGate(1), 1);
  assert.equal(hud7711a0VoidListGate(0x100), 1, "FULL dword count gate — 0x100 is open");
  assert.equal(hud7711a0VoidListGate(0xffffffff), 1);
  assert.equal(hud7711a0VoidElemHit(0x1dd, 0x1dd), 1);
  assert.equal(hud7711a0VoidElemHit(0x1dd, 0x101dd), 0, "FULL dword — 0x1dd != 0x101dd");
  assert.equal(hud7711a0VoidElemHit(0x101dd, 0x1dd), 0);
  assert.equal(hud7711a0VoidElemHit(0x5, 0x6), 0);
  assert.equal(hud7711a0VoidHas(0, 1, 1), 0, "no 0x1dd slot -> FALSE (0x7711c1)");
  assert.equal(hud7711a0VoidHas(1, 0, 1), 0, "empty list -> FALSE (0x7711df)");
  assert.equal(hud7711a0VoidHas(1, 1, 0), 0, "no elem match -> FALSE");
  assert.equal(hud7711a0VoidHas(1, 1, 1), 1, "slot + non-empty + elem match -> TRUE");
  assert.equal(hud7711a0VoidHas(1, 0x100, 1), 1);
});

