test("JS oracle: v29 0x00771410 walk bounds + per-iteration dispatch + tail", () => {
  // walk bound: SIGNED jl — (int32)id < 0x2dd; 0xffffffff = -1 CONTINUES.
  assert.equal(hud771410WalkContinue(0), 1);
  assert.equal(hud771410WalkContinue(0x2dc), 1);
  assert.equal(hud771410WalkContinue(0x2dd), 0);
  assert.equal(hud771410WalkContinue(0x2de), 0);
  assert.equal(hud771410WalkContinue(0xffffffff), 1, "SIGNED jl — (int32)-1 continues");
  assert.equal(hud771410WalkContinue(0x80000000), 1, "SIGNED jl — (int32)-0x80000000 continues");
  assert.equal(hud771410WalkContinue(0x1000002dd), 0, "FULL dword — 0x1000002dd wraps to 0x2dd");
  // path A: LOW-BYTE of the 0x771200 result (0x100 CLOSED).
  assert.equal(hud771410PathAOpen(0), 0);
  assert.equal(hud771410PathAOpen(1), 1);
  assert.equal(hud771410PathAOpen(0xff), 1);
  assert.equal(hud771410PathAOpen(0x100), 0, "test al,al — 0x100 is false");
  // edition gate: FULL dword != 0x2b.
  assert.equal(hud771410EditionGate(0x2b), 0);
  assert.equal(hud771410EditionGate(0x2a), 1);
  assert.equal(hud771410EditionGate(0x12b), 1, "FULL dword — 0x12b != 0x2b opens");
  assert.equal(hud771410EditionGate(0xffffffff), 1);
  // challenge gate: FULL dword == 0x1e4 (0x733ff0 edge).
  assert.equal(hud771410ChallengeGate(0x1e4), 1);
  assert.equal(hud771410ChallengeGate(0x1e5), 0);
  assert.equal(hud771410ChallengeGate(0x11e4), 0, "FULL dword — 0x11e4 != 0x1e4");
  // bit set: edition open && id UNSIGNED < bitset_count (jae).
  assert.equal(hud771410BitSetOpen(0x2a, 0, 1), 1);
  assert.equal(hud771410BitSetOpen(0x2a, 1, 1), 0);
  assert.equal(hud771410BitSetOpen(0x2b, 0, 1), 0, "edition 0x2b closes the arm");
  assert.equal(hud771410BitSetOpen(0x2a, 0x80000000, 0x80000001), 1, "UNSIGNED jae — 0x80000000 < 0x80000001");
  assert.equal(hud771410BitSetOpen(0x2a, 0xffffffff, 0), 0, "UNSIGNED — 0xffffffff >= 0");
  // bit word: index masked to [0,31]; FULL-dword word.
  assert.equal(hud771410BitWord(0, 0), 1);
  assert.equal(hud771410BitWord(0, 0x1f), 0x80000000);
  assert.equal(hud771410BitWord(0, 0x20), 1, "and ecx,0x1f — id 0x20 sets bit 0");
  assert.equal(hud771410BitWord(0, 0x21), 2);
  assert.equal(hud771410BitWord(0x10, 4), 0x10, "bts — already-set bit unchanged");
  // bit addr: bits_ptr + (id >> 5) * 4 (dword stride, wrap).
  assert.equal(hud771410BitAddr(0x1000, 0), 0x1000);
  assert.equal(hud771410BitAddr(0x1000, 0x20), 0x1004);
  assert.equal(hud771410BitAddr(0, 0x3f), 4);
  assert.equal(hud771410BitAddr(0xfffffff0, 0x20), 0xfffffff4);
  // room count: sar(end-begin, 2) — arithmetic.
  assert.equal(hud771410RoomCountSar(0, 8), 2);
  assert.equal(hud771410RoomCountSar(0, 7), 1);
  assert.equal(hud771410RoomCountSar(0x100, 0), 0xffffffc0, "negative span stays negative");
  assert.equal(hud771410RoomCountSar(0, 0), 0);
  // room fire: SIGNED jge — (int32)id < (int32)count.
  assert.equal(hud771410RoomFireOpen(1, 0), 1);
  assert.equal(hud771410RoomFireOpen(1, 1), 0);
  assert.equal(hud771410RoomFireOpen(0, 0xffffffff), 1, "SIGNED — -1 < 0 fires");
  assert.equal(hud771410RoomFireOpen(0xffffffff, 0x80000000), 1, "SIGNED — -0x80000000 < -1 fires");
  assert.equal(hud771410RoomFireOpen(0, 0), 0);
  // elem: FULL dword != 0.
  assert.equal(hud771410ElemFireOpen(0), 0);
  assert.equal(hud771410ElemFireOpen(1), 1);
  assert.equal(hud771410ElemFireOpen(0x100), 1, "test eax,eax — FULL dword");
  // hc/trinket skips: LOW-BYTE (0x100 CLOSED).
  assert.equal(hud771410HcSkipOpen(0), 0);
  assert.equal(hud771410HcSkipOpen(1), 1);
  assert.equal(hud771410HcSkipOpen(0x100), 0, "test al,al — 0x100 does NOT skip");
  assert.equal(hud771410TrinketSkipOpen(0), 0);
  assert.equal(hud771410TrinketSkipOpen(0x100), 0);
  assert.equal(hud771410TrinketSkipOpen(0xff), 1);
  // list fire: FULL dword != 0.
  assert.equal(hud771410ListFireOpen(0), 0);
  assert.equal(hud771410ListFireOpen(0x100), 1, "test eax,eax — FULL dword fires 0x75d850");
  // tail: mode FULL dword == 5; large gate SIGNED on the masked span.
  assert.equal(hud771410TailFire(5), 1);
  assert.equal(hud771410TailFire(0x105), 0, "FULL dword — 0x105 != 5");
  assert.equal(hud771410TailFire(4), 0);
  assert.equal(hud771410TailLargeGate(0, 0x200), 1);
  assert.equal(hud771410TailLargeGate(0, 0x1e8), 0, "0x1e8 not > 0x1e8");
  assert.equal(hud771410TailLargeGate(0, 0x1e9), 0, "and 0xfffffffc — 0x1e9 masks to 0x1e8");
  assert.equal(hud771410TailLargeGate(0, 0x1ec), 1);
  assert.equal(hud771410TailLargeGate(0x100, 0), 0, "negative span stays negative");
  assert.equal(hud771410TailLargeGate(0, 0x7ffffffc), 1);
  assert.equal(hud771410TailArg(7, 0, 0x200), 7, "large path -> dword[begin+0x1e8]");
  assert.equal(hud771410TailArg(7, 0, 0x1e8), 0, "small path -> 0");
  assert.equal(hud771410TailArg(0x123, 0, 0x1e9), 0, "0x1e9 masks to 0x1e8 -> 0");
  assert.equal(hud771410SpanMasked(0, 0x1e9), 0x1e8);
  assert.equal(hud771410SpanMasked(0x100, 0), 0xffffff00);
  // composed per-iteration mask
  assert.equal(hud771410IterMask({
    id: 0x1e4, r771200: 1, gGame26584: 0x2a, bitsetCount: 0x200,
    roomCount: 0x2dd, elem: 5, r7706e0: 0, r9305f0: 0, r72fd10: 0,
  }), 7, "path A: bit store + 0x733ff0 + 0x75d1d0");
  assert.equal(hud771410IterMask({
    id: 0x1e4, r771200: 1, gGame26584: 0x2b, bitsetCount: 0x200,
    roomCount: 0x2dd, elem: 5, r7706e0: 0, r9305f0: 0, r72fd10: 0,
  }), 4, "edition 0x2b: NO store/call, room fire still fires");
  assert.equal(hud771410IterMask({
    id: 0x1e4, r771200: 1, gGame26584: 0x2a, bitsetCount: 0x200,
    roomCount: 0x100, elem: 5, r7706e0: 0, r9305f0: 0, r72fd10: 0,
  }), 3, "room fire closed (0x1e4 >= 0x100 count)");
  assert.equal(hud771410IterMask({
    id: 5, r771200: 0, gGame26584: 0, bitsetCount: 0,
    roomCount: 0, elem: 0, r7706e0: 1, r9305f0: 0, r72fd10: 0,
  }), 8, "path B: 0x7706e0 always; LOW(r3) skip stops");
  assert.equal(hud771410IterMask({
    id: 5, r771200: 0, gGame26584: 0, bitsetCount: 0,
    roomCount: 0, elem: 0, r7706e0: 0, r9305f0: 0x100, r72fd10: 0,
  }), 0x38, "LOW(r4) 0x100 does NOT skip — the 0x72fd10 edge fires (byte gate closed)");
  assert.equal(hud771410IterMask({
    id: 5, r771200: 0, gGame26584: 0, bitsetCount: 0,
    roomCount: 0, elem: 0, r7706e0: 0, r9305f0: 0, r72fd10: 0,
  }), 8 | 0x10 | 0x20, "path B closed: 7706e0 + 9305f0 + 72fd10, no 75d850");
  assert.equal(hud771410IterMask({
    id: 5, r771200: 0, gGame26584: 0, bitsetCount: 0,
    roomCount: 0, elem: 0, r7706e0: 0, r9305f0: 0, r72fd10: 0x100,
  }), 8 | 0x10 | 0x20 | 0x40, "path B full: r5 0x100 fires 0x75d850 (FULL dword)");
  assert.equal(hud771410IterMask({
    id: 0, r771200: 0x100, gGame26584: 0x2a, bitsetCount: 1,
    roomCount: 1, elem: 1, r7706e0: 0, r9305f0: 0, r72fd10: 0,
  }), 0x38, "LOW(r1) 0x100 closed -> path B: the 7706e0+9305f0+72fd10 edges fire even with zero results");
});

